import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";

// Get all player login activity
export async function GET(request: NextRequest) {
  try {
    const user = await getCurrentUser();
    if (!user) {
      return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
    }

    // Check if user is admin/coach
    const isAdmin = user.role === "Head coach" || user.role === "Head analyst" || user.role === "Admin";
    if (!isAdmin) {
      return NextResponse.json({ ok: false, message: "Forbidden" }, { status: 403 });
    }

    // Get user's team IDs to filter players
    const userTeams = await prisma.userTeam.findMany({
      where: { userId: user.id, status: "active" },
      select: { teamId: true },
    });

    const createdTeams = await prisma.team.findMany({
      where: { createdById: user.id },
      select: { id: true },
    });

    const userTeamIds = [
      ...userTeams.map((ut) => ut.teamId),
      ...createdTeams.map((t) => t.id),
    ];

    // Build WHERE clause for team filtering
    const teamFilter = userTeamIds.length > 0 
      ? `AND p.teamId IN (${userTeamIds.join(',')})`
      : `AND 1=0`; // No teams = no players

    // Use raw SQL query to get players with login tracking
    // Filter by user's teams
    const playersRaw = await prisma.$queryRawUnsafe<Array<{
      id: number;
      name: string;
      email: string | null;
      position: string;
      number: number | null;
      lastLoginAt: Date | null;
      isOnline: number; // SQLite returns 0/1
      teamId: number | null;
      teamName: string | null;
    }>>(`
      SELECT 
        p.id,
        p.name,
        p.email,
        p.position,
        p.number,
        p.lastLoginAt,
        p.isOnline,
        t.id as teamId,
        t.name as teamName
      FROM Player p
      LEFT JOIN Team t ON p.teamId = t.id
      WHERE p.email IS NOT NULL
      ${teamFilter}
      ORDER BY p.isOnline DESC, p.lastLoginAt DESC
    `);

    const players = playersRaw.map((p) => ({
      id: p.id,
      name: p.name,
      email: p.email,
      position: p.position,
      number: p.number,
      lastLoginAt: p.lastLoginAt,
      isOnline: p.isOnline === 1,
      team: p.teamId && p.teamName ? { id: p.teamId, name: p.teamName } : null,
    }));

    return NextResponse.json({
      ok: true,
      players: players.map((p) => ({
        id: p.id,
        name: p.name,
        email: p.email,
        position: p.position,
        number: p.number,
        team: p.team,
        lastLoginAt: p.lastLoginAt ? (p.lastLoginAt instanceof Date ? p.lastLoginAt.toISOString() : String(p.lastLoginAt)) : null,
        isOnline: p.isOnline,
        status: p.isOnline ? "Online" : p.lastLoginAt ? "Offline" : "Never logged in",
      })),
    });
  } catch (error) {
    console.error("[admin/player-logins] Error:", error);
    return NextResponse.json(
      { ok: false, message: error instanceof Error ? error.message : "Failed to fetch player logins" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";

// Get all staff members (with team memberships)
export async function GET(request: NextRequest) {
  try {
    const user = await getCurrentUser();
    if (!user) {
      return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
    }

    // Check if user is admin or head coach
    const isAdmin = user.role === "Admin" || user.role === "Head Coach";

    if (!isAdmin) {
      return NextResponse.json({ ok: false, message: "Forbidden" }, { status: 403 });
    }

    const searchParams = request.nextUrl.searchParams;
    const teamId = searchParams.get("teamId");

    const where: any = {};
    if (teamId) {
      where.teamMemberships = {
        some: {
          teamId: parseInt(teamId),
        },
      };
    }

    const users = await prisma.user.findMany({
      where,
      include: {
        teamMemberships: {
          include: {
            team: {
              select: {
                id: true,
                name: true,
                league: true,
              },
            },
          },
        },
        createdTeams: {
          select: {
            id: true,
            name: true,
          },
        },
      },
      orderBy: {
        createdAt: "desc",
      },
    });

    return NextResponse.json({ ok: true, staff: users });
  } catch (error) {
    console.error("[admin/staff] Error:", error);
    return NextResponse.json(
      { ok: false, message: error instanceof Error ? error.message : "Internal server error" },
      { status: 500 }
    );
  }
}

// Invite staff member to team
export async function POST(request: NextRequest) {
  try {
    const user = await getCurrentUser();
    if (!user) {
      return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
    }

    const body = await request.json();
    const { email, teamId, role } = body;

    if (!email || !teamId || !role) {
      return NextResponse.json(
        { ok: false, message: "Email, teamId, and role are required" },
        { status: 400 }
      );
    }

    // Check if user has permission (must be team owner or admin)
    const team = await prisma.team.findUnique({
      where: { id: parseInt(teamId) },
      include: {
        members: true,
      },
    });

    if (!team) {
      return NextResponse.json({ ok: false, message: "Team not found" }, { status: 404 });
    }

    const isTeamOwner = team.createdById === user.id;
    const isUserMember = team.members.some((m) => m.userId === user.id && m.role === "Head Coach");
    const isAdmin = user.role === "Admin";

    if (!isTeamOwner && !isUserMember && !isAdmin) {
      return NextResponse.json(
        { ok: false, message: "You don't have permission to invite members to this team" },
        { status: 403 }
      );
    }

    // Find or create user
    let targetUser = await prisma.user.findUnique({ where: { email } });

    if (!targetUser) {
      // User doesn't exist - create invitation (for now, just create user without password)
      // In production, you'd send an invitation email
      return NextResponse.json(
        { ok: false, message: "User not found. They need to register first." },
        { status: 404 }
      );
    }

    // Check if user is already a member
    const existingMembership = await prisma.userTeam.findUnique({
      where: {
        userId_teamId: {
          userId: targetUser.id,
          teamId: parseInt(teamId),
        },
      },
    });

    if (existingMembership) {
      return NextResponse.json(
        { ok: false, message: "User is already a member of this team" },
        { status: 409 }
      );
    }

    // Add user to team
    const membership = await prisma.userTeam.create({
      data: {
        userId: targetUser.id,
        teamId: parseInt(teamId),
        role: role,
        invitedBy: user.id,
        status: "active",
      },
      include: {
        user: {
          select: {
            id: true,
            name: true,
            email: true,
            role: true,
          },
        },
        team: {
          select: {
            id: true,
            name: true,
          },
        },
      },
    });

    return NextResponse.json({ ok: true, membership }, { status: 201 });
  } catch (error) {
    console.error("[admin/staff] Error:", error);
    return NextResponse.json(
      { ok: false, message: error instanceof Error ? error.message : "Internal server error" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";

// Upload player statistics via CSV
export async function POST(request: NextRequest) {
  try {
    const user = await getCurrentUser();
    if (!user) {
      return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
    }

    // Check if user is admin/coach
    const isAdmin = user.role === "Head coach" || user.role === "Head analyst" || user.role === "Admin";
    if (!isAdmin) {
      return NextResponse.json({ ok: false, message: "Forbidden" }, { status: 403 });
    }

    const formData = await request.formData();
    const file = formData.get("file") as File;

    if (!file) {
      return NextResponse.json({ ok: false, message: "No file provided" }, { status: 400 });
    }

    // Read file content
    const text = await file.text();
    const lines = text.split("\n").filter((line) => line.trim());

    if (lines.length < 2) {
      return NextResponse.json({ ok: false, message: "CSV file is empty or invalid" }, { status: 400 });
    }

    // Parse CSV header
    const header = lines[0].split(",").map((h) => h.trim().toLowerCase());
    const playerIdIndex = header.findIndex((h) => h.includes("player") && h.includes("id"));
    const goalsIndex = header.findIndex((h) => h.includes("goal"));
    const assistsIndex = header.findIndex((h) => h.includes("assist"));
    const xgIndex = header.findIndex((h) => h.toLowerCase() === "xg");
    const xagIndex = header.findIndex((h) => h.toLowerCase() === "xag");
    const shotsPer90Index = header.findIndex((h) => h.toLowerCase().includes("shots") && h.includes("90"));
    const keyPassesPer90Index = header.findIndex((h) => h.toLowerCase().includes("key") && h.includes("pass"));
    const pressuresPer90Index = header.findIndex((h) => h.toLowerCase().includes("pressure"));
    const progressivePassesPer90Index = header.findIndex((h) => h.toLowerCase().includes("progressive"));
    const carriesIndex = header.findIndex((h) => h.toLowerCase().includes("carries"));
    const defensiveDuelsIndex = header.findIndex((h) => h.toLowerCase().includes("defensive") && h.includes("duel"));

    if (playerIdIndex === -1) {
      return NextResponse.json({ ok: false, message: "CSV must contain 'Player ID' column" }, { status: 400 });
    }

    let updated = 0;
    const errors: string[] = [];

    // Process each row
    for (let i = 1; i < lines.length; i++) {
      const values = lines[i].split(",").map((v) => v.trim());
      const playerId = parseInt(values[playerIdIndex]);

      if (isNaN(playerId)) {
        errors.push(`Row ${i + 1}: Invalid player ID`);
        continue;
      }

      // Verify player exists
      const player = await prisma.player.findUnique({
        where: { id: playerId },
      });

      if (!player) {
        errors.push(`Row ${i + 1}: Player ${playerId} not found`);
        continue;
      }

      // Parse values
      const goals = goalsIndex !== -1 ? parseFloat(values[goalsIndex]) || 0 : null;
      const assists = assistsIndex !== -1 ? parseFloat(values[assistsIndex]) || 0 : null;
      const xg = xgIndex !== -1 ? parseFloat(values[xgIndex]) || 0 : null;
      const xag = xagIndex !== -1 ? parseFloat(values[xagIndex]) || 0 : null;
      const shotsPer90 = shotsPer90Index !== -1 ? parseFloat(values[shotsPer90Index]) || 0 : null;
      const keyPassesPer90 = keyPassesPer90Index !== -1 ? parseFloat(values[keyPassesPer90Index]) || 0 : null;
      const pressuresPer90 = pressuresPer90Index !== -1 ? parseFloat(values[pressuresPer90Index]) || 0 : null;
      const progressivePassesPer90 = progressivePassesPer90Index !== -1 ? parseFloat(values[progressivePassesPer90Index]) || 0 : null;
      const carriesIntoFinalThirdPer90 = carriesIndex !== -1 ? parseFloat(values[carriesIndex]) || 0 : null;
      const defensiveDuelsWonPer90 = defensiveDuelsIndex !== -1 ? parseFloat(values[defensiveDuelsIndex]) || 0 : null;

      // Update player stats using raw SQL
      try {
        await prisma.$executeRawUnsafe(
          `UPDATE Player SET 
            goals = COALESCE(?, goals),
            assists = COALESCE(?, assists),
            xg = COALESCE(?, xg),
            xag = COALESCE(?, xag),
            shotsPer90 = COALESCE(?, shotsPer90),
            keyPassesPer90 = COALESCE(?, keyPassesPer90),
            pressuresPer90 = COALESCE(?, pressuresPer90),
            progressivePassesPer90 = COALESCE(?, progressivePassesPer90),
            carriesIntoFinalThirdPer90 = COALESCE(?, carriesIntoFinalThirdPer90),
            defensiveDuelsWonPer90 = COALESCE(?, defensiveDuelsWonPer90),
            updatedAt = CURRENT_TIMESTAMP
          WHERE id = ?`,
          goals,
          assists,
          xg,
          xag,
          shotsPer90,
          keyPassesPer90,
          pressuresPer90,
          progressivePassesPer90,
          carriesIntoFinalThirdPer90,
          defensiveDuelsWonPer90,
          playerId
        );
        updated++;
      } catch (error) {
        errors.push(`Row ${i + 1}: Failed to update player ${playerId}`);
      }
    }

    return NextResponse.json({
      ok: true,
      updated,
      errors: errors.length > 0 ? errors : undefined,
      message: `Successfully updated ${updated} players${errors.length > 0 ? ` (${errors.length} errors)` : ""}`,
    });
  } catch (error) {
    console.error("[admin/upload-stats] Error:", error);
    return NextResponse.json(
      { ok: false, message: error instanceof Error ? error.message : "Failed to upload statistics" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { createSession, setSessionCookie } from "@/lib/auth";
import { scryptSync, randomBytes, timingSafeEqual } from "crypto";

export const runtime = "nodejs";

function verifyPassword(password: string, stored: string): boolean {
  const [salt, hash] = stored.split(":");
  if (!salt || !hash) return false;
  const derived = scryptSync(password, salt, 64).toString("hex");
  const hashBuf = Buffer.from(hash, "hex");
  const derivedBuf = Buffer.from(derived, "hex");
  return timingSafeEqual(hashBuf, derivedBuf);
}

export async function POST(request: NextRequest) {
  try {
    const body = (await request.json().catch(() => null)) as { email?: string; password?: string } | null;

    if (!body?.email || !body?.password) {
      return NextResponse.json({ ok: false, message: "Missing credentials" }, { status: 400 });
    }

    const { email, password } = body;

    const player = await prisma.player.findUnique({ 
      where: { email },
      include: {
        team: {
          select: { id: true, name: true },
        },
      },
    });

    if (!player || !player.passwordHash || !verifyPassword(password, player.passwordHash)) {
      return NextResponse.json({ ok: false, message: "Invalid email or password" }, { status: 401 });
    }

    // Create session for player
    const session = await createSession({
      userId: player.id,
      email: player.email || "",
      name: player.name,
      role: "Player",
    }, 30); // 30 days

    const maxAge = 60 * 60 * 24 * 30; // 30 days in seconds

    const response = NextResponse.json({
      ok: true,
      player: {
        id: player.id,
        email: player.email,
        name: player.name,
        position: player.position,
        team: player.team,
      },
      message: "Login successful",
    });

    // Set cookie in response headers (same as regular login)
    response.cookies.set("session", session, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      maxAge,
      path: "/",
    });

    return response;
  } catch (error) {
    console.error("[player-login] Error:", error);
    return NextResponse.json(
      { ok: false, message: error instanceof Error ? error.message : "Login failed" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { createSession, setSessionCookie } from "@/lib/auth";
import { sendVerificationEmail } from "@/lib/email";
import { randomBytes, scryptSync } from "node:crypto";

export const runtime = "nodejs";

function hashPassword(password: string): string {
  const salt = randomBytes(16).toString("hex");
  const hash = scryptSync(password, salt, 64).toString("hex");
  return `${salt}:${hash}`;
}

export async function POST(request: Request) {
  const body = (await request.json().catch(() => null)) as {
    name?: string;
    club?: string;
    email?: string;
    password?: string;
    role?: string;
  } | null;

  if (!body?.email || !body?.password) {
    return NextResponse.json({ ok: false, message: "Email and password are required" }, { status: 400 });
  }

  const { email, password, name, club, role } = body;

  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing) {
    return NextResponse.json({ ok: false, message: "A user with this email already exists" }, { status: 409 });
  }

  // Create user with selected role (default to "Head Coach" if not provided)
  const userRole = role || "Head Coach";

  // Create user and team in a transaction
  const result = await prisma.$transaction(async (tx) => {
    // Create user
    const user = await tx.user.create({
      data: {
        email,
        name,
        role: userRole,
        passwordHash: hashPassword(password),
      },
    });

    // Create team if club name is provided
    let team = null;
    if (club && club.trim()) {
      team = await tx.team.create({
        data: {
          name: club.trim(),
          createdById: user.id,
        },
      });

      // Add user to team as Head Coach (or selected role)
      // Check if UserTeam model exists (after migration)
      try {
        await tx.userTeam.create({
          data: {
            userId: user.id,
            teamId: team.id,
            role: userRole,
            status: "active",
          },
        });
      } catch (error: any) {
        // If UserTeam doesn't exist yet (before migration), just log and continue
        // The team is still created, user just won't be in UserTeam table yet
        console.warn("[register] UserTeam model not available yet. Run migration to enable staff management.");
      }
    }

    return { user, team };
  });

  const { user, team } = result;

  const token = randomBytes(32).toString("hex");
  const expiresAt = new Date(Date.now() + 1000 * 60 * 60 * 24); // 24 hours
  await prisma.emailVerificationToken.create({
    data: {
      token,
      userId: user.id,
      expiresAt,
    },
  });

  // Send verification email
  const emailResult = await sendVerificationEmail(user.email, token, user.name || undefined);
  if (!emailResult.success) {
    console.error("[register] Failed to send verification email:", emailResult.error);
    // Continue anyway, user can request resend
  }

  // Auto-login after registration
  const session = await createSession({
    userId: user.id,
    email: user.email,
    name: user.name,
    role: user.role,
  });

  const response = NextResponse.json({
    ok: true,
    user: {
      id: user.id,
      email: user.email,
      name: user.name,
      role: user.role,
    },
    team: team ? {
      id: team.id,
      name: team.name,
    } : null,
    message: team 
      ? "Account and team created successfully. Please verify your email."
      : "Account created successfully. Please verify your email.",
  });

  await setSessionCookie(session);

  return response;
}

import { NextRequest, NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { writeFile, mkdir } from "fs/promises";
import { join } from "path";
import { existsSync } from "fs";
import Papa from "papaparse";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";

export const runtime = "nodejs";

export async function POST(request: NextRequest) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
  }

  try {
    const searchParams = request.nextUrl.searchParams;
    const source = searchParams.get("source") || "matches";
    const format = searchParams.get("format") || "csv";
    const matchId = searchParams.get("matchId");

    // Get user's team IDs to filter
    const userTeams = await prisma.userTeam.findMany({
      where: { userId: user.id, status: "active" },
      select: { teamId: true },
    });

    const createdTeams = await prisma.team.findMany({
      where: { createdById: user.id },
      select: { id: true },
    });

    const userTeamIds = [
      ...userTeams.map((ut) => ut.teamId),
      ...createdTeams.map((t) => t.id),
    ];

    if (userTeamIds.length === 0) {
      return NextResponse.json({ ok: false, message: "No teams found. Create a team first." }, { status: 400 });
    }

    let data: any[] = [];
    let filename = "";

    if (source === "matches") {
      if (matchId) {
        // Export single match events
        const match = await prisma.match.findUnique({
          where: { id: parseInt(matchId) },
          include: {
            homeTeam: true,
            awayTeam: true,
            events: {
              include: { player: true },
            },
          },
        });

        if (!match) {
          return NextResponse.json({ ok: false, message: "Match not found" }, { status: 404 });
        }

        // Verify user has access to this match
        const hasAccess = (match.homeTeamId && userTeamIds.includes(match.homeTeamId)) ||
                         (match.awayTeamId && userTeamIds.includes(match.awayTeamId));

        if (!hasAccess) {
          return NextResponse.json({ ok: false, message: "You don't have access to this match" }, { status: 403 });
        }

        data = match.events.map((event) => ({
          minute: event.minute,
          type: event.type,
          player: event.player?.name || "Unknown",
          team: event.team,
          x: event.x,
          y: event.y,
          xg: event.xg,
          metadata: event.metadata,
        }));
        filename = `match-${matchId}-events`;
      } else {
        // Export all matches from user's teams
        const matches = await prisma.match.findMany({
          where: {
            OR: [
              { homeTeamId: { in: userTeamIds } },
              { awayTeamId: { in: userTeamIds } },
            ],
          },
          include: {
            homeTeam: true,
            awayTeam: true,
          },
          orderBy: { date: "desc" },
        });
        data = matches.map((match) => ({
          id: match.id,
          date: new Date(match.date).toLocaleDateString("en-GB"),
          competition: match.competition,
          venue: match.venue || "",
          homeTeam: match.homeTeam?.name || "Unknown",
          awayTeam: match.awayTeam?.name || "Unknown",
          scoreHome: match.scoreHome ?? "",
          scoreAway: match.scoreAway ?? "",
          xgHome: match.xgHome ?? "",
          xgAway: match.xgAway ?? "",
        }));
        filename = "all-matches";
      }
    } else if (source === "players") {
      const players = await prisma.player.findMany({
        where: {
          teamId: { in: userTeamIds },
        },
        include: { team: true },
        orderBy: { name: "asc" },
      });
      data = players.map((player) => ({
        id: player.id,
        name: player.name,
        position: player.position,
        age: player.age ?? "",
        club: player.club || "",
        nationality: player.nationality || "",
        team: player.team?.name || "No team",
        goals: player.goals ?? 0,
        assists: player.assists ?? 0,
        xg: player.xg ?? 0,
        xag: player.xag ?? 0,
      }));
      filename = "all-players";
    } else if (source === "statistics") {
      // Export aggregated statistics - only from user's teams
      const [matches, players, teams] = await Promise.all([
        prisma.match.findMany({
          where: {
            OR: [
              { homeTeamId: { in: userTeamIds } },
              { awayTeamId: { in: userTeamIds } },
            ],
          },
          include: { homeTeam: true, awayTeam: true },
        }),
        prisma.player.findMany({
          where: {
            teamId: { in: userTeamIds },
          },
          include: { team: true },
        }),
        prisma.team.findMany({
          where: {
            id: { in: userTeamIds },
          },
        }),
      ]);

      // Calculate statistics
      const totalMatches = matches.length;
      const totalPlayers = players.length;
      const totalTeams = teams.length;
      const totalGoals = matches.reduce((sum, m) => sum + (m.scoreHome ?? 0) + (m.scoreAway ?? 0), 0);
      const totalXG = matches.reduce((sum, m) => sum + (m.xgHome ?? 0) + (m.xgAway ?? 0), 0);

      data = [
        { metric: "Total Matches", value: totalMatches },
        { metric: "Total Players", value: totalPlayers },
        { metric: "Total Teams", value: totalTeams },
        { metric: "Total Goals", value: totalGoals },
        { metric: "Total xG", value: totalXG.toFixed(2) },
        { metric: "Average Goals per Match", value: totalMatches > 0 ? (totalGoals / totalMatches).toFixed(2) : 0 },
        { metric: "Average xG per Match", value: totalMatches > 0 ? (totalXG / totalMatches).toFixed(2) : 0 },
      ];
      filename = "statistics-summary";
    } else if (source === "squad") {
      const players = await prisma.player.findMany({
        where: {
          teamId: { in: userTeamIds },
        },
        include: { team: true },
      });
      data = players.map((player) => ({
        name: player.name,
        position: player.position,
        age: player.age,
        club: player.club,
        nationality: player.nationality,
        team: player.team?.name || "No team",
      }));
      filename = "squad-metrics";
    }

    if (data.length === 0) {
      return NextResponse.json({ ok: false, message: "No data to export" }, { status: 400 });
    }

    // Create exports directory
    const exportsDir = join(process.cwd(), "public", "exports");
    if (!existsSync(exportsDir)) {
      await mkdir(exportsDir, { recursive: true });
    }

    let fileContent: string | Buffer;
    let fileExtension: string;
    const timestamp = Date.now();
    const finalFilename = `${filename}-${timestamp}`;

    if (format === "csv") {
      fileContent = Papa.unparse(data);
      fileExtension = "csv";
    } else if (format === "json") {
      fileContent = JSON.stringify(data, null, 2);
      fileExtension = "json";
    } else if (format === "pdf") {
      // Generate a polished landscape PDF
      const doc = new jsPDF({ orientation: "landscape", unit: "mm", format: "a4" });
      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      const marginX = 12;

      // ----- Header band -----
      const accentColor: [number, number, number] = [16, 185, 129]; // emerald
      const ink: [number, number, number] = [15, 23, 42]; // slate-900
      const muted: [number, number, number] = [100, 116, 139]; // slate-500

      doc.setFillColor(...accentColor);
      doc.rect(0, 0, pageWidth, 4, "F");

      doc.setFillColor(245, 247, 250);
      doc.rect(0, 4, pageWidth, 22, "F");

      // Brand mark
      doc.setFillColor(...accentColor);
      doc.circle(marginX + 4, 15, 4, "F");
      doc.setTextColor(255, 255, 255);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(9);
      doc.text("S", marginX + 2.5, 16.5);

      // Title and meta
      const prettyTitle = filename.replace(/-/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
      doc.setTextColor(...ink);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(16);
      doc.text(prettyTitle, marginX + 14, 14);

      doc.setFont("helvetica", "normal");
      doc.setFontSize(9);
      doc.setTextColor(...muted);
      const exportedAt = new Date();
      doc.text(
        `Exported ${exportedAt.toLocaleDateString("en-GB")} ${exportedAt.toLocaleTimeString("en-GB", {
          hour: "2-digit",
          minute: "2-digit",
        })}  ·  ${data.length} row${data.length === 1 ? "" : "s"}  ·  Source: ${source}`,
        marginX + 14,
        20
      );

      // Right-aligned product label
      doc.setFont("helvetica", "bold");
      doc.setTextColor(...ink);
      doc.text("Football Analytics", pageWidth - marginX, 14, { align: "right" });
      doc.setFont("helvetica", "normal");
      doc.setFontSize(8);
      doc.setTextColor(...muted);
      doc.text("Generated report", pageWidth - marginX, 19, { align: "right" });

      // Divider line under header
      doc.setDrawColor(226, 232, 240);
      doc.setLineWidth(0.3);
      doc.line(marginX, 28, pageWidth - marginX, 28);

      // ----- Table -----
      if (data.length > 0) {
        const headers = Object.keys(data[0]);
        const formatHeader = (h: string) =>
          h
            .replace(/([A-Z])/g, " $1")
            .replace(/[_-]/g, " ")
            .replace(/\b\w/g, (c) => c.toUpperCase())
            .trim();

        const rows = data.map((row) =>
          headers.map((header) => {
            const value = row[header];
            if (value === null || value === undefined || value === "") return "—";
            if (typeof value === "number") {
              return Number.isInteger(value) ? value.toString() : value.toFixed(2);
            }
            return String(value);
          })
        );

        // Heuristic: numeric columns get right-aligned narrow widths
        const numericCols = new Set<number>();
        headers.forEach((h, idx) => {
          let isNumeric = true;
          for (let i = 0; i < Math.min(data.length, 20); i += 1) {
            const v = data[i][h];
            if (v === null || v === undefined || v === "") continue;
            if (typeof v !== "number" && Number.isNaN(Number(v))) {
              isNumeric = false;
              break;
            }
          }
          if (isNumeric) numericCols.add(idx);
        });

        const columnStyles: Record<number, { halign?: "left" | "center" | "right"; cellWidth?: number }> = {};
        headers.forEach((_, idx) => {
          if (numericCols.has(idx)) {
            columnStyles[idx] = { halign: "right", cellWidth: 18 };
          }
        });

        autoTable(doc, {
          head: [headers.map(formatHeader)],
          body: rows,
          startY: 32,
          margin: { left: marginX, right: marginX, bottom: 16 },
          theme: "grid",
          styles: {
            fontSize: 8,
            cellPadding: { top: 2.4, right: 3, bottom: 2.4, left: 3 },
            lineColor: [226, 232, 240],
            lineWidth: 0.1,
            textColor: ink,
            valign: "middle",
            overflow: "linebreak",
          },
          headStyles: {
            fillColor: ink,
            textColor: 255,
            fontStyle: "bold",
            fontSize: 8.5,
            halign: "left",
            cellPadding: { top: 3, right: 3, bottom: 3, left: 3 },
          },
          alternateRowStyles: {
            fillColor: [248, 250, 252],
          },
          columnStyles,
          didDrawPage: () => {
            // Footer with page number + brand
            const pageCount = doc.getNumberOfPages();
            const currentPage = doc.getCurrentPageInfo().pageNumber;
            doc.setDrawColor(226, 232, 240);
            doc.setLineWidth(0.3);
            doc.line(marginX, pageHeight - 10, pageWidth - marginX, pageHeight - 10);
            doc.setFont("helvetica", "normal");
            doc.setFontSize(8);
            doc.setTextColor(...muted);
            doc.text("Football Analytics  ·  Confidential", marginX, pageHeight - 5);
            doc.text(`Page ${currentPage} / ${pageCount}`, pageWidth - marginX, pageHeight - 5, {
              align: "right",
            });
          },
        });
      } else {
        doc.setFontSize(10);
        doc.setTextColor(...muted);
        doc.text("No data available for the selected scope.", marginX, 42);
      }

      // Convert PDF to buffer
      fileContent = Buffer.from(doc.output("arraybuffer"));
      fileExtension = "pdf";
    } else {
      return NextResponse.json({ ok: false, message: "Unsupported format" }, { status: 400 });
    }

    const filepath = join(exportsDir, `${finalFilename}.${fileExtension}`);

    if (format === "pdf") {
      await writeFile(filepath, fileContent);
    } else {
      await writeFile(filepath, fileContent, "utf-8");
    }

    const downloadKey = `${finalFilename}.${fileExtension}`;
    const downloadUrl = `/exports/${downloadKey}`;
    const fileSize =
      fileContent instanceof Buffer ? fileContent.length : Buffer.byteLength(fileContent);

    const scopeLabel = matchId
      ? `Match #${matchId} (${data.length} rows)`
      : `${source} (${data.length} rows)`;

    let createdRecord = null as null | { id: number; createdAt: Date };
    try {
      createdRecord = await prisma.dataExport.create({
        data: {
          userId: user.id,
          source,
          format,
          scopeLabel,
          status: "ready",
          downloadKey,
          fileSize,
          completedAt: new Date(),
        },
        select: { id: true, createdAt: true },
      });
    } catch (persistError) {
      console.warn("[exports.create] Failed to persist DataExport metadata:", persistError);
    }

    return NextResponse.json({
      ok: true,
      downloadUrl,
      filename: downloadKey,
      export: createdRecord
        ? {
            id: createdRecord.id,
            source,
            format,
            scopeLabel,
            status: "ready",
            downloadKey,
            fileSize,
            createdAt: createdRecord.createdAt,
          }
        : null,
      message: "Export created successfully",
    });
  } catch (error) {
    console.error("[exports.create] Error:", error);
    return NextResponse.json(
      { ok: false, message: "Failed to create export" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getCurrentUser } from "@/lib/auth";
import {
  calculateTotalXG,
  calculatePossession,
  generateHeatmap,
  calculateShotStats,
  calculatePPDA,
  calculateHighRegains,
  calculateProgressivePasses,
  calculateXA,
  calculateRealXA,
  calculatePassAccuracy,
  type ShotEvent,
  type PassEvent,
  type TouchEvent,
} from "@/lib/analytics";

export const runtime = "nodejs";

// Simple in-memory cache for analytics
// In production, use Redis or similar
declare global {
  var analyticsCache: Map<string, { data: any; timestamp: number; eventCount: number }> | undefined;
}

const analyticsCache = typeof global !== "undefined" 
  ? (global.analyticsCache ||= new Map<string, { data: any; timestamp: number; eventCount: number }>())
  : new Map<string, { data: any; timestamp: number; eventCount: number }>();
const CACHE_TTL = 30 * 1000; // 30 seconds cache

export async function GET(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
  }

  const { id } = await params;
  const matchId = parseInt(id);

  if (isNaN(matchId)) {
    return NextResponse.json({ ok: false, message: "Invalid match ID" }, { status: 400 });
  }

  // Get match
  const match = await prisma.match.findUnique({
    where: { id: matchId },
    include: {
      homeTeam: { select: { id: true, name: true } },
      awayTeam: { select: { id: true, name: true } },
    },
  });

  if (!match) {
    return NextResponse.json({ ok: false, message: "Match not found" }, { status: 404 });
  }

  // Get user's team IDs to verify access
  const userTeams = await prisma.userTeam.findMany({
    where: { userId: user.id, status: "active" },
    select: { teamId: true },
  });

  const createdTeams = await prisma.team.findMany({
    where: { createdById: user.id },
    select: { id: true },
  });

  const userTeamIds = [
    ...userTeams.map((ut) => ut.teamId),
    ...createdTeams.map((t) => t.id),
  ];

  // Verify user has access to this match
  const hasAccess = userTeamIds.length > 0 && (
    (match.homeTeamId && userTeamIds.includes(match.homeTeamId)) ||
    (match.awayTeamId && userTeamIds.includes(match.awayTeamId))
  );

  if (!hasAccess && userTeamIds.length > 0) {
    return NextResponse.json({ ok: false, message: "You don't have access to this match" }, { status: 403 });
  }

  // Check cache first
  const cacheKey = `analytics-${matchId}`;
  const cached = analyticsCache.get(cacheKey);

  // Get event count for cache invalidation
  const eventCount = await prisma.matchEvent.count({ where: { matchId } });

  // Return cached data if available and events haven't changed
  if (cached && Date.now() - cached.timestamp < CACHE_TTL && cached.eventCount === eventCount) {
    return NextResponse.json({
      ok: true,
      analytics: cached.data,
      cached: true,
    });
  }

  // Get all events for this match - only select needed fields for better performance
  const events = await prisma.matchEvent.findMany({
    where: { matchId },
    select: {
      id: true,
      type: true,
      team: true,
      x: true,
      y: true,
      minute: true,
      xg: true,
      metadata: true,
      player: {
        select: { id: true, name: true },
      },
    },
    orderBy: { minute: "asc" },
  });

  // Separate events by type and team
  const homeShots: ShotEvent[] = [];
  const awayShots: ShotEvent[] = [];
  const homePasses: PassEvent[] = [];
  const awayPasses: PassEvent[] = [];
  const homeTouches: TouchEvent[] = [];
  const awayTouches: TouchEvent[] = [];
  const homeDefensiveActions: Array<{ x: number; y: number; minute?: number }> = [];
  const awayDefensiveActions: Array<{ x: number; y: number; minute?: number }> = [];
  const homeRecoveries: Array<{ x: number; y: number; minute?: number }> = [];
  const awayRecoveries: Array<{ x: number; y: number; minute?: number }> = [];

  events.forEach((event) => {
    const eventData = {
      x: event.x || 0,
      y: event.y || 0,
      minute: event.minute || undefined,
    };

    if (event.type === "shot") {
      // Filter shots with valid coords (not null, not NaN, in 0-100 range)
      const x = Number(event.x);
      const y = Number(event.y);
      if (
        event.x === null ||
        event.y === null ||
        isNaN(x) ||
        isNaN(y) ||
        x < 0 ||
        x > 100 ||
        y < 0 ||
        y > 100
      ) {
        // Skip shots without valid coords
        return;
      }

      try {
        const metadata = event.metadata ? JSON.parse(event.metadata) : {};
        // Normalize outcome
        let outcome = "off_target";
        if (metadata && typeof metadata === "object" && metadata.outcome) {
          const metaOutcome = String(metadata.outcome).toLowerCase();
          if (metaOutcome === "goal") outcome = "goal";
          else if (metaOutcome === "saved") outcome = "saved";
          else if (metaOutcome === "blocked") outcome = "blocked";
          else outcome = "off_target";
        }

        const shot: ShotEvent = {
          x: Math.max(0, Math.min(100, x)),
          y: Math.max(0, Math.min(100, y)),
          minute: event.minute || undefined,
          xg: event.xg !== null && !isNaN(Number(event.xg)) ? Number(event.xg) : undefined,
          shotType: metadata.shotType,
          bodyPart: metadata.bodyPart,
          outcome,
        };

        if (event.team === "home") {
          homeShots.push(shot);
        } else if (event.team === "away") {
          awayShots.push(shot);
        }
      } catch {
        // Invalid JSON, skip this shot
      }
    } else if (event.type === "pass") {
      try {
        const metadata = event.metadata ? JSON.parse(event.metadata) : {};
        const pass: PassEvent = {
          ...eventData,
          successful: metadata.successful !== false,
          endX: metadata.endX !== null && metadata.endX !== undefined && !isNaN(Number(metadata.endX)) 
            ? Number(metadata.endX) 
            : undefined,
          endY: metadata.endY !== null && metadata.endY !== undefined && !isNaN(Number(metadata.endY)) 
            ? Number(metadata.endY) 
            : undefined,
          receiverId: metadata.receiverId !== null && metadata.receiverId !== undefined && !isNaN(Number(metadata.receiverId)) 
            ? Number(metadata.receiverId) 
            : undefined,
          playerId: event.player?.id || undefined,
          timestamp: metadata.timestamp !== null && metadata.timestamp !== undefined && !isNaN(Number(metadata.timestamp))
            ? Number(metadata.timestamp) 
            : (event.minute !== null && !isNaN(Number(event.minute)) ? Number(event.minute) * 60 : undefined),
          eventId: event.id,
          assistId: metadata.assistId !== null && metadata.assistId !== undefined && !isNaN(Number(metadata.assistId))
            ? Number(metadata.assistId)
            : undefined,
          possessionId: metadata.possessionId !== null && metadata.possessionId !== undefined
            ? String(metadata.possessionId)
            : undefined,
        };

        if (event.team === "home") {
          homePasses.push(pass);
        } else {
          awayPasses.push(pass);
        }
      } catch {
        // Invalid JSON, skip this pass
      }
    } else if (event.type === "touch") {
      if (event.team === "home") {
        homeTouches.push(eventData);
      } else {
        awayTouches.push(eventData);
      }
    } else if (event.type === "tackle" || event.type === "interception") {
      // Defensive actions
      if (event.team === "home") {
        homeDefensiveActions.push(eventData);
      } else {
        awayDefensiveActions.push(eventData);
      }
    } else if (event.type === "recovery") {
      // Ball recoveries
      if (event.team === "home") {
        homeRecoveries.push(eventData);
      } else {
        awayRecoveries.push(eventData);
      }
    }
  });

  // Calculate analytics
  const homeXG = calculateTotalXG(homeShots);
  const awayXG = calculateTotalXG(awayShots);

  const possession = calculatePossession(
    [...homePasses, ...homeTouches],
    [...awayPasses, ...awayTouches]
  );

  const homeShotStats = calculateShotStats(homeShots);
  const awayShotStats = calculateShotStats(awayShots);

  // Advanced metrics
  const homePPDA = calculatePPDA(awayPasses, homeDefensiveActions.length);
  const awayPPDA = calculatePPDA(homePasses, awayDefensiveActions.length);

  const homeHighRegains = calculateHighRegains(homeRecoveries, true);
  const awayHighRegains = calculateHighRegains(awayRecoveries, false);

  // Calculate real progressive passes (with endX/endY from metadata)
  const homeProgressivePasses = calculateProgressivePasses(homePasses, true);
  const awayProgressivePasses = calculateProgressivePasses(awayPasses, false);

  // Calculate real xA (pass → shot links)
  const homeXAResult = calculateRealXA(homePasses, homeShots, true);
  const awayXAResult = calculateRealXA(awayPasses, awayShots, false);
  const homeXA = homeXAResult.totalXA;
  const awayXA = awayXAResult.totalXA;

  const homePassAccuracy = calculatePassAccuracy(homePasses);
  const awayPassAccuracy = calculatePassAccuracy(awayPasses);

  // Generate heatmaps from ALL spatial events (touches, passes, pressures, carries)
  // Include all events with valid coords, not just passes/touches
  // Weight=1 for most events (keep homogeneity), small boost for pressures (1.1)
  const allHomeEvents = [
    ...homePasses.map(e => ({ x: e.x, y: e.y, weight: 1 })),
    ...homeTouches.map(e => ({ x: e.x, y: e.y, weight: 1 })),
    ...homeDefensiveActions.map(e => ({ x: e.x, y: e.y, weight: 1.1 })), // Pressures/tackles: slight boost
    ...homeRecoveries.map(e => ({ x: e.x, y: e.y, weight: 1 })), // Recoveries: weight=1
  ].filter(
    (e) => {
      // Validate: x,y must be in [0,1] or [0,100] normalized range
      const x = Number(e.x);
      const y = Number(e.y);
      return e.x !== null && e.y !== null && 
             !isNaN(x) && !isNaN(y) && 
             x >= 0 && x <= 100 && 
             y >= 0 && y <= 100;
    }
  );

  const allAwayEvents = [
    ...awayPasses.map(e => ({ x: e.x, y: e.y, weight: 1 })),
    ...awayTouches.map(e => ({ x: e.x, y: e.y, weight: 1 })),
    ...awayDefensiveActions.map(e => ({ x: e.x, y: e.y, weight: 1.1 })), // Pressures/tackles: slight boost
    ...awayRecoveries.map(e => ({ x: e.x, y: e.y, weight: 1 })), // Recoveries: weight=1
  ].filter(
    (e) => {
      const x = Number(e.x);
      const y = Number(e.y);
      return e.x !== null && e.y !== null && 
             !isNaN(x) && !isNaN(y) && 
             x >= 0 && x <= 100 && 
             y >= 0 && y <= 100;
    }
  );

  // Generate heatmaps with 80×52 grid (matching 105m×68m pitch ratio)
  const homeHeatmap = generateHeatmap(allHomeEvents, 80, 52);
  const awayHeatmap = generateHeatmap(allAwayEvents, 80, 52);

  // Shot map (just shots - separate overlay, already filtered for valid coords)
  // Convert shots to events format for generateHeatmap
  const homeShotEvents = homeShots
    .filter(s => {
      const x = Number(s.x);
      const y = Number(s.y);
      return s.x !== null && s.y !== null && 
             !isNaN(x) && !isNaN(y) && 
             x >= 0 && x <= 100 && 
             y >= 0 && y <= 100;
    })
    .map(s => ({ x: s.x, y: s.y, weight: 1 }));

  const awayShotEvents = awayShots
    .filter(s => {
      const x = Number(s.x);
      const y = Number(s.y);
      return s.x !== null && s.y !== null && 
             !isNaN(x) && !isNaN(y) && 
             x >= 0 && x <= 100 && 
             y >= 0 && y <= 100;
    })
    .map(s => ({ x: s.x, y: s.y, weight: 1 }));

  const homeShotMap = generateHeatmap(homeShotEvents, 80, 52);
  const awayShotMap = generateHeatmap(awayShotEvents, 80, 52);

  const analyticsData = {
    xg: {
      home: Math.round(homeXG * 100) / 100,
      away: Math.round(awayXG * 100) / 100,
    },
    possession: {
      home: possession.home,
      away: possession.away,
    },
    shots: {
      home: homeShotStats,
      away: awayShotStats,
    },
    heatmaps: {
      home: homeHeatmap || [],
      away: awayHeatmap || [],
    },
    shotMaps: {
      home: homeShotMap || [],
      away: awayShotMap || [],
    },
    events: {
      total: events.length,
      byType: {
        shots: events.filter(e => e.type === "shot").length,
        passes: events.filter(e => e.type === "pass").length,
        touches: events.filter(e => e.type === "touch").length,
      },
      passesHomeSuccess: homePasses.filter(p => p.successful !== false).length,
      passesAwaySuccess: awayPasses.filter(p => p.successful !== false).length,
      touchesHome: homeTouches.length,
      touchesAway: awayTouches.length,
    },
    // Advanced professional metrics
    ppda: {
      home: homePPDA,
      away: awayPPDA,
    },
    highRegains: {
      home: homeHighRegains,
      away: awayHighRegains,
    },
    progressivePasses: {
      home: homeProgressivePasses,
      away: awayProgressivePasses,
    },
    xa: {
      home: homeXA,
      away: awayXA,
    },
    passAccuracy: {
      home: homePassAccuracy,
      away: awayPassAccuracy,
    },
  };

  // Cache the result
  analyticsCache.set(cacheKey, {
    data: analyticsData,
    timestamp: Date.now(),
    eventCount,
  });

  // Clean up old cache entries (keep only last 50)
  if (analyticsCache.size > 50) {
    const entries = Array.from(analyticsCache.entries());
    entries.sort((a, b) => b[1].timestamp - a[1].timestamp);
    analyticsCache.clear();
    entries.slice(0, 50).forEach(([key, value]) => {
      analyticsCache.set(key, value);
    });
  }

  return NextResponse.json({
    ok: true,
    analytics: analyticsData,
  });
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getCurrentUser } from "@/lib/auth";
import { calculateXG } from "@/lib/analytics";

export const runtime = "nodejs";

// Cache invalidation helper (shared with analytics route)
declare global {
  var analyticsCache: Map<string, { data: any; timestamp: number; eventCount: number }> | undefined;
}

function invalidateAnalyticsCache(matchId: number) {
  if (typeof global !== "undefined" && global.analyticsCache) {
    global.analyticsCache.delete(`analytics-${matchId}`);
  }
}

// Get all events for a match
export async function GET(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
  }

  const { id } = await params;

  // Support both numeric ID and slug (like the match endpoint)
  let matchId: number | null = null;
  const parsedId = parseInt(id);

  if (!isNaN(parsedId)) {
    // It's a numeric ID
    matchId = parsedId;
  } else {
    // It's a slug - find match by slug first
    const match = await prisma.match.findUnique({
      where: { slug: id },
      select: { id: true },
    });

    if (!match) {
      return NextResponse.json({ ok: false, message: "Match not found" }, { status: 404 });
    }

    matchId = match.id;
  }

  // Get user's team IDs to verify access
  const userTeams = await prisma.userTeam.findMany({
    where: { userId: user.id, status: "active" },
    select: { teamId: true },
  });

  const createdTeams = await prisma.team.findMany({
    where: { createdById: user.id },
    select: { id: true },
  });

  const userTeamIds = [
    ...userTeams.map((ut) => ut.teamId),
    ...createdTeams.map((t) => t.id),
  ];

  // Verify match access
  if (matchId) {
    const matchForAccess = await prisma.match.findUnique({
      where: { id: matchId },
      select: { homeTeamId: true, awayTeamId: true },
    });

    if (matchForAccess) {
      const hasAccess = userTeamIds.length > 0 && (
        (matchForAccess.homeTeamId && userTeamIds.includes(matchForAccess.homeTeamId)) ||
        (matchForAccess.awayTeamId && userTeamIds.includes(matchForAccess.awayTeamId))
      );

      if (!hasAccess && userTeamIds.length > 0) {
        return NextResponse.json({ ok: false, message: "You don't have access to this match" }, { status: 403 });
      }
    }
  }

  // Only select needed fields for better performance
  const events = await prisma.matchEvent.findMany({
    where: { matchId },
    select: {
      id: true,
      type: true,
      team: true,
      x: true,
      y: true,
      minute: true,
      xg: true,
      metadata: true,
      player: {
        select: { id: true, name: true },
      },
    },
    orderBy: { minute: "asc" },
  });

  return NextResponse.json({ ok: true, events });
}

// Create a new event
export async function POST(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
  }

  const { id } = await params;

  // Support both numeric ID and slug (like the match endpoint)
  let matchId: number | null = null;
  const parsedId = parseInt(id);

  if (!isNaN(parsedId)) {
    // It's a numeric ID
    matchId = parsedId;
  } else {
    // It's a slug - find match by slug first
    const match = await prisma.match.findUnique({
      where: { slug: id },
      select: { id: true },
    });

    if (!match) {
      return NextResponse.json({ ok: false, message: "Match not found" }, { status: 404 });
    }

    matchId = match.id;
  }

  // Get user's team IDs to verify access
  const userTeams = await prisma.userTeam.findMany({
    where: { userId: user.id, status: "active" },
    select: { teamId: true },
  });

  const createdTeams = await prisma.team.findMany({
    where: { createdById: user.id },
    select: { id: true },
  });

  const userTeamIds = [
    ...userTeams.map((ut) => ut.teamId),
    ...createdTeams.map((t) => t.id),
  ];

  // Verify match exists and user has access
  const match = await prisma.match.findUnique({ where: { id: matchId } });

  if (!match) {
    return NextResponse.json({ ok: false, message: "Match not found" }, { status: 404 });
  }

  // Verify user has access to this match
  const hasAccess = userTeamIds.length > 0 && (
    (match.homeTeamId && userTeamIds.includes(match.homeTeamId)) ||
    (match.awayTeamId && userTeamIds.includes(match.awayTeamId))
  );

  if (!hasAccess && userTeamIds.length > 0) {
    return NextResponse.json({ ok: false, message: "You don't have access to this match" }, { status: 403 });
  }

  const body = (await request.json().catch(() => null)) as {
    type?: string;
    team?: string;
    playerId?: number;
    x?: number;
    y?: number;
    minute?: number;
    metadata?: Record<string, any>;
  } | null;

  if (!body?.type || !body.team) {
    return NextResponse.json({ ok: false, message: "Type and team are required" }, { status: 400 });
  }

  // Calculate xG for shots
  let xg: number | null = null;
  if (body.type === "shot" && body.x !== undefined && body.y !== undefined) {
    const metadata = body.metadata || {};
    xg = calculateXG({
      x: body.x,
      y: body.y,
      shotType: metadata.shotType,
      bodyPart: metadata.bodyPart,
      outcome: metadata.outcome,
    });
  }

  const event = await prisma.matchEvent.create({
    data: {
      matchId,
      type: body.type,
      team: body.team,
      playerId: body.playerId || null,
      x: body.x || null,
      y: body.y || null,
      minute: body.minute || null,
      metadata: body.metadata ? JSON.stringify(body.metadata) : null,
      xg: xg,
    },
    select: {
      id: true,
      type: true,
      team: true,
      x: true,
      y: true,
      minute: true,
      xg: true,
      metadata: true,
      player: {
        select: { id: true, name: true },
      },
    },
  });

  // Invalidate analytics cache when new event is added
  invalidateAnalyticsCache(matchId);

  // Auto-update player stats if event has a player
  if (event.playerId) {
    try {
      const { updatePlayerStatsFromEvents } = await import("@/lib/player-stats-calculator");
      await updatePlayerStatsFromEvents(event.playerId);
    } catch (error) {
      console.error("[events] Failed to update player stats:", error);
      // Don't fail the request if stats update fails
    }
  }

  return NextResponse.json({ ok: true, event }, { status: 201 });
}

import { NextRequest, NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export const runtime = "nodejs";

// Generate AI Highlight - Analyzes match events and creates highlight moments
export async function POST(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
  }

  try {
    const { id } = await params;
    const matchId = parseInt(id);

    if (isNaN(matchId)) {
      return NextResponse.json({ ok: false, message: "Invalid match ID" }, { status: 400 });
    }

    // Fetch match with events
    const match = await prisma.match.findUnique({
      where: { id: matchId },
      select: {
        id: true,
        slug: true,
        competition: true,
        date: true,
        scoreHome: true,
        scoreAway: true,
        homeTeamId: true,
        awayTeamId: true,
        homeTeamName: true,
        awayTeamName: true,
        homeTeam: {
          select: { id: true, name: true },
        },
        awayTeam: {
          select: { id: true, name: true },
        },
        events: {
          include: { player: true },
          orderBy: { minute: "asc" },
        },
      },
    });

    if (!match) {
      return NextResponse.json({ ok: false, message: "Match not found" }, { status: 404 });
    }

    // Helper function to get team name
    const getTeamName = (team: { name: string } | null, teamName: string | null | undefined): string => {
      if (team?.name) return team.name;
      if (teamName) return teamName;
      return "Unknown";
    };

    const homeTeamName = getTeamName(match.homeTeam, (match as any).homeTeamName);
    const awayTeamName = getTeamName(match.awayTeam, (match as any).awayTeamName);

    // Analyze events to find highlight moments
    const highlights: Array<{
      minute: number;
      type: string;
      description: string;
      player?: string;
      team: string;
      xg?: number;
    }> = [];

    // Find goals
    const goals = match.events.filter(
      (e) => e.type === "shot" && e.outcome === "goal"
    );
    goals.forEach((goal) => {
      highlights.push({
        minute: goal.minute || 0,
        type: "goal",
        description: `Goal! ${goal.player?.name || "Unknown"} scores`,
        player: goal.player?.name,
        team: goal.team,
        xg: goal.xg || undefined,
      });
    });

    // Find high xG shots (missed opportunities)
    const highXGShots = match.events.filter(
      (e) => e.type === "shot" && e.xg && e.xg > 0.3 && e.outcome !== "goal"
    );
    highXGShots.forEach((shot) => {
      highlights.push({
        minute: shot.minute || 0,
        type: "chance",
        description: `Big chance! ${shot.player?.name || "Unknown"} (xG: ${shot.xg?.toFixed(2)})`,
        player: shot.player?.name,
        team: shot.team,
        xg: shot.xg || undefined,
      });
    });

    // Find key passes/assists
    const keyPasses = match.events.filter(
      (e) => e.type === "pass" && e.outcome === "successful"
    );
    // Group passes by minute and find assists (pass before goal)
    goals.forEach((goal) => {
      const assistPass = keyPasses.find(
        (p) => p.minute && goal.minute && p.minute <= goal.minute && p.minute >= goal.minute - 2 && p.team === goal.team
      );
      if (assistPass) {
        highlights.push({
          minute: assistPass.minute || 0,
          type: "assist",
          description: `Assist by ${assistPass.player?.name || "Unknown"}`,
          player: assistPass.player?.name,
          team: assistPass.team,
        });
      }
    });

    // Sort by minute
    highlights.sort((a, b) => a.minute - b.minute);

    // Generate highlight summary
    const summary = {
      match: `${homeTeamName} vs ${awayTeamName}`,
      date: match.date.toISOString(),
      score: match.scoreHome !== null && match.scoreAway !== null 
        ? `${match.scoreHome}-${match.scoreAway}` 
        : "TBD",
      highlights: highlights.slice(0, 10), // Top 10 highlights
      totalEvents: match.events.length,
      totalGoals: goals.length,
    };

    return NextResponse.json({
      ok: true,
      highlight: summary,
      message: "AI highlight generated successfully",
    });
  } catch (error) {
    console.error("[matches.highlight] Error:", error);
    return NextResponse.json(
      { ok: false, message: "Failed to generate highlight" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
