// Cache invalidation helper (shared with analytics/events routes)
declare global {
  // eslint-disable-next-line no-var
  var analyticsCache: Map<string, { data: any; timestamp: number; eventCount: number }> | undefined;
}

function invalidateAnalyticsCache(matchId: number) {
  if (typeof global !== "undefined" && global.analyticsCache) {
    global.analyticsCache.delete(`analytics-${matchId}`);
  }
}

async function resolveMatchId(idParam: string): Promise<number | null> {
  if (/^\d+$/.test(idParam)) {
    return parseInt(idParam, 10);
  }
  const match = await prisma.match.findUnique({
    where: { slug: idParam },
    select: { id: true },
  });
  return match?.id ?? null;
}

/**
 * Video Analysis API
 * 
 * This endpoint:
 * 1. Receives video file or URL
 * 2. Processes video with AI/ML
 * 3. Detects events (shots, passes, touches)
 * 4. Saves events to database
 * 5. Returns analysis results
 * 
 * Integration points:
 * - OpenCV for frame processing
 * - YOLO for object detection
 * - Cloud services (AWS, Google)
 * - Custom ML models
 */
export async function POST(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  // Check if request was aborted
  if (request.signal?.aborted) {
    return NextResponse.json({ ok: false, message: "Request cancelled" }, { status: 499 });
  }

  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
  }

  const { id } = await params;
  const matchId = await resolveMatchId(id);
  if (!matchId) {
    return NextResponse.json({ ok: false, message: "Invalid match ID" }, { status: 400 });
  }

  // Verify match exists
  const match = await prisma.match.findUnique({ where: { id: matchId } });
  if (!match) {
    return NextResponse.json({ ok: false, message: "Match not found" }, { status: 404 });
  }

  // Parse request body (can be FormData or JSON)
  let requestBody: any = {};
  try {
    const contentType = request.headers.get("content-type") || "";
    if (contentType.includes("application/json")) {
      requestBody = await request.json();
    } else {
      const formData = await request.formData().catch(() => null);
      if (formData) {
        requestBody = {
          videoUrl: formData.get("videoUrl") as string | null,
          video: formData.get("video") as File | null,
          provider: formData.get("provider") as string || "opencv",
          leftSideTeam: formData.get("leftSideTeam") as string,
          teamLeftId: formData.get("teamLeftId") ? parseInt(formData.get("teamLeftId") as string) : null,
          teamRightId: formData.get("teamRightId") ? parseInt(formData.get("teamRightId") as string) : null,
          attackDirection: formData.get("attackDirection") as string || "left-to-right",
          normalize: formData.get("normalize") === "true" || formData.get("normalize") === true,
        };
      }
    }
  } catch (e) {
    console.error("[video-analyze] Failed to parse request body:", e);
  }

  const videoFile = requestBody.video || null;
  const videoUrl = requestBody.videoUrl || null;
  const videoPathFromBody = requestBody.videoPath || null; // Support videoPath from transcoding
  const provider = requestBody.provider || "opencv";
  const leftSideTeam = requestBody.leftSideTeam || null;
  const teamLeftId = requestBody.teamLeftId || null;
  const teamRightId = requestBody.teamRightId || null;
  const attackDirection = requestBody.attackDirection || "left-to-right";
  const normalize = requestBody.normalize !== false; // Default to true
  const replaceExisting = requestBody.replaceExisting !== false; // Default true: replace old analysis results

  // VALIDATION: Team side selection is mandatory
  if (!leftSideTeam || (leftSideTeam !== "home" && leftSideTeam !== "away")) {
    return NextResponse.json({ ok: false, message: "Team side selection is required (leftSideTeam must be 'home' or 'away')" }, { status: 400 });
  }

  // NOTE: Team IDs are ONLY used for Spotlight player highlighting, NOT for analysis
  // Analysis always uses position-based team assignment (y < 50 = home, y >= 50 = away)
  // This is independent of team IDs - analysis will work even without teams assigned
  let finalTeamLeftId = teamLeftId;
  let finalTeamRightId = teamRightId;

  if (!teamLeftId || !teamRightId) {
    // Fallback: use match.homeTeamId and match.awayTeamId (only for Spotlight, not for analysis)
    const fallbackTeamLeftId = leftSideTeam === "home" ? match.homeTeamId : match.awayTeamId;
    const fallbackTeamRightId = leftSideTeam === "home" ? match.awayTeamId : match.homeTeamId;

    // Only log warning if fallback values are also null (match has no teams assigned)
    // This is just for Spotlight - analysis will work fine without teams
    if (!fallbackTeamLeftId || !fallbackTeamRightId) {
      console.log(`[video-analyze] Team IDs not provided and match has no teams assigned. This only affects Spotlight player highlighting. Analysis will proceed normally with position-based team assignment.`);
    } else {
      // Use fallback values silently (this is expected behavior)
      finalTeamLeftId = fallbackTeamLeftId;
      finalTeamRightId = fallbackTeamRightId;
    }
  }

  // Check for video input - support videoFile, videoUrl, or videoPath
  if (!videoFile && !videoUrl && !videoPathFromBody) {
    return NextResponse.json({ ok: false, message: "Video file, URL, or path required" }, { status: 400 });
  }

  // Check abort signal periodically
  const checkAbort = () => {
    if (request.signal?.aborted) {
      throw new Error("Request cancelled");
    }
  };

  try {
    // IMPORTANT: To avoid showing "previous analyses", we replace existing events by default.
    // This matches the expected UX: each analysis run should reflect the current video, not accumulate old data.
    if (replaceExisting) {
      console.log(`[video-analyze] replaceExisting=true → deleting existing events for match ${matchId}...`);
      await prisma.matchEvent.deleteMany({ where: { matchId } });
      // Reset aggregate match stats so stale values from previous analyses are not shown.
      await prisma.match.update({
        where: { id: matchId },
        data: {
          shotsHome: 0,
          shotsAway: 0,
          xgHome: 0,
          xgAway: 0,
        },
      });
      invalidateAnalyticsCache(matchId);
    }

    let videoPath: string | null = null;

    // Save video file if uploaded (non-blocking)
    if (videoFile) {
      checkAbort();
      videoPath = await saveVideoFile(videoFile, matchId);
      checkAbort();
      if (!videoPath) {
        return NextResponse.json({ ok: false, message: "Failed to save video file" }, { status: 500 });
      }
      console.log(`[video-analyze] Video saved to: ${videoPath}`);
    } else if (videoPathFromBody) {
      // Support videoPath from transcoding (absolute or relative path)
      videoPath = videoPathFromBody;
      console.log(`[video-analyze] Using video path from request: ${videoPath}`);
    } else if (videoUrl) {
      videoPath = videoUrl;
      console.log(`[video-analyze] Using video URL: ${videoPath}`);
    } else {
      return NextResponse.json({ ok: false, message: "Video file, URL, or path required" }, { status: 400 });
    }

    // Same video file the AI analyzes → persist on Match immediately so Spotlight stays in sync (before / even if AI fails).
    const storedVideoPath = toStoredVideoPath(videoPath);
    if (storedVideoPath) {
      try {
        await prisma.match.update({
          where: { id: matchId },
          data: { videoPath: storedVideoPath },
        });
        console.log(`[video-analyze] Match ${matchId} videoPath set for Spotlight: ${storedVideoPath}`);
      } catch (persistErr) {
        console.warn("[video-analyze] Could not persist videoPath:", persistErr);
      }
    }

    // Call Python AI analysis endpoint directly (internal call)
    // This uses the actual YOLO analysis from football_ai/analysis.py
    let analysisResponse = null;

    try {
      checkAbort();
      console.log(`[video-analyze] Starting AI analysis for video: ${videoPath}`);

      // Import and call the analyze-video handler directly
      // This avoids HTTP fetch issues (CORS, auth, etc.)
      const { POST: analyzeVideoPOST } = await import("@/app/api/ai/analyze-video/route");

      checkAbort();

      // Build a proper JSON request for the AI endpoint.
      // Previous URL-encoded payload could be parsed as invalid form data in some runtimes.
      const analyzePayload: Record<string, any> = {};
      if (videoPath && !videoPath.startsWith("http")) {
        analyzePayload.videoUrl = videoPath;
        console.log(`[video-analyze] Passing video path to analysis: ${videoPath}`);
      } else if (videoUrl) {
        analyzePayload.videoUrl = videoUrl;
        console.log(`[video-analyze] Passing video URL to analysis: ${videoUrl}`);
      }

      // Create NextRequest with form data and signal
      const analyzeRequest = new NextRequest(
        new URL("/api/ai/analyze-video", request.url),
        {
          method: "POST",
          headers: {
            "content-type": "application/json",
            // Copy cookies for authentication
            cookie: request.headers.get("cookie") || "",
          },
          body: JSON.stringify(analyzePayload),
          signal: request.signal, // Pass abort signal
        }
      );

      // Call the analyze-video endpoint handler directly
      // Use Promise.race with timeout to prevent blocking
      const analysisPromise = analyzeVideoPOST(analyzeRequest);
      const timeoutPromise = new Promise<NextResponse>((resolve) => {
        setTimeout(() => {
          resolve(NextResponse.json({ ok: false, message: "Analysis timeout" }, { status: 504 }));
        }, 240000); // 4 minutes timeout
      });

      analysisResponse = await Promise.race([analysisPromise, timeoutPromise]);
      checkAbort();

      console.log(`[video-analyze] Analysis response received, status: ${analysisResponse.status}`);

      // Log response for debugging (non-blocking)
      if (analysisResponse.ok) {
        analysisResponse.clone().json().then((responseData) => {
          console.log(`[video-analyze] Analysis response data:`, JSON.stringify(responseData, null, 2));
        }).catch(() => {});
      }

    } catch (err: any) {
      // If request was aborted, return early
      if (err.message === "Request cancelled" || request.signal?.aborted) {
        return NextResponse.json({ ok: false, message: "Request cancelled" }, { status: 499 });
      }

      // If Python endpoint fails, log error but continue
      console.error("[video-analyze] Python analysis error:", err);
      if (err instanceof Error) {
        console.error("[video-analyze] Error message:", err.message);
        console.error("[video-analyze] Error stack:", err.stack);
      }
      analysisResponse = null;
    }

    // Try to get analysis from Python endpoint if available
    let analysisResult = null;

    if (analysisResponse && analysisResponse.ok) {
      try {
        const analysisData = await analysisResponse.json();
        console.log(`[video-analyze] Python response: ok=${analysisData.ok}, hasAnalysis=${!!analysisData.analysis}, eventsCount=${analysisData.analysis?.events?.length || 0}`);

        if (analysisData.ok && analysisData.analysis) {
          // Convert Python analysis format to our format
          // Determine team based on pitch position:
          // - Home team attacks from y=0 to y=50 (left side)
          // - Away team attacks from y=50 to y=100 (right side)
          // For shots: if y < 50, it's home team shooting, if y > 50, it's away team
          // For other events: use ball position or event position
          analysisResult = {
            videoId: `match-${matchId}`,
            matchId,
            duration: analysisData.analysis.duration || 0,
            fps: analysisData.analysis.fps || 30,
            totalFrames: analysisData.analysis.total_frames || 0,
            events: (analysisData.analysis.events || []).map((e: any) => {
              // Determine team from position
              let team: "home" | "away" = "home";

              if (e.team) {
                // If Python script already assigned team, use it
                team = e.team === "away" ? "away" : "home";
              } else if (e.position) {
                // Determine team from pitch position
                const y = e.position.y || 50;
                // Home team attacks from y=0 to y=50 (left side, attacking goal at y=0)
                // Away team attacks from y=50 to y=100 (right side, attacking goal at y=100)

                if (e.type === "shot") {
                  // For shots: if shot is close to goal (y < 20 or y > 80), determine team
                  // Shots near y=0 are home team, shots near y=100 are away team
                  if (y < 20) {
                    team = "home"; // Home team shooting at goal (y=0)
                  } else if (y > 80) {
                    team = "away"; // Away team shooting at goal (y=100)
                  } else {
                    // For shots in middle, use y < 50 for home, y > 50 for away
                    team = y < 50 ? "home" : "away";
                  }
                } else if (e.type === "pass" || e.type === "touch") {
                  // For passes/touches: determine from position
                  // If event is in attacking half, it's that team
                  team = y < 50 ? "home" : "away";
                } else {
                  // For other events (tackles, interceptions, etc.), use position
                  team = y < 50 ? "home" : "away";
                }
              }

              return {
                type: e.type,
                timestamp: e.timestamp || 0,
                frame: e.frame || 0,
                team,
                playerId: e.playerId,
                pitchPosition: e.position ? { x: e.position.x, y: e.position.y } : undefined,
                confidence: e.confidence || 0.5,
                metadata: e.metadata || {},
              };
            }),
            playerTracking: [],
            ballTracking: [],
            processedAt: new Date().toISOString(),
          };
          console.log(`[video-analyze] Created analysisResult with ${analysisResult.events?.length || 0} events`);
        } else {
          console.warn(`[video-analyze] Python response ok but no analysis data. analysisData:`, JSON.stringify(analysisData, null, 2));
        }
      } catch (parseError) {
        console.error("[video-analyze] Failed to parse analysis response:", parseError);
        if (parseError instanceof Error) {
          console.error("[video-analyze] Parse error details:", parseError.message, parseError.stack);
        }
      }
    }

    // If no analysis result, return empty analysis (no synthetic/demo events)
    if (!analysisResult) {
      console.warn(`[video-analyze] No analysis result. Analysis response status: ${analysisResponse?.status}`);
      console.warn(`[video-analyze] Analysis response ok: ${analysisResponse?.ok}`);

      console.warn(`[video-analyze] Python analysis failed or returned no results.`);

      // Try to get error message from response (for logging only)
      if (analysisResponse && !analysisResponse.ok) {
        try {
          const errorData = await analysisResponse.json();
          console.error(`[video-analyze] Analysis error:`, errorData);
        } catch (e) {
          // Ignore parse errors
        }
      }

      return NextResponse.json({
        ok: true,
        message: "Video uploaded successfully, but no events were detected. You can add events manually.",
        analysis: {
          eventsDetected: 0,
          shots: { home: 0, away: 0 },
          xg: { home: 0, away: 0 },
          duration: 0,
          totalFrames: 0,
        },
        videoPath: videoPath.startsWith("http") ? videoPath : `/uploads/videos/match-${matchId}/${videoPath.split("/").pop()}`,
      });
    }

    // Log analysis result for debugging
    console.log(`[video-analyze] Analysis result:`, {
      eventsCount: analysisResult.events?.length || 0,
      duration: analysisResult.duration,
      totalFrames: analysisResult.totalFrames,
      finalTeamLeftId,
      finalTeamRightId,
      leftSideTeam,
    });

    // Convert detected events to MatchEvent format
    console.log(`[video-analyze] Converting ${analysisResult.events?.length || 0} events to MatchEvent format`);

    if (!analysisResult.events || analysisResult.events.length === 0) {
      console.warn(`[video-analyze] No events detected in analysis result.`);
      return NextResponse.json({
        ok: true,
        message: "Video analyzed successfully, but no events were detected. The video may not contain clear football action or the AI model needs improvement.",
        analysis: {
          eventsDetected: 0,
          shots: { home: 0, away: 0 },
          xg: { home: 0, away: 0 },
          duration: analysisResult.duration,
          totalFrames: analysisResult.totalFrames,
        },
      });
    }

    let eventsToCreate = convertDetectedEventsToMatchEvents(analysisResult.events, matchId);
    console.log(`[video-analyze] Converted to ${eventsToCreate.length} MatchEvents`);

    // Normalize and map events based on team side selection
    // IMPORTANT: Team assignment is ALWAYS position-based (y < 50 = home, y >= 50 = away)
    // Team IDs are ONLY used for Spotlight player highlighting, NOT for analysis
    // This ensures analysis always works, even without team IDs

    // Calculate xG for shots and ensure team assignment is correct
    eventsToCreate = eventsToCreate.map((eventData) => {
      // Normalize coordinates to 0..1 if needed
      let normalizedX = eventData.x;
      let normalizedY = eventData.y;

      if (normalize && eventData.x !== null && eventData.y !== null) {
        // If coordinates are in pixels, normalize to 0-100 (or 0-1)
        // Assuming video analysis returns pixel coordinates, we need to normalize
        // For now, assume they're already in 0-100 range, but we can adjust if needed
        normalizedX = Math.max(0, Math.min(100, Number(eventData.x)));
        normalizedY = Math.max(0, Math.min(100, Number(eventData.y)));
      }

      // Determine team based on position and leftSideTeam setting
      // Left side = y < 50 (or normalized y < 0.5), Right side = y >= 50
      // But we need to check the actual teamId from the event if available
      let team: "home" | "away";
      let playerId: number | null = eventData.playerId || null;

      // Try to get teamId from event metadata first
      let eventTeamId: number | null = null;
      try {
        if (eventData.metadata) {
          const metadata = typeof eventData.metadata === "string" 
            ? JSON.parse(eventData.metadata) 
            : eventData.metadata;
          eventTeamId = metadata.teamId || metadata.team_id || null;
        }
      } catch (e) {
        // Invalid metadata, ignore
      }

      // ALWAYS use position-based mapping for team assignment (independent of team IDs)
      // Team IDs are ONLY used for Spotlight player highlighting, NOT for analysis
      // Position-based: y < 50 = left side, y >= 50 = right side
      // This ensures analysis always works, even without team IDs
      // Default to "home" if y is null (shouldn't happen, but safety check)
      const isLeftSide = normalizedY !== null && normalizedY < 50;
      team = normalizedY !== null 
        ? (leftSideTeam === "home" 
          ? (isLeftSide ? "home" : "away")
          : (isLeftSide ? "away" : "home"))
        : "home"; // Default fallback if y is null

      // Apply coordinate flip if needed based on attack direction
      // Our canvas expects: home attacks right (x: 0->100), away attacks left (x: 100->0)
      // If attackDirection is "left-to-right", left side attacks right (no flip needed for left team)
      // If attackDirection is "right-to-left", right side attacks left (flip needed)
      // For now, we assume left-to-right, so left team attacks right (normal)
      // Away team (right side) needs flip: x := 100 - x, y := 100 - y
      if (normalize && normalizedX !== null && normalizedY !== null && team === "away") {
        // Flip coordinates for away team to show their attacking perspective
        normalizedX = 100 - normalizedX;
        normalizedY = 100 - normalizedY;
      }

      // Calculate xG for shots
      if (eventData.type === "shot" && normalizedX !== null && normalizedY !== null) {
        const xg = calculateXG({
          x: normalizedX,
          y: normalizedY,
          shotType: "open_play", // Default for AI-detected shots
          bodyPart: "foot", // Default
        });

        return { 
          ...eventData, 
          x: normalizedX,
          y: normalizedY,
          xg, 
          team,
          playerId,
        };
      }

      return { 
        ...eventData, 
        x: normalizedX,
        y: normalizedY,
        team,
        playerId,
      };
    });

    // Remove AI jitter duplicates / low quality detections before saving.
    eventsToCreate = sanitizeEventsForStorage(eventsToCreate);
    console.log(`[video-analyze] Sanitized events for storage: ${eventsToCreate.length}`);

    // Save events to database
    console.log(`[video-analyze] Creating ${eventsToCreate.length} events in database...`);
    const createdEvents = await Promise.all(
      eventsToCreate.map((eventData) =>
        prisma.matchEvent.create({
          data: eventData,
        }).catch((err) => {
          console.error(`[video-analyze] Failed to create event:`, err);
          console.error(`[video-analyze] Event data:`, JSON.stringify(eventData, null, 2));
          return null;
        })
      )
    ).then(results => results.filter(r => r !== null));

    console.log(`[video-analyze] Successfully created ${createdEvents.length} events out of ${eventsToCreate.length} attempted.`);

    if (createdEvents.length === 0) {
      console.error(`[video-analyze] WARNING: No events were created! Check logs above for errors.`);
      console.error(`[video-analyze] eventsToCreate sample:`, eventsToCreate.slice(0, 2));
    }

    // Update match statistics
    const homeShots = createdEvents.filter((e) => e.type === "shot" && e.team === "home").length;
    const awayShots = createdEvents.filter((e) => e.type === "shot" && e.team === "away").length;
    const homeXG = createdEvents
      .filter((e) => e.type === "shot" && e.team === "home")
      .reduce((sum, e) => sum + (e.xg || 0), 0);
    const awayXG = createdEvents
      .filter((e) => e.type === "shot" && e.team === "away")
      .reduce((sum, e) => sum + (e.xg || 0), 0);

    console.log(`[video-analyze] Statistics: homeShots=${homeShots}, awayShots=${awayShots}, homeXG=${homeXG}, awayXG=${awayXG}`);

    await prisma.match.update({
      where: { id: matchId },
      data: {
        shotsHome: homeShots,
        shotsAway: awayShots,
        xgHome: homeXG,
        xgAway: awayXG,
        ...(storedVideoPath ? { videoPath: storedVideoPath } : {}),
      },
    });

    // Auto-update player stats for all players with events in this match
    const uniquePlayerIds = new Set(
      createdEvents
        .map((e) => e.playerId)
        .filter((id): id is number => id !== null && id !== undefined)
    );

    if (uniquePlayerIds.size > 0) {
      console.log(`[video-analyze] Updating stats for ${uniquePlayerIds.size} players...`);
      const { updatePlayerStatsFromEvents } = await import("@/lib/player-stats-calculator");
      await Promise.allSettled(
        Array.from(uniquePlayerIds).map((playerId) =>
          updatePlayerStatsFromEvents(playerId).catch((err) => {
            console.error(`[video-analyze] Failed to update stats for player ${playerId}:`, err);
          })
        )
      );
      console.log(`[video-analyze] Player stats updated successfully.`);
    }

    return NextResponse.json({
      ok: true,
      analysis: {
        eventsDetected: createdEvents.length,
        shots: { home: homeShots, away: awayShots },
        xg: { home: homeXG, away: awayXG },
        duration: analysisResult.duration,
        totalFrames: analysisResult.totalFrames,
      },
    });
  } catch (error) {
    console.error("[video-analyze] Error:", error);
    return NextResponse.json(
      {
        ok: false,
        message: error instanceof Error ? error.message : "Video analysis failed",
      },
      { status: 500 }
    );
  }
}

const MAX_VIDEO_SIZE = 10 * 1024 * 1024 * 1024; // 10GB

/**
 * Generate fallback demo events when AI analysis fails or detects nothing
 * This is similar to how professional apps handle edge cases
 */
export function generateFallbackEvents(matchId: number, leftSideTeam: string): Array<{
  matchId: number;
  type: string;
  team: string;
  x?: number;
  y?: number;
  minute?: number;
  metadata?: string;
  xg?: number;
}> {
  // Disabled intentionally: do not create synthetic/demo events.
  // If AI fails, callers should return 0 detected events instead of fake stats.
  return [];
}

type StorableEvent = {
  matchId: number;
  type: string;
  team: string;
  playerId?: number | null;
  x?: number | null;
  y?: number | null;
  minute?: number | null;
  metadata?: string;
  xg?: number;
};

function readConfidence(metadata?: string): number {
  if (!metadata) return 0.5;
  try {
    const m = JSON.parse(metadata);
    const c = Number(m?.confidence);
    return Number.isFinite(c) ? c : 0.5;
  } catch {
    return 0.5;
  }
}

function sanitizeEventsForStorage(events: StorableEvent[]): StorableEvent[] {
  if (!events.length) return events;

  const dedupShots = new Map<string, StorableEvent>();
  const nonShots: StorableEvent[] = [];

  for (const ev of events) {
    if (ev.type !== "shot") {
      nonShots.push(ev);
      continue;
    }
    if (ev.x == null || ev.y == null) continue;
    const x = Number(ev.x);
    const y = Number(ev.y);
    if (!Number.isFinite(x) || !Number.isFinite(y)) continue;

    const conf = readConfidence(ev.metadata);
    if (conf < 0.45) continue;

    const minuteBucket = Math.max(0, Math.floor(Number(ev.minute ?? 0)));
    const cellX = Math.floor(Math.max(0, Math.min(99.999, x)) / 5); // 5x5 grid in 0..100 coords
    const cellY = Math.floor(Math.max(0, Math.min(99.999, y)) / 5);
    const key = `${ev.team}|${minuteBucket}|${cellX}|${cellY}`;

    const existing = dedupShots.get(key);
    if (!existing || readConfidence(existing.metadata) < conf) {
      dedupShots.set(key, ev);
    }
  }

  const keptShots = Array.from(dedupShots.values());
  const byTeam = { home: [] as StorableEvent[], away: [] as StorableEvent[] };
  for (const s of keptShots) {
    if (s.team === "away") byTeam.away.push(s);
    else byTeam.home.push(s);
  }
  byTeam.home.sort((a, b) => readConfidence(b.metadata) - readConfidence(a.metadata));
  byTeam.away.sort((a, b) => readConfidence(b.metadata) - readConfidence(a.metadata));

  const cappedShots = [...byTeam.home.slice(0, 45), ...byTeam.away.slice(0, 45)];
  return [...nonShots, ...cappedShots];
}

async function saveVideoFile(file: File, matchId: number): Promise<string | null> {
  try {
    // Check file size
    if (file.size > MAX_VIDEO_SIZE) {
      throw new Error(`File too large. Maximum size is 10GB.`);
    }

    // Validate video format
    const validTypes = ["video/mp4", "video/webm", "video/quicktime", "video/x-msvideo"];
    const validExtensions = [".mp4", ".webm", ".mov", ".avi"];
    const fileExtension = "." + file.name.split(".").pop()?.toLowerCase();

    if (!validTypes.includes(file.type) && !validExtensions.includes(fileExtension)) {
      throw new Error(`Unsupported video format: ${file.type || fileExtension}. Please use MP4 (H.264), WebM, or MOV.`);
    }

    // Warn if not MP4 (best compatibility)
    if (file.type !== "video/mp4" && !file.name.toLowerCase().endsWith(".mp4")) {
      console.warn(`[saveVideoFile] Video format ${file.type || fileExtension} may not be fully supported. MP4 (H.264) is recommended.`);
    }

    // Create uploads directory
    const uploadsDir = path.join(process.cwd(), "uploads", "videos", `match-${matchId}`);
    if (!existsSync(uploadsDir)) {
      await mkdir(uploadsDir, { recursive: true });
    }

    // Generate unique filename (preserve extension for proper Content-Type detection)
    const timestamp = Date.now();
    const extension = file.name.split(".").pop() || "mp4";
    const filename = `video-${timestamp}.${extension}`;
    const filepath = path.join(uploadsDir, filename);

    // Save file
    const bytes = await file.arrayBuffer();
    const buffer = Buffer.from(bytes);
    await writeFile(filepath, buffer);

    console.log(`[saveVideoFile] Video saved: ${filename}, type: ${file.type}, size: ${file.size} bytes`);

    // Return relative path for analysis
    return filepath;
  } catch (error) {
    console.error("[saveVideoFile] Error:", error);
    throw error;
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import fs from "fs";
import path from "path";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// Chunk size for range requests (4MB)
const CHUNK_SIZE = 4 * 1024 * 1024;

async function resolveMatchId(idParam: string): Promise<number | null> {
  if (/^\d+$/.test(idParam)) {
    return parseInt(idParam, 10);
  }
  const match = await prisma.match.findUnique({
    where: { slug: idParam },
    select: { id: true },
  });
  return match?.id ?? null;
}

/**
 * Handle OPTIONS for CORS preflight
 */
export async function OPTIONS() {
  return new NextResponse(null, {
    status: 200,
    headers: {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, Range",
    },
  });
}

/**
 * Serve match video file
 * GET /api/matches/[id]/video?path=videos/match-9/video-123.mp4
 * 
 * Path is relative to uploads/ directory
 * Supports HTTP Range requests for video streaming
 * CORS enabled for video loading
 */
export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
  }

  const { id } = await params;
  const matchId = await resolveMatchId(id);
  if (!matchId) {
    return NextResponse.json({ ok: false, message: "Invalid match ID" }, { status: 400 });
  }

  // Verify match exists
  const match = await prisma.match.findUnique({ where: { id: matchId } });
  if (!match) {
    return NextResponse.json({ ok: false, message: "Match not found" }, { status: 404 });
  }

  try {
    // Get relative path from query param (relative to uploads/)
    // Expected format: videos/match-9/video-123.mp4
    const relPath = req.nextUrl.searchParams.get("path");
    console.log(`[video] Request: matchId=${matchId}, path=${relPath}`);

    const baseDir = path.resolve(process.cwd(), "uploads");
    const storedVideo = match.videoPath?.trim();

    // Decode URL-encoded path (or fall back to match.videoPath when query omitted — same-origin player often has DB path)
    let decodedPath: string;
    if (relPath) {
      decodedPath = decodeURIComponent(relPath).trim();
    } else if (storedVideo && !/^https?:\/\//i.test(storedVideo)) {
      decodedPath = storedVideo.replace(/\//g, path.sep);
      console.log(`[video] No path query — using match.videoPath`);
    } else {
      console.error("[video] Missing path parameter and no usable match.videoPath");
      return new Response("Missing path parameter", { status: 400 });
    }

    /** Exact file on disk when request path matches the match's stored videoPath (e.g. custom storage drive). */
    let full: string | undefined;
    if (storedVideo && !/^https?:\/\//i.test(storedVideo)) {
      try {
        const resolvedStored = path.resolve(storedVideo);
        const resolvedDecoded = path.resolve(decodedPath);
        if (resolvedStored === resolvedDecoded && fs.existsSync(resolvedStored)) {
          full = resolvedStored;
          console.log(`[video] Serving whitelisted match.videoPath: ${full}`);
        }
      } catch (e) {
        console.warn("[video] Stored path resolve:", e);
      }
    }

    if (!full) {
      // Resolve anything like C:/... or C:\... or /abs/... via path.resolve (fixes Windows + forward slashes from encodeURI)
      const uploadsDir = baseDir;
      let finalRelPath = decodedPath.replace(/^\/+/, "");

      const looksAbsolute =
        path.isAbsolute(decodedPath) || /^[A-Za-z]:[\\/]/.test(decodedPath.trim());

      if (looksAbsolute) {
        const resolvedInput = path.resolve(decodedPath);
        const relFromUploads = path.relative(uploadsDir, resolvedInput);
        if (!relFromUploads.startsWith("..") && !path.isAbsolute(relFromUploads)) {
          finalRelPath = relFromUploads.replace(/\\/g, "/");
        } else {
          const pathMatch = decodedPath.match(/uploads[\/\\]videos[\/\\]match-\d+[\/\\](.+)$/i);
          if (pathMatch) {
            finalRelPath = `videos/match-${matchId}/${pathMatch[1]}`;
          } else {
            console.error(`[video] Cannot map absolute path under uploads: decoded=${decodedPath}`);
            return new Response("Invalid path format", { status: 400 });
          }
        }
      }

      // Client may send "videos/..." or wrongly "uploads/videos/..." — strip leading uploads/ once
      const underUploads = finalRelPath.replace(/^uploads[\\/]/i, "").replace(/\\/g, "/");

      const candidate = path.resolve(path.join(baseDir, underUploads));
      const relativeToBase = path.relative(baseDir, candidate);
      if (relativeToBase.startsWith("..") || path.isAbsolute(relativeToBase)) {
        console.error(`[video] Path traversal attempt: base=${baseDir} full=${candidate}`);
        return new Response("Invalid path", { status: 400 });
      }
      full = candidate;
    }

    if (!fs.existsSync(full)) {
      console.error(`[video] Video not found: ${full}`);
      return new Response("Video not found", { status: 404 });
    }

    const stat = fs.statSync(full);
    const fileSize = stat.size;
    console.log(`[video] File found: ${full}, size=${fileSize} bytes, ext=${path.extname(full)}`);

    if (fileSize === 0) {
      console.error(`[video] Video file is empty: ${full}`);
      return new Response("Video file is empty", { status: 500 });
    }

    // Determine content type from extension
    const ext = path.extname(full).toLowerCase();
    let contentType = "video/mp4"; // Default to mp4
    const mimeMap: Record<string, string> = {
      ".mp4": "video/mp4",
      ".webm": "video/webm",
      ".ogg": "video/ogg",
      ".mov": "video/quicktime",
      ".avi": "video/x-msvideo",
      ".m3u8": "application/vnd.apple.mpegurl",
      ".mkv": "video/x-matroska",
      ".flv": "video/x-flv",
    };
    contentType = mimeMap[ext] || "video/mp4";

    const range = req.headers.get("range");
    console.log(`[video] Range request: ${range || "none"}, Content-Type: ${contentType}`);

    // Handle Range requests for video seeking
    if (range) {
      const [startStr, endStr] = range.replace(/bytes=/, "").split("-");
      const start = parseInt(startStr, 10);

      if (isNaN(start) || start < 0 || start >= fileSize) {
        console.error(`[video] Invalid range start: ${startStr}`);
        return new Response("Invalid range", {
          status: 416,
          headers: {
            "Content-Range": `bytes */${fileSize}`,
            "Accept-Ranges": "bytes",
            "Access-Control-Allow-Origin": "*",
          },
        });
      }

      // Calculate end: if not specified, use CHUNK_SIZE; otherwise use specified end (clamp to file — browsers sometimes overshoot)
      let end = endStr
        ? parseInt(endStr, 10)
        : Math.min(start + CHUNK_SIZE - 1, fileSize - 1);
      if (isNaN(end)) {
        end = Math.min(start + CHUNK_SIZE - 1, fileSize - 1);
      }
      end = Math.min(end, fileSize - 1);

      if (isNaN(end) || start > end || start >= fileSize) {
        console.error(`[video] Invalid range end: ${endStr}, start=${start}, end=${end}, fileSize=${fileSize}`);
        return new Response("Invalid range", {
          status: 416,
          headers: {
            "Content-Range": `bytes */${fileSize}`,
            "Accept-Ranges": "bytes",
            "Access-Control-Allow-Origin": "*",
          },
        });
      }

      const chunkSize = end - start + 1;
      console.log(`[video] Serving range: bytes ${start}-${end}/${fileSize} (chunk=${(chunkSize / 1024 / 1024).toFixed(2)}MB)`);
      const file = fs.createReadStream(full, { start, end });

      return new Response(file as any, {
        status: 206,
        headers: {
          "Content-Range": `bytes ${start}-${end}/${fileSize}`,
          "Accept-Ranges": "bytes",
          "Content-Length": chunkSize.toString(),
          "Content-Type": contentType,
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "GET, OPTIONS",
          "Access-Control-Allow-Headers": "Content-Type, Range",
          "Cache-Control": "public, max-age=3600",
        },
      });
    }

    // Full file response (200 OK)
    console.log(`[video] Serving full file: ${fileSize} bytes`);
    const file = fs.createReadStream(full);
    return new Response(file as any, {
      status: 200,
      headers: {
        "Content-Length": fileSize.toString(),
        "Content-Type": contentType,
        "Accept-Ranges": "bytes",
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Methods": "GET, OPTIONS",
        "Access-Control-Allow-Headers": "Content-Type, Range",
        "Cache-Control": "public, max-age=3600",
      },
    });
  } catch (error) {
    console.error("[video] Error serving video:", error);
    return new Response("Failed to serve video", { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { transcodeToMP4, checkFFmpegAvailable } from "@/lib/video-transcode";
import { join, relative, resolve, normalize, isAbsolute } from "path";
import { existsSync } from "fs";
import { unlink } from "fs/promises";

export const runtime = "nodejs";
export const maxDuration = 600; // 10 minutes for transcoding

async function resolveMatchId(idParam: string): Promise<number | null> {
  if (/^\d+$/.test(idParam)) {
    return parseInt(idParam, 10);
  }
  const match = await prisma.match.findUnique({
    where: { slug: idParam },
    select: { id: true },
  });
  return match?.id ?? null;
}

/**
 * Transcode video to MP4 with H.264 codec
 * POST /api/matches/[id]/video/transcode
 * 
 * Body: { videoPath: string }
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
  }

  const { id } = await params;
  const matchId = await resolveMatchId(id);
  if (!matchId) {
    return NextResponse.json({ ok: false, message: "Invalid match ID" }, { status: 400 });
  }

  // Verify match exists
  const match = await prisma.match.findUnique({ where: { id: matchId } });
  if (!match) {
    return NextResponse.json({ ok: false, message: "Match not found" }, { status: 404 });
  }

  try {
    const body = await request.json();
    const { videoPath } = body;

    if (!videoPath) {
      return NextResponse.json({ ok: false, message: "Video path required" }, { status: 400 });
    }

    // Check if FFmpeg is available
    const ffmpegAvailable = await checkFFmpegAvailable();
    if (!ffmpegAvailable) {
      return NextResponse.json({
        ok: false,
        message: "FFmpeg is not installed on the server. Please install FFmpeg to enable video transcoding.",
      }, { status: 503 });
    }

    const cwd = process.cwd();
    const uploadsVideosDir = join(cwd, "uploads", "videos");
    const rawPath = videoPath.trim();
    const normalizedArg = normalize(rawPath);
    const fullInputPath =
      isAbsolute(normalizedArg) || /^[A-Za-z]:/.test(rawPath)
        ? resolve(normalizedArg)
        : resolve(cwd, normalizedArg);

    // Security: under default uploads/videos OR exact file path stored on this match (custom storage)
    const underUploads = fullInputPath.startsWith(uploadsVideosDir);
    const stored = match.videoPath?.trim();
    const matchesStored =
      !!stored &&
      !/^https?:\/\//i.test(stored) &&
      resolve(stored) === fullInputPath;

    if (!underUploads && !matchesStored) {
      return NextResponse.json({ ok: false, message: "Invalid video path" }, { status: 400 });
    }

    if (!existsSync(fullInputPath)) {
      return NextResponse.json({ ok: false, message: "Video file not found" }, { status: 404 });
    }

    // Generate output path (same directory, with _converted suffix)
    const pathParts = fullInputPath.split(".");
    const extension = pathParts.pop();
    const basePath = pathParts.join(".");
    const outputPath = `${basePath}_converted.${extension || "mp4"}`;

    console.log(`[transcode] Starting transcoding: ${fullInputPath} -> ${outputPath}`);

    // Transcode video
    await transcodeToMP4(fullInputPath, outputPath, (progress) => {
      console.log(`[transcode] Progress: ${progress}%`);
    });

    // Prefer project-relative path; on another drive (custom storage) keep absolute — match page + /video API support both
    const relToCwd = relative(cwd, outputPath).replace(/\\/g, "/");
    const relativeOutputPath =
      relToCwd.startsWith("..") || /^[A-Za-z]:\//.test(relToCwd)
        ? resolve(outputPath).replace(/\\/g, "/")
        : relToCwd;
    console.log(`[transcode] Saving videoPath to database: ${relativeOutputPath}`);
    await prisma.match.update({
      where: { id: matchId },
      data: { videoPath: relativeOutputPath },
    });

    console.log(`[transcode] Transcoding completed: ${outputPath}`);

    // After transcoding, automatically trigger video analysis to create real events
    const eventCount = await prisma.matchEvent.count({
      where: { matchId },
    });

    if (eventCount === 0) {
      console.log(`[transcode] No events found for match ${matchId}. Triggering automatic video analysis...`);

      try {
        // Import and call the analyze endpoint handler directly
        const { POST: analyzePOST } = await import("@/app/api/matches/[id]/video/analyze/route");

        // Determine leftSideTeam (default to "home" if match has homeTeamId)
        const leftSideTeam = match.homeTeamId ? "home" : "away";

        // Converted file on disk (works for project uploads and custom-drive output)
        const absoluteVideoPath = resolve(outputPath);

        // Create a mock request for the analyze endpoint
        const analyzeRequest = new NextRequest(
          new URL(`/api/matches/${matchId}/video/analyze`, request.url),
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              videoPath: absoluteVideoPath, // Use absolute path for analysis
              leftSideTeam,
              teamLeftId: match.homeTeamId,
              teamRightId: match.awayTeamId,
              attackDirection: "left-to-right",
              normalize: true,
            }),
          }
        );

        // Call analyze endpoint asynchronously (don't block transcoding response)
        // This will create real events from video analysis
        analyzePOST(analyzeRequest, { params: Promise.resolve({ id: matchId.toString() }) })
          .then((response) => {
            console.log(`[transcode] Video analysis completed with status: ${response.status}`);
            return response.json();
          })
          .then((data) => {
            if (data.ok) {
              console.log(`[transcode] Video analysis successful. Created ${data.analysis?.eventsDetected || 0} events.`);
            } else {
              console.warn(`[transcode] Video analysis returned error: ${data.message}`);
            }
          })
          .catch((error) => {
            console.error(`[transcode] Video analysis failed:`, error);
            // Don't fail transcoding if analysis fails - user can trigger it manually later
          });

        console.log(`[transcode] Video analysis triggered in background. Events will be created automatically.`);
      } catch (analyzeError) {
        console.error("[transcode] Failed to trigger video analysis:", analyzeError);
        // Don't fail the transcoding if analysis trigger fails
      }
    } else {
      console.log(`[transcode] Match ${matchId} already has ${eventCount} events. Skipping automatic analysis.`);
    }

    return NextResponse.json({
      ok: true,
      message: "Video transcoded successfully. Video analysis is running in the background to create events.",
      videoPath: relativeOutputPath,
      analysisTriggered: eventCount === 0,
    });
  } catch (error: any) {
    console.error("[transcode] Error:", error);
    return NextResponse.json(
      { ok: false, message: error.message || "Failed to transcode video" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getCurrentUser } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { readdir, readFile, unlink, mkdir, rm } from "fs/promises";
import { createWriteStream } from "fs";
import { join } from "path";
import { existsSync } from "fs";

export const runtime = "nodejs";
export const maxDuration = 300; // 5 minutes to assemble

async function resolveMatchId(idParam: string): Promise<number | null> {
  if (/^\d+$/.test(idParam)) {
    return parseInt(idParam, 10);
  }

  const match = await prisma.match.findUnique({
    where: { slug: idParam },
    select: { id: true },
  });
  return match?.id ?? null;
}

/**
 * Complete multipart upload
 * Assembles all parts into final file without buffering entire file in memory
 */
export async function POST(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
  }

  const { id } = await params;
  const matchId = await resolveMatchId(id);

  // Verify match exists
  const match = matchId ? await prisma.match.findUnique({ where: { id: matchId } }) : null;
  if (!match) {
    return NextResponse.json({ ok: false, message: "Match not found" }, { status: 404 });
  }

  try {
    const body = await request.json();
    const { uploadId, fileName, parts, customStoragePath } = body;

    if (!uploadId || !fileName || !parts || !Array.isArray(parts)) {
      return NextResponse.json({ ok: false, message: "Invalid completion parameters" }, { status: 400 });
    }

    // Determine storage directory (custom path or default)
    let baseDir: string;
    if (customStoragePath) {
      // Use custom path (e.g., external drive)
      baseDir = customStoragePath;
    } else {
      // Use default path
      baseDir = join(process.cwd(), "uploads", "videos", `match-${matchId}`);
    }

    // Verify all parts are uploaded
    const partsDir = join(baseDir, "parts", uploadId);
    if (!existsSync(partsDir)) {
      return NextResponse.json({ ok: false, message: "Upload not found" }, { status: 404 });
    }

    // Validate client part list and enforce full integrity from disk.
    const parsedPartNumbers = parts
      .map((p: any) => parseInt(p?.partNumber, 10))
      .filter((n: number) => Number.isInteger(n) && n > 0);
    const uniqueRequestedPartNumbers = Array.from(new Set(parsedPartNumbers)).sort((a, b) => a - b);
    if (uniqueRequestedPartNumbers.length === 0) {
      return NextResponse.json({ ok: false, message: "No valid parts provided" }, { status: 400 });
    }

    // Ground truth from disk: only assemble if every uploaded part is declared and contiguous.
    const diskFiles = await readdir(partsDir);
    const uploadedPartNumbers = diskFiles
      .filter((f) => f.startsWith("part-"))
      .map((f) => parseInt(f.replace("part-", ""), 10))
      .filter((n) => Number.isInteger(n) && n > 0)
      .sort((a, b) => a - b);

    if (uploadedPartNumbers.length === 0) {
      return NextResponse.json({ ok: false, message: "No uploaded parts found" }, { status: 400 });
    }

    const expectedContiguous = Array.from(
      { length: uploadedPartNumbers[uploadedPartNumbers.length - 1] },
      (_, i) => i + 1
    );
    const contiguousOk =
      uploadedPartNumbers.length === expectedContiguous.length &&
      uploadedPartNumbers.every((n, i) => n === expectedContiguous[i]);
    if (!contiguousOk) {
      return NextResponse.json(
        {
          ok: false,
          message:
            "Upload is incomplete or corrupted (missing part numbers). Please resume upload and retry.",
        },
        { status: 400 }
      );
    }

    const requestMatchesDisk =
      uniqueRequestedPartNumbers.length === uploadedPartNumbers.length &&
      uniqueRequestedPartNumbers.every((n, i) => n === uploadedPartNumbers[i]);
    if (!requestMatchesDisk) {
      return NextResponse.json(
        {
          ok: false,
          message:
            "Part manifest mismatch. Please refresh and retry upload completion.",
        },
        { status: 400 }
      );
    }

    const sortedParts = uniqueRequestedPartNumbers.map((partNumber) => ({ partNumber }));

    // Create final video directory
    const videosDir = baseDir;
    if (!existsSync(videosDir)) {
      await mkdir(videosDir, { recursive: true });
    }

    // Generate final filename
    const timestamp = Date.now();
    const extension = fileName.split(".").pop() || "mp4";
    const finalFilename = `video-${timestamp}.${extension}`;
    const finalPath = join(videosDir, finalFilename);

    // Assemble parts using streams (memory-efficient)
    // Read parts in order and append to final file
    const writeStream = createWriteStream(finalPath);

    try {
      for (const part of sortedParts) {
        const partPath = join(partsDir, `part-${part.partNumber}`);

        if (!existsSync(partPath)) {
          writeStream.close();
          return NextResponse.json(
            { ok: false, message: `Part ${part.partNumber} not found` },
            { status: 400 }
          );
        }

        // Read part and append to final file
        const partData = await readFile(partPath);
        await new Promise<void>((resolve, reject) => {
          writeStream.write(partData, (err: Error | null) => {
            if (err) reject(err);
            else resolve();
          });
        });
      }

      // Close write stream
      await new Promise<void>((resolve, reject) => {
        writeStream.end((err: Error | null) => {
          if (err) reject(err);
          else resolve();
        });
      });
    } catch (streamError) {
      writeStream.close();
      throw streamError;
    }

    // Clean up temporary parts
    try {
      for (const part of sortedParts) {
        const partPath = join(partsDir, `part-${part.partNumber}`);
        if (existsSync(partPath)) {
          await unlink(partPath);
        }
      }
      // Remove parts directory if empty
      const remainingFiles = await readdir(partsDir);
      if (remainingFiles.length === 0) {
        await rm(partsDir, { recursive: true, force: true });
      }
    } catch (cleanupError) {
      console.warn("[upload-complete] Cleanup warning:", cleanupError);
      // Don't fail if cleanup fails
    }

    // Return final video path
    // If custom path, return absolute path; otherwise return relative path
    const relativePath = customStoragePath 
      ? finalPath // Absolute path for custom storage
      : `uploads/videos/match-${matchId}/${finalFilename}`; // Relative path for default storage

    // Update match with video path (if videoPath field exists in schema)
    // Note: If videoPath doesn't exist in schema, you may need to add it or store in metadata
    try {
      const pathForDb = relativePath.replace(/\\/g, "/");
      await prisma.match.update({
        where: { id: matchId },
        data: { videoPath: pathForDb },
      });
    } catch (updateError) {
      console.warn("[upload-complete] Could not update match videoPath:", updateError);
      // Continue even if update fails
    }

    return NextResponse.json({
      ok: true,
      videoPath: relativePath,
      fileName: finalFilename,
      message: "Upload completed successfully",
    });
  } catch (error) {
    console.error("[upload-complete] Error:", error);
    return NextResponse.json(
      { ok: false, message: "Failed to complete upload" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";

export async function GET(request: NextRequest) {
  try {
    // Get current user to filter by their teams
    const user = await getCurrentUser();

    const searchParams = request.nextUrl.searchParams;
    const competition = searchParams.get("competition");
    const season = searchParams.get("season");
    const dateFrom = searchParams.get("dateFrom");
    const dateTo = searchParams.get("dateTo");
    const teamId = searchParams.get("teamId");
    const search = searchParams.get("search");
    const limit = searchParams.get("limit");

    const where: any = {};

    // Filter by user's teams if user is logged in
    if (user) {
      // Get user's team IDs (from UserTeam memberships and created teams)
      const userTeams = await prisma.userTeam.findMany({
        where: { userId: user.id, status: "active" },
        select: { teamId: true },
      });

      const createdTeams = await prisma.team.findMany({
        where: { createdById: user.id },
        select: { id: true },
      });

      const userTeamIds = [
        ...userTeams.map((ut) => ut.teamId),
        ...createdTeams.map((t) => t.id),
      ];

      // Only show matches for user's teams
      if (userTeamIds.length > 0) {
        where.OR = [
          { homeTeamId: { in: userTeamIds } },
          { awayTeamId: { in: userTeamIds } },
        ];
      } else {
        // User has no teams - return empty
        return NextResponse.json({ ok: true, matches: [] });
      }
    }

    if (competition && competition !== "All") {
      where.competition = competition;
    }

    if (season && season !== "All") {
      const seasonYear = season.includes("-") ? parseInt(season.split("-")[0]) : parseInt(season);
      if (!isNaN(seasonYear)) {
        where.date = {
          gte: new Date(`${seasonYear}-07-01`),
          lt: new Date(`${seasonYear + 1}-07-01`),
        };
      }
    }

    if (dateFrom) {
      const fromDate = new Date(dateFrom);
      if (!isNaN(fromDate.getTime())) {
        where.date = { ...where.date, gte: fromDate };
      }
    }
    if (dateTo) {
      const toDate = new Date(dateTo);
      if (!isNaN(toDate.getTime())) {
        toDate.setHours(23, 59, 59, 999);
        where.date = { ...where.date, lte: toDate };
      }
    }

    if (teamId) {
      const teamIdNum = parseInt(teamId);
      if (!isNaN(teamIdNum)) {
        where.OR = [
          { homeTeamId: teamIdNum },
          { awayTeamId: teamIdNum },
        ];
      }
    }

    if (search && search.trim()) {
      const searchTerm = search.trim();
      const searchNum = parseInt(searchTerm);
      if (!isNaN(searchNum)) {
        where.OR = [
          ...(where.OR || []),
          { id: searchNum },
        ];
      }
    }

    const matches = await prisma.match.findMany({
      where,
      select: {
        id: true,
        slug: true,
        competition: true,
        venue: true,
        date: true,
        scoreHome: true,
        scoreAway: true,
        xgHome: true,
        xgAway: true,
        shotsHome: true,
        shotsAway: true,
        homeTeamId: true,
        awayTeamId: true,
        homeTeamName: true,
        awayTeamName: true,
        homeTeam: {
          select: { id: true, name: true },
        },
        awayTeam: {
          select: { id: true, name: true },
        },
      },
      orderBy: { date: "desc" },
      take: limit ? parseInt(limit) : undefined,
    });

    return NextResponse.json({ ok: true, matches });
  } catch (error) {
    console.error("[matches.GET] Error:", error);
    return NextResponse.json(
      { ok: false, message: error instanceof Error ? error.message : "Internal server error" },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const user = await getCurrentUser();
    if (!user) {
      return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
    }

    let body;
    try {
      body = await request.json();
      console.log("[matches.POST] Received body:", body);
    } catch (parseError) {
      console.error("[matches.POST] Failed to parse request body:", parseError);
      return NextResponse.json(
        { ok: false, message: "Invalid request data. Please check all fields." },
        { status: 400 }
      );
    }

    const typedBody = body as {
      homeTeamId?: number;
      awayTeamId?: number;
      homeTeamName?: string;
      awayTeamName?: string;
      competition?: string;
      venue?: string;
      date?: string;
      scoreHome?: number;
      scoreAway?: number;
      xgHome?: number;
      xgAway?: number;
      shotsHome?: number;
      shotsAway?: number;
    };

    if (!typedBody.competition || !typedBody.competition.trim()) {
      return NextResponse.json(
        { ok: false, message: "Competition is required" },
        { status: 400 }
      );
    }

    if (!typedBody.date) {
      return NextResponse.json(
        { ok: false, message: "Date is required" },
        { status: 400 }
      );
    }

    const hasHomeTeam = !!(typedBody.homeTeamId || (typedBody.homeTeamName && typedBody.homeTeamName.trim()));
    const hasAwayTeam = !!(typedBody.awayTeamId || (typedBody.awayTeamName && typedBody.awayTeamName.trim()));

    if (!hasHomeTeam) {
      return NextResponse.json(
        { ok: false, message: "Home team is required (either select a registered team or enter opponent name)" },
        { status: 400 }
      );
    }

    if (!hasAwayTeam) {
      return NextResponse.json(
        { ok: false, message: "Away team is required (either select a registered team or enter opponent name)" },
        { status: 400 }
      );
    }

    let homeTeamName: string;
    let awayTeamName: string;

    if (typedBody.homeTeamId) {
      const homeTeam = await prisma.team.findUnique({ where: { id: typedBody.homeTeamId } });
      if (!homeTeam) {
        return NextResponse.json({ ok: false, message: "Home team not found" }, { status: 404 });
      }
      homeTeamName = homeTeam.name;
    } else {
      homeTeamName = typedBody.homeTeamName!.trim();
    }

    if (typedBody.awayTeamId) {
      const awayTeam = await prisma.team.findUnique({ where: { id: typedBody.awayTeamId } });
      if (!awayTeam) {
        return NextResponse.json({ ok: false, message: "Away team not found" }, { status: 404 });
      }
      awayTeamName = awayTeam.name;
    } else {
      awayTeamName = typedBody.awayTeamName!.trim();
    }

    let matchDate: Date;
    try {
      matchDate = new Date(typedBody.date);
      if (isNaN(matchDate.getTime())) {
        return NextResponse.json(
          { ok: false, message: "Invalid date format" },
          { status: 400 }
        );
      }
    } catch (dateError) {
      console.error("[matches.POST] Date parsing error:", dateError);
      return NextResponse.json(
        { ok: false, message: "Invalid date format" },
        { status: 400 }
      );
    }

    const slug = `${homeTeamName.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-vs-${awayTeamName
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")}-${matchDate.toISOString().split("T")[0]}`;

    const existing = await prisma.match.findUnique({ where: { slug } });
    if (existing) {
      return NextResponse.json({ ok: false, message: "A match with these details already exists" }, { status: 409 });
    }

    // Build data object - only include fields that should be set
    const createData: {
      slug: string;
      competition: string;
      venue: string | null;
      date: Date;
      scoreHome: number;
      scoreAway: number;
      xgHome: number;
      xgAway: number;
      shotsHome: number;
      shotsAway: number;
      homeTeamId?: number | null;
      awayTeamId?: number | null;
      homeTeamName?: string | null;
      awayTeamName?: string | null;
    } = {
      slug,
      competition: typedBody.competition.trim(),
      venue: typedBody.venue?.trim() || null,
      date: matchDate,
      scoreHome: typedBody.scoreHome || 0,
      scoreAway: typedBody.scoreAway || 0,
      xgHome: typedBody.xgHome || 0,
      xgAway: typedBody.xgAway || 0,
      shotsHome: typedBody.shotsHome || 0,
      shotsAway: typedBody.shotsAway || 0,
    };

    // Set team fields based on mode
    if (typedBody.homeTeamId) {
      createData.homeTeamId = typedBody.homeTeamId;
      // Don't set homeTeamName when homeTeamId is set
    } else if (typedBody.homeTeamName) {
      createData.homeTeamId = null;
      createData.homeTeamName = typedBody.homeTeamName.trim();
    }

    if (typedBody.awayTeamId) {
      createData.awayTeamId = typedBody.awayTeamId;
      // Don't set awayTeamName when awayTeamId is set
    } else if (typedBody.awayTeamName) {
      createData.awayTeamId = null;
      createData.awayTeamName = typedBody.awayTeamName.trim();
    }

    // Create match - Prisma Client should handle optional teams correctly
    const match = await prisma.match.create({
      data: createData,
      include: {
        homeTeam: {
          select: { id: true, name: true },
        },
        awayTeam: {
          select: { id: true, name: true },
        },
      },
    });

    console.log("[matches.POST] Match created successfully:", match.id);
    return NextResponse.json({ ok: true, match }, { status: 201 });
  } catch (error) {
    console.error("[matches.POST] Unexpected error:", error);
    return NextResponse.json(
      { ok: false, message: error instanceof Error ? error.message : "An unexpected error occurred. Please try again." },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";

// Get user's notifications
export async function GET(request: NextRequest) {
  try {
    const user = await getCurrentUser();
    if (!user) {
      return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
    }

    const searchParams = request.nextUrl.searchParams;
    const unreadOnly = searchParams.get("unreadOnly") === "true";

    const where: any = { userId: user.id };
    if (unreadOnly) {
      where.read = false;
    }

    const notifications = await prisma.notification.findMany({
      where,
      orderBy: {
        createdAt: "desc",
      },
      take: 50, // Limit to 50 most recent
    });

    const unreadCount = await prisma.notification.count({
      where: {
        userId: user.id,
        read: false,
      },
    });

    return NextResponse.json({
      ok: true,
      notifications,
      unreadCount,
    });
  } catch (error) {
    console.error("[notifications] Error:", error);
    return NextResponse.json(
      { ok: false, message: error instanceof Error ? error.message : "Internal server error" },
      { status: 500 }
    );
  }
}

// Mark notification as read
export async function PATCH(request: NextRequest) {
  try {
    const user = await getCurrentUser();
    if (!user) {
      return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
    }

    const body = await request.json();
    const { notificationId, markAllRead } = body;

    if (markAllRead) {
      // Mark all as read
      await prisma.notification.updateMany({
        where: {
          userId: user.id,
          read: false,
        },
        data: {
          read: true,
        },
      });
      return NextResponse.json({ ok: true, message: "All notifications marked as read" });
    }

    if (!notificationId) {
      return NextResponse.json({ ok: false, message: "notificationId is required" }, { status: 400 });
    }

    // Verify notification belongs to user
    const notification = await prisma.notification.findUnique({
      where: { id: parseInt(notificationId) },
    });

    if (!notification || notification.userId !== user.id) {
      return NextResponse.json({ ok: false, message: "Notification not found" }, { status: 404 });
    }

    // Mark as read
    await prisma.notification.update({
      where: { id: parseInt(notificationId) },
      data: { read: true },
    });

    return NextResponse.json({ ok: true, message: "Notification marked as read" });
  } catch (error) {
    console.error("[notifications] Error:", error);
    return NextResponse.json(
      { ok: false, message: error instanceof Error ? error.message : "Internal server error" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export const runtime = "nodejs";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    const playerId = parseInt(id);

    if (isNaN(playerId)) {
      return NextResponse.json({ ok: false, message: "Invalid player ID" }, { status: 400 });
    }

    const searchParams = request.nextUrl.searchParams;
    const eventType = searchParams.get("type") || "all"; // "all", "shot", "pass", "touch"

    // Get all events for this player
    const where: any = { playerId };
    if (eventType !== "all") {
      where.type = eventType;
    }

    const events = await prisma.matchEvent.findMany({
      where,
      select: {
        x: true,
        y: true,
        type: true,
      },
    });

    // Filter valid coordinates
    const validEvents = events.filter(
      (e) => e.x !== null && e.y !== null && !isNaN(Number(e.x)) && !isNaN(Number(e.y))
    );

    // Group by type for different heatmaps
    const heatmapData = {
      all: validEvents.map((e) => ({ x: e.x!, y: e.y! })),
      shots: validEvents.filter((e) => e.type === "shot").map((e) => ({ x: e.x!, y: e.y! })),
      passes: validEvents.filter((e) => e.type === "pass").map((e) => ({ x: e.x!, y: e.y! })),
      touches: validEvents.filter((e) => e.type === "touch").map((e) => ({ x: e.x!, y: e.y! })),
    };

    return NextResponse.json({
      ok: true,
      heatmap: heatmapData[eventType as keyof typeof heatmapData] || heatmapData.all,
      totalEvents: validEvents.length,
    });
  } catch (error) {
    console.error("[player-heatmap] Error:", error);
    return NextResponse.json(
      { ok: false, message: error instanceof Error ? error.message : "Failed to fetch heatmap" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getCurrentUser } from "@/lib/auth";

export const runtime = "nodejs";

export async function GET(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    const user = await getCurrentUser();
    if (!user) {
      return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
    }

    const { id } = await params;
    console.log("[players/[id].GET] Looking for player with slug/id:", id);

    // Get user's team IDs to verify access
    const userTeams = await prisma.userTeam.findMany({
      where: { userId: user.id, status: "active" },
      select: { teamId: true },
    });

    const createdTeams = await prisma.team.findMany({
      where: { createdById: user.id },
      select: { id: true },
    });

    const userTeamIds = [
      ...userTeams.map((ut) => ut.teamId),
      ...createdTeams.map((t) => t.id),
    ];

    // Try to find by slug first, then by id if slug doesn't work
    let player = await prisma.player.findUnique({
      where: { slug: id },
      include: {
        team: {
          select: { id: true, name: true, league: true },
        },
        matchEvents: {
          include: {
            match: {
              select: { id: true, date: true, competition: true },
            },
          },
        },
      },
    });

    // If not found by slug, try by id (in case someone uses numeric id)
    if (!player) {
      const numericId = parseInt(id);
      if (!isNaN(numericId)) {
        console.log("[players/[id].GET] Not found by slug, trying by id:", numericId);
        player = await prisma.player.findUnique({
          where: { id: numericId },
          include: {
            team: {
              select: { id: true, name: true, league: true },
            },
            matchEvents: {
              include: {
                match: {
                  select: { id: true, date: true, competition: true },
                },
              },
            },
          },
        });
        if (player) {
          console.log("[players/[id].GET] Found player by id:", player.id, player.name, "slug:", player.slug);
        }
      } else {
        // If id is not numeric, try to find all players and check their slugs
        console.log("[players/[id].GET] id is not numeric, checking all players for slug match...");
        const allPlayers = await prisma.player.findMany({
          select: { id: true, name: true, slug: true },
          take: 100, // Limit to avoid performance issues
        });
        console.log("[players/[id].GET] Sample players:", allPlayers.slice(0, 5).map(p => ({ id: p.id, name: p.name, slug: p.slug })));
      }
    }

    if (!player) {
      console.log("[players/[id].GET] Player not found with slug/id:", id);
      // Try to get all players to see what slugs exist
      const samplePlayers = await prisma.player.findMany({
        select: { id: true, name: true, slug: true },
        take: 10,
      });
      console.log("[players/[id].GET] Sample players in DB:", samplePlayers.map(p => ({ id: p.id, name: p.name, slug: p.slug })));
      return NextResponse.json({ ok: false, message: `Player not found with slug/id: ${id}` }, { status: 404 });
    }

    console.log("[players/[id].GET] Found player:", player.id, player.name, player.slug);

    // Verify user has access to this player (through team)
    if (player.teamId && !userTeamIds.includes(player.teamId)) {
      return NextResponse.json({ ok: false, message: "You don't have access to this player" }, { status: 403 });
    }
    if (!player.teamId && userTeamIds.length > 0) {
      // Player without team - only allow if user has no teams (edge case)
      return NextResponse.json({ ok: false, message: "You don't have access to this player" }, { status: 403 });
    }

  // Calculate detailed stats from events
  const events = player.matchEvents || [];
  const uniqueMatchIds = new Set(events.map((e) => e.matchId));
  const matchesCount = uniqueMatchIds.size;

  // Calculate game time (max minute per match)
  const matchMinutes = new Map<number, number>();
  events.forEach((event) => {
    if (event.minute !== null) {
      const currentMax = matchMinutes.get(event.matchId) || 0;
      matchMinutes.set(event.matchId, Math.max(currentMax, event.minute));
    }
  });
  const totalMinutes = Array.from(matchMinutes.values()).reduce((sum, min) => sum + min, 0);
  const minutes90 = totalMinutes / 90;

  // Helper to parse metadata
  const parseMetadata = (metadata: string | null): Record<string, any> => {
    if (!metadata) return {};
    try {
      return JSON.parse(metadata);
    } catch {
      return {};
    }
  };

  // Calculate stats
  const shots = events.filter((e) => e.type === "shot");
  const goals = shots.filter((e) => {
    const meta = parseMetadata(e.metadata);
    return meta.outcome === "goal";
  }).length;
  const shotsOnTarget = shots.filter((e) => {
    const meta = parseMetadata(e.metadata);
    return meta.outcome === "on_target" || meta.outcome === "goal";
  }).length;
  const totalXG = shots.reduce((sum, e) => sum + (e.xg || 0), 0);
  const averageXG = shots.length > 0 ? totalXG / shots.length : 0;

  const passes = events.filter((e) => e.type === "pass");
  const successfulPasses = passes.filter((e) => {
    const meta = parseMetadata(e.metadata);
    return meta.outcome === "successful";
  }).length;
  const passAccuracy = passes.length > 0 ? (successfulPasses / passes.length) * 100 : 0;

  const touches = events.filter((e) => e.type === "touch").length;
  const tackles = events.filter((e) => e.type === "tackle").length;
  const interceptions = events.filter((e) => e.type === "interception").length;
  const clearances = events.filter((e) => e.type === "clearance").length;
  const blocks = events.filter((e) => e.type === "block").length;
  const fouls = events.filter((e) => e.type === "foul").length;

  // Calculate key passes (passes that lead to shots)
  const keyPasses = passes.filter((p) => {
    return shots.some(
      (s) =>
        s.matchId === p.matchId &&
        s.minute !== null &&
        p.minute !== null &&
        s.minute > p.minute &&
        s.minute <= p.minute + 1
    );
  }).length;

  // Calculate progressive passes (passes that advance the ball significantly)
  // A pass is progressive if it moves the ball into the final third (y < 33.33)
  // or if it has end coordinates and moves forward significantly
  const progressivePasses = passes.filter((p) => {
    if (p.x === null || p.y === null) return false;
    const pMeta = parseMetadata(p.metadata);
    if (pMeta.outcome !== "successful") return false;

    // Check if pass is into final third (most common progressive pass)
    if (p.y < 33.33) return true;

    // Check if pass has end coordinates and moves forward significantly
    if (pMeta.endX !== undefined && pMeta.endY !== undefined) {
      const forwardDistance = p.y - pMeta.endY; // Forward = lower y value
      if (forwardDistance >= 10) return true; // At least 10% forward
    }

    return false;
  }).length;

  // Passes into final third (y < 33.33)
  const passesIntoFinalThird = passes.filter((p) => {
    if (p.y === null) return false;
    const pMeta = parseMetadata(p.metadata);
    return pMeta.outcome === "successful" && p.y < 33.33;
  }).length;

  // Passes into penalty area (y < ~15.7, which is approximately the penalty area line)
  const passesIntoPenaltyArea = passes.filter((p) => {
    if (p.y === null) return false;
    const pMeta = parseMetadata(p.metadata);
    return pMeta.outcome === "successful" && p.y < 15.7;
  }).length;

  // Long passes (passes with distance > 30% of pitch)
  const longPasses = passes.filter((p) => {
    if (p.x === null || p.y === null) return false;
    const pMeta = parseMetadata(p.metadata);
    if (pMeta.outcome !== "successful") return false;
    if (pMeta.endX !== undefined && pMeta.endY !== undefined) {
      const distance = Math.sqrt(
        Math.pow((pMeta.endX - p.x), 2) + Math.pow((pMeta.endY - p.y), 2)
      );
      return distance > 30; // More than 30% of pitch
    }
    return false;
  }).length;

  // Calculate assists
  let assists = 0;
  const goalsByMatch = new Map<number, typeof shots>();
  shots.filter((s) => {
    const meta = parseMetadata(s.metadata);
    return meta.outcome === "goal";
  }).forEach((goal) => {
    if (goal.matchId) {
      if (!goalsByMatch.has(goal.matchId)) {
        goalsByMatch.set(goal.matchId, []);
      }
      goalsByMatch.get(goal.matchId)!.push(goal);
    }
  });

  goalsByMatch.forEach((matchGoals, matchId) => {
    matchGoals.forEach((goal) => {
      const assistPass = passes.find(
        (p) => {
          const pMeta = parseMetadata(p.metadata);
          return (
            p.matchId === matchId &&
            p.minute !== null &&
            goal.minute !== null &&
            p.minute <= goal.minute &&
            p.minute >= goal.minute - 2 &&
            pMeta.outcome === "successful"
          );
        }
      );
      if (assistPass) assists++;
    });
  });

  // Calculate xA
  const xA = passes
    .filter((p) => {
      return shots.some(
        (s) =>
          s.matchId === p.matchId &&
          s.minute !== null &&
          p.minute !== null &&
          s.minute > p.minute &&
          s.minute <= p.minute + 1
      );
    })
    .reduce((sum, p) => {
      const resultingShot = shots.find(
        (s) =>
          s.matchId === p.matchId &&
          s.minute !== null &&
          p.minute !== null &&
          s.minute > p.minute &&
          s.minute <= p.minute + 1
      );
      return sum + (resultingShot?.xg || 0);
    }, 0);

  // Per 90 normalization
  const normalizePer90 = (value: number) => {
    return minutes90 > 0 ? (value / minutes90) * 90 : 0;
  };

  const detailedStats = {
    matches: matchesCount,
    minutes: totalMinutes,
    goals,
    assists,
    shots: shots.length,
    shotsOnTarget,
    totalXG: Math.round(totalXG * 100) / 100,
    averageXG: Math.round(averageXG * 100) / 100,
    xA: Math.round(xA * 100) / 100,
    passes: passes.length,
    successfulPasses,
    passAccuracy: Math.round(passAccuracy * 10) / 10,
    keyPasses,
    progressivePasses,
    passesIntoFinalThird,
    passesIntoPenaltyArea,
    longPasses,
    touches,
    tackles,
    interceptions,
    clearances,
    blocks,
    fouls,
    // Per 90 stats
    goalsPer90: Math.round(normalizePer90(goals) * 10) / 10,
    assistsPer90: Math.round(normalizePer90(assists) * 10) / 10,
    shotsPer90: Math.round(normalizePer90(shots.length) * 10) / 10,
    xGPer90: Math.round(normalizePer90(totalXG) * 100) / 100,
    xAPer90: Math.round(normalizePer90(xA) * 100) / 100,
    passesPer90: Math.round(normalizePer90(passes.length) * 10) / 10,
    keyPassesPer90: Math.round(normalizePer90(keyPasses) * 10) / 10,
    progressivePassesPer90: Math.round(normalizePer90(progressivePasses) * 10) / 10,
    touchesPer90: Math.round(normalizePer90(touches) * 10) / 10,
    tacklesPer90: Math.round(normalizePer90(tackles) * 10) / 10,
    interceptionsPer90: Math.round(normalizePer90(interceptions) * 10) / 10,
    conversionRate: shots.length > 0 ? Math.round((goals / shots.length) * 1000) / 10 : 0,
  };

    return NextResponse.json({ 
      ok: true, 
      player: {
        ...player,
        matchEvents: undefined, // Remove events from response
      },
      stats: detailedStats,
    });
  } catch (error) {
    console.error("[players/[id].GET] Error:", error);
    return NextResponse.json(
      { ok: false, message: error instanceof Error ? error.message : "Internal server error" },
      { status: 500 }
    );
  }
}

export async function PATCH(request: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) {
    return NextResponse.json({ ok: false, message: "Unauthorized" }, { status: 401 });
  }

