          </div>

          {source === "matches" && (
            <div className="space-y-1.5">
              <label className="text-[11px] text-slate-300">Match (Optional)</label>
              <select
                value={selectedMatch}
                onChange={(e) => setSelectedMatch(e.target.value)}
