  name: string;
  shooting: number;
  creativity: number;
  passing: number;
  involvement: number;
  efficiency: number;
}

interface PlayerRadarChartProps {
  players: Array<{
    name: string;
    radarMetrics: {
      shooting: number;
      creativity: number;
      passing: number;
      involvement: number;
      efficiency: number;
    };
  }>;
  mode?: "all" | "attacking" | "passing";
}

export function PlayerRadarChart({ players, mode = "all" }: PlayerRadarChartProps) {
  // Need at least 2 players for comparison
  if (players.length < 2) {
    return (
      <div className="rounded-lg border border-slate-800 bg-slate-950 p-8 text-center">
        <p className="text-sm text-slate-400">Select at least 2 players to see radar comparison</p>
      </div>
    );
  }

  const axesByMode: Record<"all" | "attacking" | "passing", Array<{ label: string; key: keyof PlayerRadarChartProps["players"][number]["radarMetrics"] }>> = {
    all: [
      { label: "Shooting", key: "shooting" },
      { label: "Creativity", key: "creativity" },
      { label: "Passing", key: "passing" },
      { label: "Involvement", key: "involvement" },
      { label: "Efficiency", key: "efficiency" },
    ],
    attacking: [
      { label: "Shooting", key: "shooting" },
      { label: "Creativity", key: "creativity" },
      { label: "Efficiency", key: "efficiency" },
    ],
    passing: [
      { label: "Passing", key: "passing" },
      { label: "Creativity", key: "creativity" },
      { label: "Involvement", key: "involvement" },
    ],
  };
  const selectedAxes = axesByMode[mode];

  // Prepare data for radar chart
  const radarData: PlayerRadarData[] = selectedAxes.map((axis) => ({
    name: axis.label,
    ...players.reduce((acc, player, idx) => {
      acc[`player${idx}`] = player.radarMetrics[axis.key];
      return acc;
    }, {} as Record<string, number>),
  }));

  const metricKeys = players.map((_, idx) => `player${idx}`);
  const maxMetricValue = Math.max(
    0,
    ...radarData.flatMap((axis) =>
      metricKeys.map((key) => {
        const value = (axis as Record<string, number | string>)[key];
        return typeof value === "number" && Number.isFinite(value) ? value : 0;
      })
    )
  );
  const radarDomainMax =
    maxMetricValue <= 5
      ? 5
      : maxMetricValue <= 10
      ? 10
      : maxMetricValue <= 20
      ? 20
      : maxMetricValue <= 40
      ? 40
      : maxMetricValue <= 60
      ? 60
      : maxMetricValue <= 80
      ? 80
      : 100;

  const colors = ["#10b981", "#3b82f6", "#f59e0b", "#ef4444", "#8b5cf6"];
  const dashPatterns = ["0", "6 4", "3 3", "10 4", "2 2"];
  const fillOpacities = [0.22, 0.16, 0.12, 0.1, 0.08];
  const seriesVisibility = players.map((player, idx) => ({
    name: player.name,
    dataKey: `player${idx}`,
    color: colors[idx % colors.length],
    hasAnyNonZero: Object.values(player.radarMetrics).some((v) => v > 0),
    allZero: Object.values(player.radarMetrics).every((v) => v === 0),
  }));

  return (
    <div className="rounded-xl border border-slate-800 bg-slate-950 p-6">
      <div className="mb-6">
        <h3 className="text-base font-semibold text-slate-100 mb-1">Performance Radar Comparison</h3>
        <p className="text-[11px] text-slate-400">
          {mode === "attacking"
            ? "Attacking profile"
            : mode === "passing"
            ? "Passing profile"
            : "Multi-dimensional player analysis"}
        </p>
      </div>
      <ResponsiveContainer width="100%" height={400}>
        <RadarChart data={radarData} margin={{ top: 20, right: 30, bottom: 20, left: 30 }}>
          <PolarGrid 
            stroke="#334155" 
            strokeWidth={1}
            strokeDasharray="4 4"
            opacity={0.5}
          />
          <PolarAngleAxis
            dataKey="name"
            tick={{ 
              fill: "#94a3b8", 
              fontSize: 12,
              fontWeight: 500
            }}
          />
          <PolarRadiusAxis
            angle={90}
            domain={[0, radarDomainMax]}
            tick={{ 
              fill: "#64748b", 
              fontSize: 10
            }}
            tickCount={6}
          />
          {players.map((player, idx) => (
            <Radar
              key={player.name}
              name={player.name}
              dataKey={`player${idx}`}
              stroke={colors[idx % colors.length]}
              fill={colors[idx % colors.length]}
              fillOpacity={fillOpacities[idx % fillOpacities.length]}
              strokeWidth={2.4}
              strokeDasharray={dashPatterns[idx % dashPatterns.length]}
              dot={{ fill: colors[idx % colors.length], r: 3, strokeWidth: 1.5, stroke: "#fff" }}
            />
          ))}
          <Legend
            wrapperStyle={{ paddingTop: "20px" }}
            iconType="circle"
            iconSize={8}
            formatter={(value) => (
              <span className="text-xs text-slate-300 ml-2">{value}</span>
            )}
            content={({ payload }) => (
              <div className="flex flex-wrap justify-center gap-4 mt-4">
                {payload?.map((entry, index) => (
                  <div key={index} className="flex items-center gap-2">
                    <div 
                      className="w-2.5 h-2.5 rounded-full" 
                      style={{ backgroundColor: entry.color }}
                    />
                    <span className="text-xs text-slate-300">{entry.value}</span>
                  </div>
                ))}
              </div>
            )}
          />
        </RadarChart>
      </ResponsiveContainer>
      <div className={`mt-4 grid gap-2 text-[10px] border-t border-slate-800 pt-4 ${mode === "all" ? "grid-cols-2 md:grid-cols-5" : "grid-cols-3"}`}>
        {selectedAxes.map((axis) => (
          <div key={axis.key} className="text-center">
            <p className="font-medium text-slate-300 mb-0.5">{axis.label}</p>
            <p className="text-slate-500 text-[9px]">
              {axis.key === "shooting"
                ? "Shots/xG/goals blend"
                : axis.key === "creativity"
                ? "xA/assists blend"
                : axis.key === "passing"
                ? "Volume + accuracy"
                : axis.key === "involvement"
                ? "Touches per 90"
                : "On-target/conversion"}
            </p>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from "recharts";

interface TrendData {
  matchId: number;
  date: string;
  opponent: string;
  competition: string;
  goals: number;
  assists: number;
  xg: number;
  xa: number;
  shots: number;
  passes: number;
  touches: number;
}

interface PlayerTrendsChartProps {
  trends: TrendData[];
  metric: "goals" | "assists" | "xg" | "xa" | "shots" | "passes";
  title: string;
}

export function PlayerTrendsChart({ trends, metric, title }: PlayerTrendsChartProps) {
  // Format data for chart
  const chartData = trends.map((trend, idx) => {
    const date = new Date(trend.date);
    const matchLabel = `${date.toLocaleDateString("en-GB", {
      day: "2-digit",
      month: "short",
    })} vs ${trend.opponent}`;

    return {
      match: `Match ${idx + 1}`,
      matchLabel,
      date: date.toISOString(),
      [metric]: trend[metric],
    };
  });

  // Color mapping for different metrics
  const colorMap: Record<string, string> = {
    goals: "#fbbf24", // amber-400
    assists: "#34d399", // emerald-400
    xg: "#34d399", // emerald-400
    xa: "#38bdf8", // sky-400
    shots: "#a78bfa", // violet-400
    passes: "#f472b6", // pink-400
  };

  const color = colorMap[metric] || "#34d399";

  if (trends.length === 0) {
    return (
      <div className="flex h-64 items-center justify-center rounded-lg border border-slate-800 bg-slate-950">
        <p className="text-sm text-slate-500">No match data available</p>
      </div>
    );
  }

  // Calculate average and trend
  const values = chartData.map(d => d[metric] as number);
  const average = values.length > 0 ? values.reduce((a, b) => a + b, 0) / values.length : 0;
  const maxValue = Math.max(...values, 0);

  return (
    <div className="group relative overflow-hidden rounded-xl border border-slate-800 bg-gradient-to-br from-slate-950/90 to-slate-900/90 p-4 transition-all hover:border-slate-700 hover:shadow-xl hover:shadow-emerald-500/5">
      <div className="flex items-center justify-between mb-3">
        <div>
          <p className="text-[11px] font-semibold text-slate-200">{title}</p>
          <p className="text-[9px] text-slate-500 mt-0.5">Performance trend</p>
        </div>
        <div className="text-right">
          <p className="text-[10px] text-slate-500">Average</p>
          <p className="text-[11px] font-bold" style={{ color: color }}>
            {average.toFixed(metric === "xg" || metric === "xa" ? 2 : 1)}
          </p>
        </div>
      </div>
      <ResponsiveContainer width="100%" height={220}>
        <LineChart
          data={chartData}
          margin={{ top: 10, right: 15, left: -10, bottom: 40 }}
        >
          <defs>
            <linearGradient id={`gradient-${metric}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor={color} stopOpacity={0.3} />
              <stop offset="95%" stopColor={color} stopOpacity={0.05} />
            </linearGradient>
          </defs>
          <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" opacity={0.3} />
          <XAxis
            dataKey="match"
            stroke="#64748b"
            tick={{ fill: "#94a3b8", fontSize: 9 }}
            angle={-45}
            textAnchor="end"
            height={50}
            interval={Math.floor(chartData.length / 6)} // Show ~6 labels
          />
          <YAxis
            stroke="#64748b"
            tick={{ fill: "#94a3b8", fontSize: 9 }}
            domain={[0, "auto"]}
            width={35}
          />
          <Tooltip
            contentStyle={{
              backgroundColor: "#0f172a",
              border: `1px solid ${color}40`,
              borderRadius: "8px",
              fontSize: "11px",
              padding: "8px 12px",
              boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.3)",
            }}
            labelStyle={{ color: "#cbd5e1", fontWeight: 600, marginBottom: "4px" }}
            formatter={(value: number) => [
              <span key="value" style={{ color, fontWeight: 700 }}>
                {value.toFixed(metric === "xg" || metric === "xa" ? 2 : 0)}
              </span>,
              title
            ]}
            labelFormatter={(label, payload) => {
              if (payload && payload[0]) {
                const data = payload[0].payload as typeof chartData[0];
                return data.matchLabel;
              }
              return label;
            }}
            cursor={{ stroke: color, strokeWidth: 1, strokeDasharray: "3 3" }}
          />
          <Line
            type="monotone"
            dataKey={metric}
            stroke={color}
            strokeWidth={2.5}
            dot={{ fill: color, r: 3, strokeWidth: 2, stroke: "#0f172a" }}
            activeDot={{ r: 5, fill: color, stroke: "#0f172a", strokeWidth: 2 }}
            name={title}
          />
        </LineChart>
      </ResponsiveContainer>
      <div className="mt-2 flex items-center justify-between text-[9px] text-slate-500">
        <span>Max: {maxValue.toFixed(metric === "xg" || metric === "xa" ? 2 : 0)}</span>
        <span>{trends.length} matches</span>
      </div>
    </div>
  );
}

"use client";

import { useState, FormEvent, useEffect } from "react";
import toast from "react-hot-toast";

interface PlaylistModalProps {
  isOpen: boolean;
  onClose: () => void;
  onPlaylistSuccess?: () => void;
}

export function PlaylistModal({ isOpen, onClose, onPlaylistSuccess }: PlaylistModalProps) {
  const [creating, setCreating] = useState(false);
  const [playlistName, setPlaylistName] = useState("");
  const [description, setDescription] = useState("");
  const [matchId, setMatchId] = useState("");
  const [matches, setMatches] = useState<any[]>([]);

  useEffect(() => {
    if (isOpen) {
      fetch("/api/matches")
        .then((res) => res.json())
        .then((data) => {
          if (data.ok) {
            setMatches(data.matches || []);
          }
        })
        .catch(() => {});
    }
  }, [isOpen]);

  if (!isOpen) return null;

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    if (!playlistName.trim()) {
      toast.error("Please enter a playlist name");
      return;
    }

    setCreating(true);
    try {
      const res = await fetch("/api/playlists", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: playlistName,
          description,
          matchId: matchId ? parseInt(matchId) : null,
        }),
      });

      const data = await res.json();

      if (res.ok && data.ok) {
        toast.success("Playlist created successfully!");
        onPlaylistSuccess?.();
        onClose();
        // Reset form
        setPlaylistName("");
        setDescription("");
        setMatchId("");
      } else {
        toast.error(data.message || "Failed to create playlist");
      }
    } catch (error) {
      toast.error("Network error. Please try again.");
    } finally {
      setCreating(false);
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
      <div className="relative w-full max-w-lg rounded-xl border border-slate-800 bg-slate-950 p-6 text-xs text-slate-200 shadow-2xl">
        <button
          onClick={onClose}
          className="absolute right-4 top-4 text-slate-400 hover:text-slate-200 transition text-xl font-bold leading-none"
        >
          ×
        </button>

        <div className="mb-4">
          <h2 className="text-lg font-semibold text-white">New Playlist</h2>
          <p className="text-[11px] text-slate-400 mt-1">
            Create a new playlist to organize video clips and key moments.
          </p>
        </div>

        <form className="space-y-4" onSubmit={handleSubmit}>
          <div className="space-y-1.5">
            <label className="text-[11px] text-slate-300">Playlist Name *</label>
            <input
              type="text"
              value={playlistName}
              onChange={(e) => setPlaylistName(e.target.value)}
              className="h-8 w-full rounded-md border border-slate-800 bg-slate-900 px-2 text-[11px] text-slate-100 outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500/60"
              placeholder="e.g., High Press Moments"
              required
            />
          </div>

          <div className="space-y-1.5">
            <label className="text-[11px] text-slate-300">Description</label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={3}
              className="w-full rounded-md border border-slate-800 bg-slate-900 px-2 py-2 text-[11px] text-slate-100 outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500/60 resize-none"
              placeholder="Optional description..."
            />
          </div>

          <div className="space-y-1.5">
            <label className="text-[11px] text-slate-300">Match (Optional)</label>
            <select
              value={matchId}
              onChange={(e) => setMatchId(e.target.value)}
              className="h-8 w-full rounded-md border border-slate-800 bg-slate-900 px-2 text-[11px] text-slate-100 outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500/60"
            >
              <option value="">No specific match</option>
              {matches.map((match) => (
                <option key={match.id} value={match.id}>
                  {match.homeTeam?.name || "Home"} vs {match.awayTeam?.name || "Away"} - {new Date(match.date).toLocaleDateString()}
                </option>
              ))}
            </select>
          </div>

          <div className="flex gap-3 pt-2">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 h-9 rounded-md border border-slate-700 bg-slate-900 text-[11px] font-semibold text-slate-200 hover:bg-slate-800 transition"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={creating}
              className="flex-1 h-9 rounded-md bg-emerald-500 text-[11px] font-semibold text-slate-950 hover:bg-emerald-400 disabled:cursor-not-allowed disabled:opacity-60 transition"
            >
              {creating ? "Creating..." : "Create Playlist"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

