"use client";

import { useMemo, useState } from "react";
import type { ShotEvent } from "./ShotAnalytics";

interface ShotHeatmapProps {
  shots: ShotEvent[];
  homeTeamName: string;
  awayTeamName: string;
  homeTeamId?: string;
  awayTeamId?: string;
}

const PITCH_WIDTH = 900;
const PITCH_HEIGHT = 520;

export function ShotHeatmap({ shots, homeTeamName, awayTeamName, homeTeamId, awayTeamId }: ShotHeatmapProps) {
  const [hoveredShot, setHoveredShot] = useState<ShotEvent | null>(null);
  const [selectedShot, setSelectedShot] = useState<ShotEvent | null>(null);

  // Separate shots by team
  const { homeShots, awayShots } = useMemo(() => {
    const home: ShotEvent[] = [];
    const away: ShotEvent[] = [];

    shots.forEach((shot) => {
      const byTeamId =
        (homeTeamId && shot.teamId === homeTeamId) ? "home" :
        (awayTeamId && shot.teamId === awayTeamId) ? "away" :
        null;
      const byTeamFlag = shot.team || null;
      const team = byTeamId || byTeamFlag;

      // Use actual team mapping; only fallback to x-position when no team info exists.
      if (team === "home") {
        home.push(shot);
      } else if (team === "away") {
        away.push(shot);
      } else if (shot.x < 0.5) {
        home.push(shot);
      } else {
        away.push(shot);
      }
    });

    return { homeShots: home, awayShots: away };
  }, [shots, homeTeamId, awayTeamId]);

  // Convert normalized coordinates (0-1) to SVG coordinates
  const normalizeX = (x: number) => Math.max(10, Math.min(PITCH_WIDTH - 10, x * PITCH_WIDTH));
  const normalizeY = (y: number) => Math.max(10, Math.min(PITCH_HEIGHT - 10, y * PITCH_HEIGHT));

  const applyDeclustering = (
    shotEntries: Array<{ shot: ShotEvent; teamColor: string }>
  ) => {
    const points = shotEntries.map(({ shot, teamColor }) => ({
      shot,
      teamColor,
      baseX: normalizeX(shot.x),
      baseY: normalizeY(shot.y),
      displayX: normalizeX(shot.x),
      displayY: normalizeY(shot.y),
    }));

    /** Merge into one cluster when shots are within this SVG distance (pairwise → union-find). */
    const CLUSTER_MERGE_EPS = 72;

    const clusterIndices = (): number[][] => {
      const n = points.length;
      const parent = Array.from({ length: n }, (_, i) => i);
      const find = (i: number): number => {
        if (parent[i] !== i) parent[i] = find(parent[i]);
        return parent[i];
      };
      const union = (a: number, b: number) => {
        const ra = find(a);
        const rb = find(b);
        if (ra !== rb) parent[ra] = rb;
      };
      const eps2 = CLUSTER_MERGE_EPS * CLUSTER_MERGE_EPS;
      for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
          const dx = points[j].baseX - points[i].baseX;
          const dy = points[j].baseY - points[i].baseY;
          if (dx * dx + dy * dy <= eps2) union(i, j);
        }
      }
      const map = new Map<number, number[]>();
      for (let i = 0; i < n; i++) {
        const r = find(i);
        if (!map.has(r)) map.set(r, []);
        map.get(r)!.push(i);
      }
      return Array.from(map.values());
    };

    const clusters = clusterIndices();
    for (const idxs of clusters) {
      if (idxs.length <= 1) continue;
      let cx = 0;
      let cy = 0;
      for (const idx of idxs) {
        cx += points[idx].baseX;
        cy += points[idx].baseY;
      }
      cx /= idxs.length;
      cy /= idxs.length;
      const n = idxs.length;
      const R = Math.min(108, Math.max(34, 14 + n * 7));
      idxs.forEach((idx, k) => {
        const angle = (Math.PI * 2 * k) / n - Math.PI / 2;
        points[idx].displayX = cx + Math.cos(angle) * R;
        points[idx].displayY = cy + Math.sin(angle) * R;
      });
    }

    for (const point of points) {
      point.displayX = Math.max(10, Math.min(PITCH_WIDTH - 10, point.displayX));
      point.displayY = Math.max(10, Math.min(PITCH_HEIGHT - 10, point.displayY));
    }

    return points;
  };

  const displayShots = useMemo(
    () =>
      applyDeclustering([
        ...homeShots.map((shot) => ({ shot, teamColor: "#3b82f6" })),
        ...awayShots.map((shot) => ({ shot, teamColor: "#ef4444" })),
      ]),
    [homeShots, awayShots]
  );

  const focusedShot = selectedShot ?? hoveredShot;

  // Get icon and color for shot outcome
  const getShotIcon = (shot: ShotEvent) => {
    const isGoal = shot.goal || shot.outcome === "Goal";
    const isOnGoal = shot.outcome === "OnGoal" || isGoal;
    const isWide = shot.outcome === "Wide";
    const isBlocked = shot.outcome === "Blocked";

    if (isGoal) {
      return { symbol: "★", color: "#fbbf24", size: 12 }; // Gold star
    } else if (isOnGoal) {
      return { symbol: "◎", color: "#3b82f6", size: 10 }; // Blue circle
    } else if (isWide) {
      return { symbol: "○", color: "#ef4444", size: 10 }; // Red circle
    } else if (isBlocked) {
      return { symbol: "✖", color: "#6b7280", size: 10 }; // Gray X
    }
    return { symbol: "○", color: "#9ca3af", size: 9 }; // Default gray
  };

  const renderShots = (
    shotEntries: Array<{
      shot: ShotEvent;
      teamColor: string;
      baseX: number;
      baseY: number;
      displayX: number;
      displayY: number;
    }>
  ) => {
    return shotEntries.map((entry, idx) => {
      const { shot, teamColor, displayX, displayY } = entry;
      const icon = getShotIcon(shot);
      const x = displayX;
      const y = displayY;
      const isHovered = focusedShot === shot;

      return (
        <g key={`shot-${teamColor}-${shot.playerName}-${shot.timeSec}-${idx}`} data-shot-marker>
          {/* Hover circle */}
          {isHovered && (
            <circle
              cx={x}
              cy={y}
              r={15}
              fill={icon.color}
              opacity={0.2}
              className="animate-pulse"
            />
          )}
          {/* Shot icon */}
          <circle
            cx={x}
            cy={y}
            r={icon.size}
            fill={icon.color}
            stroke={isHovered ? "#fff" : "rgba(255,255,255,0.3)"}
            strokeWidth={isHovered ? 2 : 1}
            className="cursor-pointer transition-all"
            onMouseEnter={() => setHoveredShot(shot)}
            onMouseLeave={() => setHoveredShot((prev) => (prev === shot ? null : prev))}
            onClick={(e) => {
              e.stopPropagation();
              setSelectedShot((prev) => (prev === shot ? null : shot));
            }}
          />
          {/* Symbol overlay */}
          <text
            x={x}
            y={y + 4}
            fontSize={icon.size * 0.8}
            fill="#fff"
            textAnchor="middle"
            fontWeight="bold"
            pointerEvents="none"
          >
            {icon.symbol}
          </text>
        </g>
      );
    });
  };

  return (
    <div className="relative">
      <svg
        viewBox={`0 0 ${PITCH_WIDTH} ${PITCH_HEIGHT}`}
        width="100%"
        height="100%"
        className="rounded-lg"
        style={{ maxHeight: "520px", background: "#0f1923" }}
        onClick={(e) => {
          const t = e.target as Element;
          if (!t.closest?.("[data-shot-marker]")) setSelectedShot(null);
        }}
      >
        {/* Pitch background */}
        <rect width={PITCH_WIDTH} height={PITCH_HEIGHT} fill="#0f1923" rx="8" />

        {/* Pitch lines */}
        <g stroke="rgba(255,255,255,0.08)" strokeWidth="2" fill="none">
          {/* Outer border */}
          <rect x="6" y="6" width={PITCH_WIDTH - 12} height={PITCH_HEIGHT - 12} rx="10" />
          {/* Center line */}
          <line x1={PITCH_WIDTH / 2} y1="0" x2={PITCH_WIDTH / 2} y2={PITCH_HEIGHT} />
          {/* Goal boxes */}
          <rect x="6" y={PITCH_HEIGHT * 0.3} width={PITCH_WIDTH * 0.1} height={PITCH_HEIGHT * 0.4} />
          <rect
            x={PITCH_WIDTH - 6 - PITCH_WIDTH * 0.1}
            y={PITCH_HEIGHT * 0.3}
            width={PITCH_WIDTH * 0.1}
            height={PITCH_HEIGHT * 0.4}
          />
          {/* Center circle */}
          <circle cx={PITCH_WIDTH / 2} cy={PITCH_HEIGHT / 2} r={PITCH_HEIGHT * 0.12} />
        </g>

        {/* Render shots */}
        {renderShots(displayShots)}
      </svg>

      {/* Tooltip */}
      {focusedShot && (
        <div
          className="absolute z-20 rounded-xl border border-emerald-500/40 bg-gradient-to-br from-[#0b1220] to-[#0f1620] px-4 py-3 shadow-2xl backdrop-blur-sm"
          style={{
            left: `${(((displayShots.find((entry) => entry.shot === focusedShot)?.displayX ?? (focusedShot.x * PITCH_WIDTH)) / PITCH_WIDTH) * 100)}%`,
            top: `${(((displayShots.find((entry) => entry.shot === focusedShot)?.displayY ?? (focusedShot.y * PITCH_HEIGHT)) / PITCH_HEIGHT) * 100)}%`,
            transform: "translate(-50%, -100%)",
            marginTop: "-12px",
            pointerEvents: "none",
          }}
        >
          <div className="text-[11px] space-y-1.5">
            <div className="flex items-center gap-2 mb-1">
              <div className="h-6 w-6 rounded-full bg-emerald-500/20 flex items-center justify-center">
                <svg className="h-3 w-3 text-emerald-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                </svg>
              </div>
              <p className="font-bold text-white">{focusedShot.playerName}</p>
            </div>
            <div className="flex items-center gap-2 text-white/80">
              <svg className="h-3 w-3 text-white/60" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              <span>{Math.floor(focusedShot.timeSec / 60)}' {focusedShot.timeSec % 60}"</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="h-5 w-5 rounded bg-emerald-500/20 flex items-center justify-center">
                <span className="text-[9px] font-bold text-emerald-400">xG</span>
              </div>
              <p className="font-semibold text-emerald-400">
                {(focusedShot.xg || 0).toFixed(2)}
              </p>
            </div>
            <div className="pt-1 border-t border-white/10">
              <p className="text-white/70 text-[10px] font-medium">
                {focusedShot.outcome || (focusedShot.goal ? "Goal" : "Shot")}
              </p>
              {focusedShot.shotType && (
                <p className="text-white/50 text-[9px] mt-0.5">{focusedShot.shotType}</p>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Legend */}
      <div className="mt-5 flex items-center justify-center gap-5 flex-wrap">
        <div className="flex items-center gap-2.5 rounded-lg bg-[#0b1220] border border-[#1a1f2e] px-3 py-1.5">
          <div className="h-3.5 w-3.5 rounded-full bg-yellow-400 shadow-lg shadow-yellow-400/30"></div>
          <span className="text-[10px] font-semibold text-white/90">Γκολ</span>
        </div>
        <div className="flex items-center gap-2.5 rounded-lg bg-[#0b1220] border border-[#1a1f2e] px-3 py-1.5">
          <div className="h-3.5 w-3.5 rounded-full bg-blue-500 shadow-lg shadow-blue-500/30"></div>
          <span className="text-[10px] font-semibold text-white/90">Στο Τέρμα</span>
        </div>
        <div className="flex items-center gap-2.5 rounded-lg bg-[#0b1220] border border-[#1a1f2e] px-3 py-1.5">
          <div className="h-3.5 w-3.5 rounded-full bg-red-500 shadow-lg shadow-red-500/30"></div>
          <span className="text-[10px] font-semibold text-white/90">Άστοχο</span>
        </div>
        <div className="flex items-center gap-2.5 rounded-lg bg-[#0b1220] border border-[#1a1f2e] px-3 py-1.5">
          <div className="h-3.5 w-3.5 rounded-full bg-gray-500 shadow-lg shadow-gray-500/30"></div>
          <span className="text-[10px] font-semibold text-white/90">Κομμένο</span>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useMemo } from "react";
import type { ShotEvent } from "./ShotAnalytics";

interface ShotTimelineProps {
  shots: ShotEvent[];
}

export function ShotTimeline({ shots }: ShotTimelineProps) {
  // Group shots by minute
  const timeline = useMemo(() => {
    const byMinute: Record<number, ShotEvent[]> = {};

    shots.forEach((shot) => {
      const minute = Math.floor(shot.timeSec / 60);
      if (!byMinute[minute]) {
        byMinute[minute] = [];
      }
      byMinute[minute].push(shot);
    });

    // Convert to array and sort
    return Object.entries(byMinute)
      .map(([minute, shotList]) => ({
        minute: parseInt(minute),
        shots: shotList,
        count: shotList.length,
        goals: shotList.filter((s) => s.goal || s.outcome === "Goal").length,
      }))
      .sort((a, b) => a.minute - b.minute);
  }, [shots]);

  const maxCount = Math.max(...timeline.map((t) => t.count), 1);
  const maxMinute = Math.max(...timeline.map((t) => t.minute), 90);

  if (timeline.length === 0) {
    return (
      <div className="flex h-64 items-center justify-center text-[11px] text-white/50">
        Δεν υπάρχουν δεδομένα για timeline
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {/* Bar Chart */}
      <div className="relative h-64">
        <svg width="100%" height="100%" viewBox={`0 0 ${Math.max(900, maxMinute * 10)} 200`} className="overflow-visible">
          {/* Grid lines */}
          <g stroke="rgba(255,255,255,0.05)" strokeWidth="1">
            {Array.from({ length: Math.ceil(maxMinute / 5) + 1 }).map((_, i) => (
              <line
                key={`grid-${i}`}
                x1={i * 50}
                y1="0"
                x2={i * 50}
                y2="200"
              />
            ))}
          </g>

          {/* Bars */}
          {timeline.map((item) => {
            const barHeight = (item.count / maxCount) * 180;
            const x = item.minute * 10;
            const goalHeight = item.goals > 0 ? (item.goals / maxCount) * 180 : 0;

            return (
              <g key={`minute-${item.minute}`}>
                {/* Total shots bar */}
                <rect
                  x={x}
                  y={200 - barHeight}
                  width="8"
                  height={barHeight}
                  fill="rgba(59, 130, 246, 0.6)"
                  rx="2"
                />
                {/* Goals bar (overlay) */}
                {goalHeight > 0 && (
                  <rect
                    x={x}
                    y={200 - goalHeight}
                    width="8"
                    height={goalHeight}
                    fill="#fbbf24"
                    rx="2"
                  />
                )}
                {/* Minute label */}
                {item.minute % 5 === 0 && (
                  <text
                    x={x + 4}
                    y="195"
                    fontSize="10"
                    fill="rgba(255,255,255,0.5)"
                    textAnchor="middle"
                  >
                    {item.minute}'
                  </text>
                )}
                {/* Count label on hover area */}
                <rect
                  x={x - 2}
                  y="0"
                  width="12"
                  height="200"
                  fill="transparent"
                  className="cursor-pointer"
                >
                  <title>
                    {item.minute}': {item.count} σουτ ({item.goals} γκολ)
                  </title>
                </rect>
              </g>
            );
          })}
        </svg>
      </div>

      {/* Legend */}
      <div className="flex items-center justify-center gap-5 mt-4">
        <div className="flex items-center gap-2.5 rounded-lg bg-[#0b1220] border border-[#1a1f2e] px-3 py-1.5">
          <div className="h-3.5 w-8 bg-blue-500/60 rounded shadow-lg"></div>
          <span className="text-[10px] font-semibold text-white/90">Συνολικά Σουτ</span>
        </div>
        <div className="flex items-center gap-2.5 rounded-lg bg-[#0b1220] border border-[#1a1f2e] px-3 py-1.5">
          <div className="h-3.5 w-8 bg-yellow-400 rounded shadow-lg shadow-yellow-400/30"></div>
          <span className="text-[10px] font-semibold text-white/90">Γκολ</span>
        </div>
      </div>

      {/* Summary stats */}
      <div className="grid grid-cols-3 gap-4 mt-6">
        <div className="rounded-lg border border-[#1a1f2e] bg-[#0b1220] p-4 text-center">
          <p className="text-[10px] font-semibold text-white/70 mb-1.5">Συνολικά Σουτ</p>
          <p className="text-2xl font-bold text-white">{shots.length}</p>
        </div>
        <div className="rounded-lg border border-[#1a1f2e] bg-[#0b1220] p-4 text-center">
          <p className="text-[10px] font-semibold text-white/70 mb-1.5">Σουτ/Λεπτό</p>
          <p className="text-2xl font-bold text-emerald-400">
            {(shots.length / Math.max(maxMinute, 1)).toFixed(2)}
          </p>
        </div>
        <div className="rounded-lg border border-[#1a1f2e] bg-[#0b1220] p-4 text-center">
          <p className="text-[10px] font-semibold text-white/70 mb-1.5">Γκολ</p>
          <p className="text-2xl font-bold text-yellow-400">
            {shots.filter((s) => s.goal || s.outcome === "Goal").length}
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useMemo, useState, useCallback } from "react";

type TeamId = string;
type PlayerId = string;
type Half = "1H" | "2H" | "all";
type Direction = "L2R" | "R2L" | "all";

interface MovementVector {
  teamId: TeamId;
  playerId: PlayerId;
  startX: number; // 0..1
  startY: number; // 0..1
  endX: number;
  endY: number;
  half?: Half;
  speedMps?: number;
  distanceM?: number;
  eventType?: string;
  subType?: string;
}

interface VectorFieldProps {
  events: Array<{
    id: number;
    type: string;
    team: string;
    playerId: number | null;
    player: { id: number; name: string; number?: number | null } | null;
    x: number | null;
    y: number | null;
    minute: number | null;
    metadata: string | null;
  }>;
  players: Array<{
    id: number;
    name: string;
    number?: number | null;
    position?: string;
  }>;
  homeTeamId: number | null;
  awayTeamId: number | null;
  homeTeamName: string;
  awayTeamName: string;
}

const HOME_COLOR = "#3a8bff";
const AWAY_COLOR = "#f25c54";

function buildVectors(
  events: VectorFieldProps["events"],
  players: VectorFieldProps["players"],
  team: "home" | "away",
  filters: {
    attribute?: "passing" | "carrying" | "all";
    subAttribute?: string;
    eventType?: string;
    playerIds?: PlayerId[];
    half?: Half;
    minDistance?: number;
    normalizeDirection?: boolean;
  }
): MovementVector[] {
  // Filter events by team and type
  let filteredEvents = events.filter(
    (e) => e.team === team && e.x !== null && e.y !== null && e.minute !== null
  );

  // Filter by half
  if (filters.half === "1H") {
    filteredEvents = filteredEvents.filter((e) => e.minute !== null && e.minute < 45);
  } else if (filters.half === "2H") {
    filteredEvents = filteredEvents.filter((e) => e.minute !== null && e.minute >= 45);
  }

  // Filter by attribute/event type
  if (filters.attribute === "passing") {
    filteredEvents = filteredEvents.filter((e) => e.type === "pass");
  } else if (filters.attribute === "carrying") {
    filteredEvents = filteredEvents.filter((e) => e.type === "carry" || e.type === "dribble");
  }

  if (filters.eventType && filters.eventType !== "all") {
    filteredEvents = filteredEvents.filter((e) => e.type === filters.eventType);
  }

  // Filter by players
  if (filters.playerIds && filters.playerIds.length > 0) {
    const allowedIds = new Set(filters.playerIds);
    const allSelected = allowedIds.has("__all__");
    if (!allSelected) {
      // Keep unknown-player events too (AI often cannot assign a playerId).
      filteredEvents = filteredEvents.filter((e) => !e.playerId || allowedIds.has(e.playerId.toString()));
    }
  }

  // Build vectors from consecutive events or from metadata
  const vectors: MovementVector[] = [];
  const eventsByPlayer = new Map<PlayerId, typeof filteredEvents>();

  filteredEvents.forEach((e) => {
    // Keep unknown player events too; AI output often has no playerId.
    const playerId = e.playerId ? e.playerId.toString() : `unknown-${team}`;
    if (!eventsByPlayer.has(playerId)) {
      eventsByPlayer.set(playerId, []);
    }
    eventsByPlayer.get(playerId)!.push(e);
  });

  eventsByPlayer.forEach((playerEvents, playerId) => {
    // Sort by minute
    const sorted = [...playerEvents].sort((a, b) => (a.minute || 0) - (b.minute || 0));

    // 1) Prefer explicit pass/carry vectors from metadata end coordinates.
    // This is the most accurate source and should not depend on consecutive events.
    sorted.forEach((event) => {
      if (event.x === null || event.y === null) return;
      if (event.type !== "pass" && event.type !== "carry" && event.type !== "dribble") return;

      let endX: number | null = null;
      let endY: number | null = null;
      let subType: string | undefined;

      if (event.metadata) {
        try {
          const meta = JSON.parse(event.metadata);
          // Support both legacy and new key names
          endX = meta.endX ?? meta.toX ?? null;
          endY = meta.endY ?? meta.toY ?? null;
          subType = meta.subType || meta.progressive || undefined;
        } catch {
          // invalid metadata
        }
      }

      if (endX === null || endY === null || Number.isNaN(Number(endX)) || Number.isNaN(Number(endY))) return;
      if (Number(endX) < 0 || Number(endX) > 100 || Number(endY) < 0 || Number(endY) > 100) return;

      const startX = Number(event.x) / 100;
      const startY = Number(event.y) / 100;
      const finalEndXRaw = Number(endX) / 100;
      const endYNorm = Number(endY) / 100;

      const dx = (finalEndXRaw - startX) * 105;
      const dy = (endYNorm - startY) * 68;
      const distanceM = Math.sqrt(dx * dx + dy * dy);
      if (filters.minDistance && distanceM < filters.minDistance) return;

      const speedMps = distanceM / 2;
      let finalStartX = startX;
      let finalEndX = finalEndXRaw;
      if (filters.normalizeDirection && team === "away") {
        finalStartX = 1 - startX;
        finalEndX = 1 - finalEndXRaw;
      }

      if (filters.subAttribute && filters.subAttribute !== "all") {
        if (filters.subAttribute === "progressive" && subType !== "progressive") return;
        if (filters.subAttribute === "backward" && subType !== "backward") return;
      }

      vectors.push({
        teamId: team,
        playerId: event.playerId ? event.playerId.toString() : `unknown-${event.id}`,
        startX: finalStartX,
        startY,
        endX: finalEndX,
        endY: endYNorm,
        half: (event.minute || 0) < 45 ? "1H" : "2H",
        speedMps,
        distanceM,
        eventType: event.type,
        subType,
      });
    });

    // 2) Fallback to consecutive-event vectors when metadata endpoints are unavailable.
    for (let i = 0; i < sorted.length - 1; i++) {
      const current = sorted[i];
      const next = sorted[i + 1];

      if (current.x === null || current.y === null || next.x === null || next.y === null) continue;

      // Only create vector if events are close in time (same minute or adjacent)
      const timeDiff = (next.minute || 0) - (current.minute || 0);
      if (timeDiff > 5) continue; // Allow small gaps to avoid empty plots on sparse data

      const startX = current.x / 100; // Normalize to 0-1
      const startY = current.y / 100;
      const endX = next.x / 100;
      const endY = next.y / 100;

      // Calculate distance (assuming pitch is ~105m x 68m)
      const dx = (endX - startX) * 105;
      const dy = (endY - startY) * 68;
      const distanceM = Math.sqrt(dx * dx + dy * dy);

      // Filter by min distance
      if (filters.minDistance && distanceM < filters.minDistance) continue;

      // Calculate speed (assume ~2 seconds between events)
      const speedMps = distanceM / 2;

      // Normalize direction if needed (mirror for away team if attacking left-to-right)
      let finalStartX = startX;
      let finalEndX = endX;
      if (filters.normalizeDirection && team === "away") {
        // Mirror horizontally for away team
        finalStartX = 1 - startX;
        finalEndX = 1 - endX;
      }

      // Get event metadata
      let eventType = current.type;
      let subType: string | undefined;
      if (current.metadata) {
        try {
          const meta = JSON.parse(current.metadata);
          subType = meta.subType || meta.progressive || undefined;
        } catch {
          // Invalid JSON
        }
      }

      // Filter by sub-attribute
      if (filters.subAttribute && filters.subAttribute !== "all") {
        if (filters.subAttribute === "progressive" && subType !== "progressive") continue;
        if (filters.subAttribute === "backward" && subType !== "backward") continue;
      }

      vectors.push({
        teamId: team,
        playerId,
        startX: finalStartX,
        startY,
        endX: finalEndX,
        endY,
        half: (current.minute || 0) < 45 ? "1H" : "2H",
        speedMps,
        distanceM,
        eventType,
        subType,
      });
    }
  });

  return vectors;
}

interface VectorPitchProps {
  vectors: MovementVector[];
  teamColor: string;
  teamName: string;
  width?: number;
  height?: number;
}

function VectorPitch({ vectors, teamColor, teamName, width = 900, height = 520 }: VectorPitchProps) {
  const [hoveredVector, setHoveredVector] = useState<MovementVector | null>(null);
  const [tooltipPos, setTooltipPos] = useState<{ x: number; y: number } | null>(null);

  const maxDistance = useMemo(() => Math.max(...vectors.map((v) => v.distanceM || 0), 1), [vectors]);
  const maxSpeed = useMemo(() => Math.max(...vectors.map((v) => v.speedMps || 0), 1), [vectors]);

  const handleMouseMove = useCallback((e: React.MouseEvent<SVGSVGElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setTooltipPos({
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
    });
  }, []);

  // Calculate stats
  const stats = useMemo(() => {
    const totalVectors = vectors.length;
    const meanMagnitude = vectors.length > 0
      ? vectors.reduce((sum, v) => sum + (v.distanceM || 0), 0) / vectors.length
      : 0;

    // Calculate net direction
    const sumDx = vectors.reduce((sum, v) => sum + (v.endX - v.startX), 0);
    const sumDy = vectors.reduce((sum, v) => sum + (v.endY - v.startY), 0);
    const netDirection = Math.atan2(sumDy, sumDx) * (180 / Math.PI);

    return { totalVectors, meanMagnitude, netDirection };
  }, [vectors]);

  if (vectors.length === 0) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-center">
          <div className="text-4xl mb-3 opacity-50">⚡</div>
          <p className="text-white/50 text-sm font-medium">Δεν υπάρχουν διανύσματα για αυτό το φίλτρο</p>
        </div>
      </div>
    );
  }

  return (
    <div className="relative w-full rounded-xl overflow-hidden" style={{ aspectRatio: `${width}/${height}`, background: "linear-gradient(135deg, #0f1923 0%, #0a1520 100%)" }}>
      <svg
        viewBox={`0 0 ${width} ${height}`}
        width="100%"
        height="100%"
        className="absolute inset-0"
        onMouseMove={handleMouseMove}
        onMouseLeave={() => {
          setHoveredVector(null);
          setTooltipPos(null);
        }}
      >
        <defs>
          <marker
            id={`arrowhead-${teamColor}`}
            markerWidth="10"
            markerHeight="10"
            refX="9"
            refY="3"
            orient="auto"
          >
            <polygon
              points="0 0, 10 3, 0 6"
              fill={teamColor}
            />
          </marker>
          <linearGradient id="pitchGradient" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="#0f1923" stopOpacity="1" />
            <stop offset="100%" stopColor="#0a1520" stopOpacity="1" />
          </linearGradient>
        </defs>

        {/* Pitch background */}
        <rect x="0" y="0" width={width} height={height} fill="url(#pitchGradient)" />

        {/* Pitch lines */}
        <g stroke="rgba(255,255,255,0.1)" strokeWidth="2.5" fill="none" opacity="0.6">
          <rect x="6" y="6" width={width - 12} height={height - 12} rx="12" />
          <line x1={width / 2} y1="0" x2={width / 2} y2={height} strokeWidth="3" />
          <rect x="6" y={height * 0.3} width={width * 0.1} height={height * 0.4} rx="4" />
          <rect x={width - 6 - width * 0.1} y={height * 0.3} width={width * 0.1} height={height * 0.4} rx="4" />
          <circle cx={width / 2} cy={height / 2} r={height * 0.12} />
        </g>

        {/* Vectors */}
        {vectors.map((vector, idx) => {
          const x1 = vector.startX * width;
          const y1 = vector.startY * height;
          const x2 = vector.endX * width;
          const y2 = vector.endY * height;

          const distance = vector.distanceM || 0;
          const speed = vector.speedMps || 0;
          const distanceNorm = distance / maxDistance;
          const speedNorm = speed / maxSpeed;

          // Draw true vector length (no hard clamp) to match tactical-style vector maps.
          const finalX2 = x2;
          const finalY2 = y2;

          const opacity = 0.35 + 0.5 * speedNorm;
          const isHovered = hoveredVector === vector;
          const strokeWidth = isHovered ? 3 : 1.5 + distanceNorm;

          // Color based on event type
          let strokeColor = teamColor;
          if (vector.eventType === "pass") {
            strokeColor = teamColor;
          } else if (vector.eventType === "carry" || vector.eventType === "dribble") {
            strokeColor = "#10b981"; // Green for carries
          } else if (vector.subType === "progressive") {
            strokeColor = "#f59e0b"; // Amber for progressive
          }

          return (
            <line
              key={idx}
              x1={x1}
              y1={y1}
              x2={finalX2}
              y2={finalY2}
              stroke={strokeColor}
              strokeWidth={strokeWidth}
              opacity={isHovered ? 1 : opacity}
              markerEnd={`url(#arrowhead-${teamColor})`}
              style={{
                transition: "opacity 0.2s ease, stroke-width 0.2s ease",
                filter: isHovered ? "url(#glow)" : "none",
              }}
              onMouseEnter={() => setHoveredVector(vector)}
              onMouseLeave={() => setHoveredVector(null)}
              cursor="pointer"
            />
          );
        })}

        {/* Glow filter */}
        <defs>
          <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="3" result="coloredBlur" />
            <feMerge>
              <feMergeNode in="coloredBlur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>
      </svg>

      {/* Attack Direction Arrow */}
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex items-center gap-2 text-white/60 text-xs">
        <svg width="60" height="20" viewBox="0 0 60 20">
          <path d="M 0 10 L 50 10" stroke="currentColor" strokeWidth="2" fill="none" />
          <path d="M 45 5 L 50 10 L 45 15" stroke="currentColor" strokeWidth="2" fill="none" />
        </svg>
        <span className="font-medium">Attack Direction</span>
      </div>

      {/* Tooltip */}
      {hoveredVector && tooltipPos && (
        <div
          className="absolute pointer-events-none z-50 rounded-xl bg-gradient-to-br from-[#0f1923] to-[#0a1520] border border-white/20 p-4 shadow-2xl backdrop-blur-sm transition-all duration-200"
          style={{
            left: `${tooltipPos.x + 15}px`,
            top: `${tooltipPos.y + 15}px`,
            transform: tooltipPos.x > width - 250 ? "translateX(-100%)" : "none",
            boxShadow: "0 8px 32px rgba(0,0,0,0.6), 0 0 0 1px rgba(255,255,255,0.1)",
          }}
        >
          <div className="text-xs text-white space-y-2">
            <div className="flex items-center gap-2 mb-2 pb-2 border-b border-white/10">
              <div className="w-2 h-2 rounded-full" style={{ backgroundColor: teamColor }} />
              <div className="font-bold text-sm">Movement Vector</div>
            </div>
            <div className="space-y-1 text-white/80">
              <div className="flex justify-between">
                <span className="text-white/60">Distance:</span>
                <span className="font-semibold">{(hoveredVector.distanceM || 0).toFixed(1)}m</span>
              </div>
              {hoveredVector.speedMps && (
                <div className="flex justify-between">
                  <span className="text-white/60">Speed:</span>
                  <span className="font-semibold">{(hoveredVector.speedMps).toFixed(1)} m/s</span>
                </div>
              )}
              {hoveredVector.eventType && (
                <div className="flex justify-between">
                  <span className="text-white/60">Type:</span>
                  <span className="font-semibold">{hoveredVector.eventType}</span>
                </div>
              )}
              {hoveredVector.subType && (
                <div className="flex justify-between">
                  <span className="text-white/60">Sub-type:</span>
                  <span className="font-semibold">{hoveredVector.subType}</span>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Stats overlay */}
      <div className="absolute bottom-12 left-4 right-4 flex justify-between items-end text-xs text-white/70">
        <div className="space-y-1">
          <div>Total Vectors: <span className="font-semibold text-white">{stats.totalVectors}</span></div>
          <div>Mean Magnitude: <span className="font-semibold text-white">{stats.meanMagnitude.toFixed(2)}m</span></div>
        </div>
        <div className="flex items-center gap-2">
          <span>Direction:</span>
          <svg width="40" height="20" viewBox="0 0 40 20" style={{ transform: `rotate(${stats.netDirection}deg)` }}>
            <path d="M 0 10 L 30 10" stroke="currentColor" strokeWidth="2" fill="none" />
            <path d="M 25 5 L 30 10 L 25 15" stroke="currentColor" strokeWidth="2" fill="none" />
          </svg>
        </div>
      </div>
    </div>
  );
}

export function VectorField({
  events,
  players,
  homeTeamId,
  awayTeamId,
  homeTeamName,
  awayTeamName,
}: VectorFieldProps) {
  const [homeAttribute, setHomeAttribute] = useState<"passing" | "carrying" | "all">("all");
  const [awayAttribute, setAwayAttribute] = useState<"passing" | "carrying" | "all">("all");
  const [homeSubAttribute, setHomeSubAttribute] = useState("all");
  const [awaySubAttribute, setAwaySubAttribute] = useState("all");
  const [homeEventType, setHomeEventType] = useState("all");
  const [awayEventType, setAwayEventType] = useState("all");
  const [homePlayerIds, setHomePlayerIds] = useState<PlayerId[]>(["__all__"]);
  const [awayPlayerIds, setAwayPlayerIds] = useState<PlayerId[]>(["__all__"]);
  const [half, setHalf] = useState<Half>("all");
  const [minDistance, setMinDistance] = useState(0);
  const [normalizeDirection, setNormalizeDirection] = useState(false);
  const [showSpotlight, setShowSpotlight] = useState(false);

  // Build vectors for both teams
  const homeVectors = useMemo(
    () =>
      buildVectors(events, players, "home", {
        attribute: homeAttribute,
        subAttribute: homeSubAttribute,
        eventType: homeEventType === "all" ? undefined : homeEventType,
        playerIds: homePlayerIds.length > 0 ? homePlayerIds : undefined,
        half,
        minDistance,
        normalizeDirection,
      }),
    [events, players, homeAttribute, homeSubAttribute, homeEventType, homePlayerIds, half, minDistance, normalizeDirection]
  );

  const awayVectors = useMemo(
    () =>
      buildVectors(events, players, "away", {
        attribute: awayAttribute,
        subAttribute: awaySubAttribute,
        eventType: awayEventType === "all" ? undefined : awayEventType,
        playerIds: awayPlayerIds.length > 0 ? awayPlayerIds : undefined,
        half,
        minDistance,
        normalizeDirection,
      }),
    [events, players, awayAttribute, awaySubAttribute, awayEventType, awayPlayerIds, half, minDistance, normalizeDirection]
  );

  // Filter players by team based on events
  const homePlayers = useMemo(() => {
    const homePlayerIds = new Set<number>();
    events.forEach((e) => {
      if (e.team === "home" && e.playerId) {
        homePlayerIds.add(e.playerId);
      }
    });
    return players.filter((p) => homePlayerIds.has(p.id));
  }, [events, players]);

  const awayPlayers = useMemo(() => {
    const awayPlayerIds = new Set<number>();
    events.forEach((e) => {
      if (e.team === "away" && e.playerId) {
        awayPlayerIds.add(e.playerId);
      }
    });
    return players.filter((p) => awayPlayerIds.has(p.id));
  }, [events, players]);

  const homePlayerCount = useMemo(() => {
    const unique = new Set(homeVectors.map((v) => v.playerId));
    return unique.size;
  }, [homeVectors]);

  const awayPlayerCount = useMemo(() => {
    const unique = new Set(awayVectors.map((v) => v.playerId));
    return unique.size;
  }, [awayVectors]);

