                    teamId={match.awayTeamId || null}
                    teamName={getTeamName(match.awayTeam, match.awayTeamName)}
                    players={match.awayTeamId ? players.filter((p) => p.teamId === match.awayTeamId) : players.filter((p) => !p.teamId || p.teamId === null)}
                    onSave={() => {
