                </div>
                <div style={{ minWidth: 200, minHeight: 200 }}>
                  <Suspense fallback={<div className="h-96 animate-pulse bg-slate-900 rounded" style={{ minWidth: 200, minHeight: 200 }} />}>
                    <DistributionMap events={events} team="away" teamName={getTeamName(match.awayTeam, match.awayTeamName)} />
                  </Suspense>
                </div>
              </div>
            </section>
          )}
          {activeTab === "activity" && (
            <section className="space-y-4 rounded-xl border border-slate-800 bg-slate-950 p-4 text-[11px] text-slate-300">
              <div className="flex items-center justify-between">
                <div>
                  <p className="font-medium">Πεδίο Δραστηριότητας</p>
                  <p className="text-[10px] text-slate-500">Οπτικοποίηση χάρτη θερμότητας ζωνών δραστηριότητας παικτών</p>
                </div>
                <span className="rounded-full bg-slate-900 px-2 py-0.5 text-[10px] text-slate-400">Χάρτης θερμότητας ζώνης</span>
              </div>
              <div className="grid gap-4 md:gap-6 lg:grid-cols-2">
                <div style={{ minWidth: 200, minHeight: 200 }}>
                  <Suspense fallback={<div className="h-96 animate-pulse bg-slate-900 rounded" style={{ minWidth: 200, minHeight: 200 }} />}>
                    <ActivityField events={events} team="home" teamName={getTeamName(match.homeTeam, match.homeTeamName)} />
                  </Suspense>
                </div>
                <div style={{ minWidth: 200, minHeight: 200 }}>
                  <Suspense fallback={<div className="h-96 animate-pulse bg-slate-900 rounded" style={{ minWidth: 200, minHeight: 200 }} />}>
                    <ActivityField events={events} team="away" teamName={getTeamName(match.awayTeam, match.awayTeamName)} />
                  </Suspense>
                </div>
              </div>
            </section>
          )}
          {activeTab === "vector" && (
            <section className="space-y-4 rounded-xl border border-slate-800 bg-slate-950 p-4 text-[11px] text-slate-300">
              <Suspense fallback={<div className="h-96 animate-pulse bg-slate-900 rounded" />}>
                <VectorField
                  events={events.map(e => ({ ...e, playerId: e.player?.id || null }))}
                  players={players}
                  homeTeamId={match.homeTeamId}
                  awayTeamId={match.awayTeamId}
                  homeTeamName={getTeamName(match.homeTeam, match.homeTeamName)}
                  awayTeamName={getTeamName(match.awayTeam, match.awayTeamName)}
                />
              </Suspense>
            </section>
          )}
          {activeTab === "dynamics" && (
            <section className="space-y-4 rounded-xl border border-slate-800 bg-slate-950 p-4 text-[11px] text-slate-300">
              <Suspense fallback={<div className="h-96 animate-pulse bg-slate-900 rounded" />}>
                <MatchDynamics
                  events={events}
                  homeTeamId={match.homeTeamId}
                  awayTeamId={match.awayTeamId}
                  homeTeamName={getTeamName(match.homeTeam, match.homeTeamName)}
                  awayTeamName={getTeamName(match.awayTeam, match.awayTeamName)}
                />
              </Suspense>
            </section>
          )}

          {activeTab === "shot-analytics" && (
            <section className="space-y-4 rounded-xl border border-slate-800 bg-slate-950 p-4 text-[11px] text-slate-300">
              <Suspense fallback={<div className="h-96 animate-pulse bg-slate-900 rounded" />}>
                <ShotAnalytics
                  shots={shotAnalyticsData}
                  homeTeamName={getTeamName(match.homeTeam, match.homeTeamName)}
                  awayTeamName={getTeamName(match.awayTeam, match.awayTeamName)}
                  homeTeamId={String(match.homeTeamId || "")}
                  awayTeamId={String(match.awayTeamId || "")}
                />
              </Suspense>
            </section>
          )}

          {activeTab === "players-analysis" && (
            <section className="space-y-4 rounded-xl border border-slate-800 bg-slate-950 p-4 text-[11px] text-slate-300">
              <div className="flex items-center justify-between">
                <div>
                  <p className="font-medium">Players Analysis</p>
                  <p className="text-[10px] text-slate-500">Στατιστικά παικτών που προκύπτουν αποκλειστικά από το συγκεκριμένο match</p>
                </div>
              </div>
              <Suspense fallback={<div className="h-96 animate-pulse bg-slate-900 rounded" />}>
                <PlayersAnalysis
                  events={events}
                  players={players}
                  homeTeamId={match.homeTeamId}
                  awayTeamId={match.awayTeamId}
                  homeTeamName={getTeamName(match.homeTeam, match.homeTeamName)}
                  awayTeamName={getTeamName(match.awayTeam, match.awayTeamName)}
                  starterPlayerIds={starterPlayerIds}
                  canJumpToVideo={Boolean(match.videoPath)}
                  onJumpToVideoMinute={(minute) => {
                    setSpotlightJumpMinute(minute);
                    setActiveTab("spotlight");
                  }}
                />
              </Suspense>
            </section>
          )}

          {activeTab === "spotlight" && (
            <section className="space-y-4 rounded-xl border border-slate-800 bg-slate-950 p-4 text-[11px] text-slate-300">
              <div className="flex items-center justify-between">
                <div>
                  <p className="font-medium">Spotlight</p>
                  <p className="text-[10px] text-slate-500">Κρίσιμες στιγμές και highlights από τον αγώνα</p>
                </div>
                <div className="flex gap-2 text-[10px]">
                  <button className="rounded-full bg-emerald-500 px-3 py-1 font-medium text-slate-950 hover:bg-emerald-400 transition">
                    Δημιουργία AI highlight
                  </button>
                  <button className="rounded-full border border-slate-700 bg-slate-900 px-3 py-1 font-medium text-slate-200 hover:bg-slate-800 transition">
                    Λήψη αναφοράς αγώνα
                  </button>
                </div>
              </div>
              <Suspense fallback={<div className="h-96 animate-pulse bg-slate-900 rounded" />}>
                <Spotlight 
                  events={events as any} 
                  matchId={match.id}
                  videoUrl={match.videoPath ? (() => {
                    // Handle different path formats
                    if (match.videoPath.startsWith('http')) {
                      return match.videoPath;
                    }
                    // Convert absolute or relative path to relative format (videos/match-X/file.mp4)
                    let relPath = match.videoPath.replace(/\\/g, "/");
                    // If absolute path, extract relative part
                    if (relPath.match(/^[A-Za-z]:/) || relPath.startsWith('/')) {
                      const matchPath = relPath.match(/uploads[\/\\]videos[\/\\]match-\d+[\/\\](.+)$/i);
                      if (matchPath) {
                        relPath = `videos/match-${match.id}/${matchPath[1]}`;
                      } else {
                        const uploadsIndex = relPath.indexOf('uploads');
                        if (uploadsIndex !== -1) {
                          relPath = relPath.substring(uploadsIndex + 8).replace(/\\/g, '/');
                        } else {
                          // Custom drive / absolute path outside project: API whitelists against match.videoPath
                          return `/api/matches/${match.id}/video?path=${encodeURIComponent(match.videoPath!.replace(/\\/g, '/'))}`;
                        }
                      }
                    } else {
                      // Already relative - ensure it starts with videos/ not uploads/
                      relPath = relPath.replace(/^uploads[\/\\]?/i, '').replace(/\\/g, '/');
                    }
                    return `/api/matches/${match.id}/video?path=${encodeURIComponent(relPath)}`;
                  })() : null}
                  homeTeamId={match.homeTeamId}
                  awayTeamId={match.awayTeamId}
                  initialMinute={spotlightJumpMinute ?? undefined}
                />
              </Suspense>
            </section>
          )}
        </div>
      </div>
    </div>

    {/* AI Highlights Modal */}
    {showHighlightsModal && highlights && (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
        <div className="w-full max-w-2xl rounded-2xl border border-slate-800 bg-slate-950/95 p-6 text-xs text-slate-200 shadow-2xl max-h-[80vh] overflow-y-auto">
          <div className="mb-4 flex items-center justify-between">
            <div className="space-y-0.5">
              <p className="text-[11px] font-medium uppercase tracking-wide text-slate-400">AI Highlights</p>
              <h2 className="text-lg font-semibold tracking-tight text-slate-50">
                {getTeamName(match?.homeTeam || null, match?.homeTeamName)} vs {getTeamName(match?.awayTeam || null, match?.awayTeamName)}
              </h2>
            </div>
            <button
              onClick={() => setShowHighlightsModal(false)}
              className="h-8 w-8 rounded-full bg-slate-900 text-[11px] text-slate-400 hover:bg-slate-800 transition"
            >
              ×
            </button>
          </div>
          <div className="space-y-2">
            {highlights.length > 0 ? (
              highlights.map((highlight, idx) => (
                <div
                  key={idx}
                  className="flex items-start gap-3 rounded-lg border border-slate-800 bg-slate-900/50 p-3"
                >
                  <div className="flex h-8 w-8 items-center justify-center rounded-full bg-blue-500/20 text-xs font-semibold text-blue-300">
                    {highlight.minute}'
                  </div>
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <span className={`text-xs font-medium ${
                        highlight.type === "goal" ? "text-emerald-400" :
                        highlight.type === "chance" ? "text-yellow-400" :
                        "text-blue-400"
                      }`}>
                        {highlight.type === "goal" ? "⚽ GOAL" :
                         highlight.type === "chance" ? "🎯 BIG CHANCE" :
                         "🎯 ASSIST"}
                      </span>
                      {highlight.xg && (
                        <span className="text-[10px] text-slate-500">xG: {highlight.xg.toFixed(2)}</span>
                      )}
                    </div>
                    <p className="mt-1 text-[11px] text-slate-200">{highlight.description}</p>
                    {highlight.player && (
                      <p className="mt-1 text-[10px] text-slate-400">Player: {highlight.player} • Team: {highlight.team === "home" ? getTeamName(match?.homeTeam || null, match?.homeTeamName) : getTeamName(match?.awayTeam || null, match?.awayTeamName)}</p>
                    )}
                  </div>
                </div>
              ))
            ) : (
              <p className="text-center text-[11px] text-slate-500 py-4">No highlights found for this match.</p>
            )}
          </div>
          <div className="mt-4 flex justify-end">
            <button
              onClick={() => setShowHighlightsModal(false)}
              className="h-8 rounded-md bg-emerald-500 px-4 text-[11px] font-semibold text-slate-950 shadow-sm transition hover:bg-emerald-400"
            >
              Close
            </button>
          </div>
        </div>
      </div>
    )}
    </>
  );
}

"use client";

import Link from "next/link";
import { useState, FormEvent, useEffect, useRef } from "react";
import { useRouter } from "next/navigation";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { matchSchema, type MatchFormData } from "@/lib/validations";
import toast, { Toaster } from "react-hot-toast";
import { ExportModal } from "@/app/components/ExportModal";
import { useTranslation } from "@/lib/i18n";

type Match = {
  id: number;
  slug: string;
  competition: string;
  venue: string | null;
  date: string;
  scoreHome: number | null;
  scoreAway: number | null;
  xgHome: number | null;
  xgAway: number | null;
  homeTeam: { id: number; name: string };
  awayTeam: { id: number; name: string };
};

type Team = {
  id: number;
  name: string;
};

type TabKey = "matches" | "tournaments" | "players";

export default function MatchesPage() {
  const { t } = useTranslation();
  const router = useRouter();
  const [activeTab, setActiveTab] = useState<TabKey>("matches");
  const [showCreateMatch, setShowCreateMatch] = useState(false);
  const [matches, setMatches] = useState<Match[]>([]);
  const [teams, setTeams] = useState<Team[]>([]);
  const [loading, setLoading] = useState(true);
  const [openActionsMenu, setOpenActionsMenu] = useState<number | null>(null);
  const [menuPosition, setMenuPosition] = useState<{ top: number; right: number } | null>(null);
  const buttonRefs = useRef<{ [key: number]: HTMLButtonElement | null }>({});
  const [showExportModal, setShowExportModal] = useState(false);

  // Check authentication first
  useEffect(() => {
    async function checkAuth() {
      try {
        const userRes = await fetch("/api/account/me");
        if (!userRes.ok) {
          router.push("/auth/login");
          return;
        }
        const userData = await userRes.json();
        if (!userData.ok) {
          router.push("/auth/login");
          return;
        }
      } catch {
        router.push("/auth/login");
      }
    }
    checkAuth();
  }, [router]);

  // Close menu on scroll or resize
  useEffect(() => {
    if (openActionsMenu !== null) {
      const handleClose = () => {
        setOpenActionsMenu(null);
        setMenuPosition(null);
      };
      window.addEventListener('scroll', handleClose, true);
      window.addEventListener('resize', handleClose);
      return () => {
        window.removeEventListener('scroll', handleClose, true);
        window.removeEventListener('resize', handleClose);
      };
    }
  }, [openActionsMenu]);

  // Load persisted filters from localStorage
  const loadPersistedFilters = () => {
    if (typeof window === "undefined") {
      return {
        season: "All",
        competition: "All",
        teamId: "All",
        dateFrom: "",
        dateTo: "",
        search: "",
      };
    }

    try {
      const stored = localStorage.getItem("matches_filters");
      if (stored) {
        const parsed = JSON.parse(stored);
        return {
          season: parsed.season || "All",
          competition: parsed.competition || "All",
          teamId: parsed.teamId || "All",
          dateFrom: parsed.dateFrom || "",
          dateTo: parsed.dateTo || "",
          search: parsed.search || "",
        };
      }
    } catch (e) {
      console.warn("[MatchesPage] Failed to load persisted filters:", e);
    }

    return {
      season: "All",
      competition: "All",
      teamId: "All",
      dateFrom: "",
      dateTo: "",
      search: "",
    };
  };

  // Filter states
  const [filters, setFilters] = useState(loadPersistedFilters());

  // Save filters to localStorage whenever they change
  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      localStorage.setItem("matches_filters", JSON.stringify(filters));
    } catch (e) {
      console.warn("[MatchesPage] Failed to save filters:", e);
    }
  }, [filters]);

  const [homeTeamMode, setHomeTeamMode] = useState<"registered" | "opponent">("registered");
  const [awayTeamMode, setAwayTeamMode] = useState<"registered" | "opponent">("opponent");

  // Load team modes from localStorage when modal opens - CRITICAL: Load every time modal opens
  useEffect(() => {
    if (showCreateMatch) {
      // Use setTimeout to ensure this runs after component render
      const loadFromStorage = () => {
        if (typeof window === "undefined") return;

        try {
          const storedHome = localStorage.getItem("matchForm_homeTeamMode");
          const storedAway = localStorage.getItem("matchForm_awayTeamMode");

          if (storedHome === "registered" || storedHome === "opponent") {
            setHomeTeamMode(storedHome);
          }

          if (storedAway === "registered" || storedAway === "opponent") {
            setAwayTeamMode(storedAway);
          }
        } catch (e) {
          console.error("[Matches] Failed to load from localStorage:", e);
        }
      };

      // Run immediately and also after a small delay to ensure state updates
      loadFromStorage();
      const timer = setTimeout(loadFromStorage, 10);

      return () => clearTimeout(timer);
    }
  }, [showCreateMatch]);

  // Save team modes to localStorage when they change
  useEffect(() => {
    try {
      localStorage.setItem("matchForm_homeTeamMode", homeTeamMode);
    } catch (e) {
      console.warn("[Matches] Failed to save homeTeamMode:", e);
    }
  }, [homeTeamMode]);

  useEffect(() => {
    try {
      localStorage.setItem("matchForm_awayTeamMode", awayTeamMode);
    } catch (e) {
      console.warn("[Matches] Failed to save awayTeamMode:", e);
    }
  }, [awayTeamMode]);

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
    reset,
    watch,
    setValue,
  } = useForm<MatchFormData>({
    resolver: zodResolver(matchSchema),
    defaultValues: {
      homeTeamId: "",
      awayTeamId: "",
      homeTeamName: "",
      awayTeamName: "",
      competition: "",
      venue: "",
      date: "",
      time: "",
      scoreHome: "",
      scoreAway: "",
      shotsHome: "",
      shotsAway: "",
    },
  });

  // Fetch teams once on mount
  useEffect(() => {
    async function fetchTeams() {
      try {
        const teamsRes = await fetch("/api/teams");
        if (teamsRes.ok) {
          const teamsData = await teamsRes.json();
          if (teamsData.ok) {
            setTeams(teamsData.teams);
          }
        }
      } catch (err) {
        console.error("Failed to load teams", err);
      }
    }
    fetchTeams();
  }, []);

  // Fetch matches with filters
  useEffect(() => {
    async function fetchMatches() {
      setLoading(true);
      try {
        const params = new URLSearchParams();
        if (filters.competition && filters.competition !== "All") {
          params.append("competition", filters.competition);
        }
        if (filters.season && filters.season !== "All") {
          params.append("season", filters.season);
        }
        if (filters.teamId && filters.teamId !== "All") {
          params.append("teamId", filters.teamId);
        }
        if (filters.dateFrom) {
          params.append("dateFrom", filters.dateFrom);
        }
        if (filters.dateTo) {
          params.append("dateTo", filters.dateTo);
        }
        if (filters.search.trim()) {
          params.append("search", filters.search.trim());
        }
        // Add cache busting
        params.append("t", Date.now().toString());

        const matchesRes = await fetch(`/api/matches?${params.toString()}`);
        if (matchesRes.ok) {
          const matchesData = await matchesRes.json();
          if (matchesData.ok) {
            // Apply client-side search filter for team names (SQLite limitation)
            let filteredMatches = matchesData.matches;
            if (filters.search.trim() && isNaN(parseInt(filters.search.trim()))) {
              const searchTerm = filters.search.trim().toLowerCase();
              filteredMatches = matchesData.matches.filter((m: Match) => 
                (m.homeTeam?.name || (m as any).homeTeamName || "").toLowerCase().includes(searchTerm) ||
                (m.awayTeam?.name || (m as any).awayTeamName || "").toLowerCase().includes(searchTerm)
              );
            }
            setMatches(filteredMatches);
          }
        }
      } catch (err) {
        console.error("Failed to load matches", err);
      } finally {
        setLoading(false);
      }
    }

    // Debounce search to avoid too many requests
    const timeoutId = setTimeout(() => {
      fetchMatches();
    }, filters.search ? 300 : 0);

    return () => clearTimeout(timeoutId);
  }, [filters]);

  async function handleCreateMatch(data: MatchFormData) {
    try {
      // Validate teams based on mode
      if (homeTeamMode === "registered" && !data.homeTeamId) {
        toast.error("Please select a home team");
        return;
      }
      if (homeTeamMode === "opponent" && !data.homeTeamName?.trim()) {
        toast.error("Please enter home team name");
        return;
      }
      if (awayTeamMode === "registered" && !data.awayTeamId) {
        toast.error("Please select an away team");
        return;
      }
      if (awayTeamMode === "opponent" && !data.awayTeamName?.trim()) {
        toast.error("Please enter away team name");
        return;
      }

      // Combine date and time
      const dateTime = data.time
        ? `${data.date}T${data.time}`
        : `${data.date}T12:00`;

      const requestBody: any = {
        competition: data.competition,
        venue: data.venue || undefined,
        date: dateTime,
        scoreHome: data.scoreHome ? parseInt(data.scoreHome) : undefined,
        scoreAway: data.scoreAway ? parseInt(data.scoreAway) : undefined,
        shotsHome: data.shotsHome ? parseInt(data.shotsHome) : undefined,
        shotsAway: data.shotsAway ? parseInt(data.shotsAway) : undefined,
      };

      // Add team data based on mode
      if (homeTeamMode === "registered" && data.homeTeamId) {
        requestBody.homeTeamId = parseInt(data.homeTeamId);
      } else if (homeTeamMode === "opponent" && data.homeTeamName?.trim()) {
        requestBody.homeTeamName = data.homeTeamName.trim();
      }

      if (awayTeamMode === "registered" && data.awayTeamId) {
        requestBody.awayTeamId = parseInt(data.awayTeamId);
      } else if (awayTeamMode === "opponent" && data.awayTeamName?.trim()) {
        requestBody.awayTeamName = data.awayTeamName.trim();
      }

      const res = await fetch("/api/matches", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(requestBody),
      });

      let result;
      try {
        result = await res.json();
      } catch (parseError) {
        console.error("[Matches] Failed to parse response:", parseError);
        toast.error("Invalid response from server. Please try again.");
        return;
      }

      if (!res.ok || !result.ok) {
        const errorMessage = result.message || `Failed to create match (Status: ${res.status})`;
        toast.error(errorMessage);
        return;
      }

      toast.success(t("matchAddedSuccessfully"));
      setShowCreateMatch(false);
      reset();
      router.refresh();
      // Trigger filter refresh by updating a filter (this will cause useEffect to re-run)
      setFilters({ ...filters });
    } catch (err) {
      console.error("[Matches] ❌ Network error:", err);
      const errorMessage = err instanceof Error ? err.message : "Network error. Please check your connection and try again.";
      toast.error(errorMessage);
    }
  }

  if (loading) {
    return (
      <div className="space-y-5 text-xs text-slate-700 dark:text-slate-200">
        <p className="text-slate-600 dark:text-slate-400">{t("loadingMatches")}</p>
      </div>
    );
  }

  return (
    <>
      <Toaster position="top-right" />
      <div className="min-h-screen bg-white dark:bg-slate-950">
        {/* Professional Header */}
        <header className="border-b border-slate-200 dark:border-slate-900/50 bg-white/80 dark:bg-slate-950/80 backdrop-blur-sm">
          <div className="mx-auto max-w-7xl px-6 py-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="flex h-12 w-12 items-center justify-center rounded-full bg-emerald-500/20 border border-emerald-500/30">
                  <svg className="h-6 w-6 text-emerald-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" />
                  </svg>
                </div>
                <div>
                  <h1 className="text-3xl font-bold tracking-tight text-slate-900 dark:text-white mb-1">{t("matches")}</h1>
                  <p className="text-sm text-slate-600 dark:text-slate-400">{t("matchesDescription")}</p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <button
                  onClick={() => setShowExportModal(true)}
                  className="flex items-center gap-2 rounded-lg border border-slate-300 dark:border-slate-700 bg-slate-100 dark:bg-slate-800/50 px-5 py-3 text-sm font-semibold text-slate-700 dark:text-slate-200 transition-all hover:bg-slate-200 dark:hover:bg-slate-800 hover:border-slate-400 dark:hover:border-slate-600"
                >
                  <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                  </svg>
                  {t("export")}
                </button>
                <button
                  onClick={() => setShowCreateMatch(true)}
                  className="flex items-center gap-2 rounded-lg bg-amber-500 px-6 py-3 text-sm font-semibold text-slate-950 shadow-lg shadow-amber-500/20 transition-all hover:bg-amber-400 hover:scale-105"
                >
