                      >
                        {deletingId === entry.id
                          ? t("deleting") || "Deleting..."
                          : t("deleteFeedback") || "Delete feedback"}
                      </button>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </main>

        <FeedbackModal
          isOpen={showFeedbackModal}
          onClose={() => setShowFeedbackModal(false)}
          onFeedbackSuccess={() => {
            void loadFeedback();
          }}
        />
      </div>
    </>
  );
}

"use client";

