                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                        </svg>
                      </div>
                      <span className="text-[11px] text-slate-400">Αγώνες</span>
                    </div>
                    <span className="text-[11px] font-semibold text-slate-200">{playerStats.matches}</span>
                  </div>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <div className="rounded bg-sky-500/20 p-0.5">
                        <svg className="h-3 w-3 text-sky-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                        </svg>
                      </div>
                      <span className="text-[11px] text-slate-400">Μ.Ο. Λεπτά</span>
                    </div>
                    <span className="text-[11px] font-semibold text-sky-300">
                      {playerStats.matches > 0 ? Math.round(playerStats.minutes / playerStats.matches) : 0}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </div>

        <div className="space-y-4 rounded-xl border border-slate-800 bg-slate-950/80 p-4 text-[11px] text-slate-300">
          <div>
            <p className="font-medium text-slate-200">Προφίλ Παίκτη</p>
            <p className="text-[10px] text-slate-500 mt-0.5">
              Λεπτομερείς πληροφορίες και μετρικές
            </p>
          </div>

          {/* Player Info Card */}
          <div className="rounded-lg border border-slate-800 bg-slate-950/50 p-4 space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-[10px] text-slate-500">Θέση</span>
              <span className="text-[11px] font-semibold text-slate-200">{player.position}</span>
            </div>
            {player.age && (
              <div className="flex items-center justify-between">
                <span className="text-[10px] text-slate-500">Ηλικία</span>
                <span className="text-[11px] font-semibold text-slate-200">{player.age} ετών</span>
              </div>
            )}
            {player.number && (
              <div className="flex items-center justify-between">
                <span className="text-[10px] text-slate-500">Φανέλα #</span>
                <span className="text-[11px] font-semibold text-slate-200">#{player.number}</span>
              </div>
            )}
            {player.team && (
              <div className="flex items-center justify-between">
                <span className="text-[10px] text-slate-500">Ομάδα</span>
                <span className="text-[11px] font-semibold text-slate-200">{player.team.name}</span>
              </div>
            )}
            {player.nationality && (
              <div className="flex items-center justify-between">
                <span className="text-[10px] text-slate-500">Εθνικότητα</span>
                <span className="text-[11px] font-semibold text-slate-200">{player.nationality}</span>
              </div>
            )}
            {player.foot && (
              <div className="flex items-center justify-between">
                <span className="text-[10px] text-slate-500">Προτιμώμενο Πόδι</span>
                <span className="text-[11px] font-semibold text-slate-200">{player.foot}</span>
              </div>
            )}
          </div>

          {/* Performance Rating */}
          {playerStats && (
            <div className="rounded-lg border border-slate-800 bg-gradient-to-br from-slate-950 to-slate-900 p-4">
              <p className="text-[10px] font-medium uppercase tracking-wide text-slate-500 mb-3">Αξιολόγηση Επιδόσεων</p>
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <span className="text-[11px] text-slate-400">Συνολική Αξιολόγηση</span>
                  <span className="text-lg font-bold text-emerald-400">
                    {((playerStats.goalsPer90 * 1.2 + playerStats.assistsPer90 * 0.8 + playerStats.xGPer90 * 0.5 + playerStats.passAccuracy / 10) / 4).toFixed(1)}
                  </span>
                </div>
                <div className="h-2 w-full rounded-full bg-slate-900 overflow-hidden">
                  <div 
                    className="h-full bg-gradient-to-r from-emerald-500 to-emerald-400 transition-all"
                    style={{ width: `${Math.min(100, ((playerStats.goalsPer90 * 1.2 + playerStats.assistsPer90 * 0.8 + playerStats.xGPer90 * 0.5 + playerStats.passAccuracy / 10) / 4) * 10)}%` }}
                  />
                </div>
              </div>
            </div>
          )}

          {/* Additional Database Metrics */}
          {(player.pressuresPer90 !== null || player.keyPassesPer90 !== null || player.progressivePassesPer90 !== null) && (
            <div className="rounded-lg border border-slate-800 bg-slate-950/50 p-4">
              <p className="text-[10px] font-medium uppercase tracking-wide text-slate-500 mb-3">Επιπλέον Μετρικές</p>
              <div className="space-y-2">
                {player.pressuresPer90 !== null && (
                  <div className="flex items-center justify-between">
                    <span className="text-[11px] text-slate-400">Πιέσεις / 90</span>
                    <span className="text-[11px] font-semibold text-slate-200">{player.pressuresPer90.toFixed(1)}</span>
                  </div>
                )}
                {player.keyPassesPer90 !== null && (
                  <div className="flex items-center justify-between">
                    <span className="text-[11px] text-slate-400">Κρίσιμες Πάσες / 90</span>
                    <span className="text-[11px] font-semibold text-slate-200">{player.keyPassesPer90.toFixed(1)}</span>
                  </div>
                )}
                {player.progressivePassesPer90 !== null && (
                  <div className="flex items-center justify-between">
                    <span className="text-[11px] text-slate-400">Προοδευτικές Πάσες / 90</span>
                    <span className="text-[11px] font-semibold text-slate-200">{player.progressivePassesPer90.toFixed(1)}</span>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
        </section>
      )}

      {/* Performance Trends */}
      {trends.length > 0 && (
        <section className="space-y-4 rounded-xl border border-slate-800 bg-slate-950/80 p-4 text-[11px] text-slate-300">
          <div className="flex items-center justify-between">
            <div>
              <p className="font-medium">Τάσεις Επιδόσεων</p>
              <p className="text-[10px] text-slate-500">Επιδόσεις παίκτη με την πάροδο του χρόνου σε αγώνες</p>
            </div>
          </div>
          <div className="grid gap-4 md:grid-cols-2">
            <PlayerTrendsChart
              trends={trends}
              metric="goals"
              title="Γκολ"
            />
            <PlayerTrendsChart
              trends={trends}
              metric="assists"
              title="Ασίστ"
            />
            <PlayerTrendsChart
              trends={trends}
              metric="xg"
              title="Αναμενόμενα Γκολ (xG)"
            />
            <PlayerTrendsChart
              trends={trends}
              metric="xa"
              title="Αναμενόμενες Ασίστ (xA)"
            />
            <PlayerTrendsChart
              trends={trends}
              metric="shots"
              title="Σουτ"
            />
            <PlayerTrendsChart
              trends={trends}
              metric="passes"
              title="Πάσες"
            />
          </div>
        </section>
      )}

      <section className="space-y-3 rounded-xl border border-slate-800 bg-slate-950/80 p-4 text-[11px] text-slate-300">
        <div className="flex items-center justify-between">
          <div>
            <p className="font-medium">Σχόλια προπονητικού επιτελείου</p>
            <p className="text-[10px] text-slate-500">
              Μοιραστείτε σημειώσεις μεταξύ προπονητή, αναλυτών και σκάουτερ για αυτόν τον παίκτη.
            </p>
          </div>
        </div>

        <div className="space-y-2">
          {comments.length === 0 && (
            <p className="text-[10px] text-slate-500">Δεν υπάρχουν ακόμα σχόλια. Ξεκινήστε τη συζήτηση με το επιτελείο σας.</p>
          )}
          {comments.map((c) => (
            <div key={c.id} className="space-y-1 rounded-lg border border-slate-800 bg-slate-950 p-2">
              <div className="flex items-center justify-between text-[10px] text-slate-400">
                <span>{c.author}</span>
                <span>{new Date(c.createdAt).toLocaleString()}</span>
              </div>
              <p className="text-[11px] text-slate-200">{c.body}</p>
            </div>
          ))}
        </div>

        <form onSubmit={handleSubmitComment} className="space-y-2">
          <label className="text-[11px] text-slate-400">Νέο σχόλιο</label>
          <textarea
            className="min-h-[60px] w-full rounded-md border border-slate-800 bg-slate-900 p-2 text-[11px] text-slate-100 outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500/60"
            placeholder="Τακτικές σημειώσεις, εστίαση ανάπτυξης, ID σημαντικών clips..."
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
          />
          <button
            type="submit"
            disabled={isSubmitting || !newComment.trim()}
            className="h-8 w-full rounded-md bg-emerald-500 text-[11px] font-semibold text-slate-950 shadow-sm transition hover:bg-emerald-400 disabled:cursor-not-allowed disabled:opacity-60"
          >
            {isSubmitting ? "Αποστολή..." : "Προσθήκη σχολίου"}
          </button>
        </form>
      </section>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import { PlayerRadarChart } from "@/app/components/PlayerRadarChart";
import toast, { Toaster } from "react-hot-toast";
import { useTranslation } from "@/lib/i18n";

type Player = {
  id: number;
  name: string;
  position: string;
  age: number | null;
  number: number | null;
  team: { id: number; name: string } | null;
};

type PlayerStats = {
  id: number;
  name: string;
  position: string;
  age: number | null;
  number: number | null;
  team: { id: number; name: string } | null;
  matches: number;
  minutes: number;
  goals: number;
  assists: number;
  shots: number;
  shotsOnTarget: number;
  totalXG: number;
  averageXG: number;
  xA: number;
  passes: number;
  successfulPasses: number;
  passAccuracy: number;
  touches: number;
  goalsPer90: number;
  assistsPer90: number;
  shotsPer90: number;
  xGPer90: number;
  xAPer90: number;
  passesPer90: number;
  touchesPer90: number;
  radarMetrics: {
    shooting: number;
    creativity: number;
    passing: number;
    involvement: number;
    efficiency: number;
  };
};

export default function PlayerComparePage() {
  const { t } = useTranslation();
  const router = useRouter();
  const searchParams = useSearchParams();
  const [allPlayers, setAllPlayers] = useState<Player[]>([]);
  const [selectedPlayers, setSelectedPlayers] = useState<number[]>([]);
  const [playerStats, setPlayerStats] = useState<PlayerStats[]>([]);
  const [loading, setLoading] = useState(false);
  const [showPer90, setShowPer90] = useState(true);
  const [mounted, setMounted] = useState(false);
  const [statCategory, setStatCategory] = useState<"all" | "attacking" | "passing">("all");

  // Fix hydration mismatch by only rendering dynamic content after mount
  useEffect(() => {
    setMounted(true);
  }, []);

  // Load player IDs from URL query params or localStorage
  useEffect(() => {
    const idsParam = searchParams.get("ids");
    console.log("[PlayerCompare] URL ids param:", idsParam, "searchParams:", searchParams.toString());

    let ids: number[] = [];

    if (idsParam) {
      // Priority 1: Use URL params if available
      ids = idsParam.split(",").map(id => parseInt(id.trim())).filter(id => !isNaN(id));
      console.log("[PlayerCompare] Parsed IDs from URL:", ids, "count:", ids.length);

      // Save to localStorage for persistence
      if (ids.length >= 1 && ids.length <= 4) {
        try {
          localStorage.setItem("playerComparisonIds", JSON.stringify(ids));
          console.log("[PlayerCompare] Saved to localStorage:", ids);
        } catch (e) {
          console.warn("[PlayerCompare] Failed to save to localStorage:", e);
        }
      }
    } else {
      // Priority 2: Try to load from localStorage (for server reloads)
      try {
        const stored = localStorage.getItem("playerComparisonIds");
        if (stored) {
          const parsedIds = JSON.parse(stored);
          if (Array.isArray(parsedIds) && parsedIds.length >= 1 && parsedIds.length <= 4) {
            ids = parsedIds.map(id => parseInt(String(id))).filter(id => !isNaN(id) && id > 0);
            console.log("[PlayerCompare] Loaded from localStorage:", ids);

            // Update URL to match localStorage
            if (ids.length >= 1) {
              router.replace(`/players/compare?ids=${ids.join(",")}`);
            }
          }
        }
      } catch (e) {
        console.warn("[PlayerCompare] Failed to load from localStorage:", e);
      }
    }

    if (ids.length >= 1 && ids.length <= 4) {
      console.log("[PlayerCompare] Setting selected players:", ids);
      // Remove duplicates
      const uniqueIds = Array.from(new Set(ids));
      console.log("[PlayerCompare] Unique IDs:", uniqueIds);
      setSelectedPlayers(uniqueIds);
    } else if (ids.length === 0) {
      // If no IDs in URL or localStorage, redirect to players page
      console.log("[PlayerCompare] No IDs found, redirecting to /players");
      router.push("/players");
    } else {
      console.warn("[PlayerCompare] Invalid number of players:", ids.length);
      toast.error("Please select 1-4 players to compare");
      router.push("/players");
    }
  }, [searchParams, router]);

  useEffect(() => {
    // Fetch all players for selection (with pagination to get all)
    const fetchAllPlayers = async () => {
      try {
        console.log("[PlayerCompare] Starting to fetch all players...");
        let allPlayersList: Player[] = [];
        let page = 1;
        let hasMore = true;

        while (hasMore) {
          const res = await fetch(`/api/players?page=${page}&limit=50`);
          const data = await res.json();

          if (data.ok && Array.isArray(data.players)) {
            allPlayersList = [...allPlayersList, ...data.players];
            console.log(`[PlayerCompare] Loaded page ${page}: ${data.players.length} players (total: ${allPlayersList.length})`);
            hasMore = data.pagination?.hasMore || false;
            page++;
          } else {
            hasMore = false;
          }
        }

        console.log("[PlayerCompare] ✅ Loaded ALL players:", allPlayersList.length);
        console.log("[PlayerCompare] Player IDs:", allPlayersList.map(p => `${p.id}: ${p.name}`));
        setAllPlayers(allPlayersList);
      } catch (error) {
        console.error("[PlayerCompare] Failed to load players:", error);
        toast.error("Failed to load players");
      }
    };

    fetchAllPlayers();
  }, []);

  useEffect(() => {
    console.log("[PlayerCompare] selectedPlayers changed:", selectedPlayers, "length:", selectedPlayers.length);
    console.log("[PlayerCompare] allPlayers count:", allPlayers.length);
    if (selectedPlayers.length >= 1 && selectedPlayers.length <= 4) {
      // Wait a bit to ensure allPlayers are loaded, but don't wait too long
      const timer = setTimeout(() => {
        console.log("[PlayerCompare] Calling fetchComparison with selectedPlayers:", selectedPlayers);
        console.log("[PlayerCompare] allPlayers available:", allPlayers.length > 0);
        fetchComparison();
      }, 200); // Increased timeout to ensure allPlayers are loaded
      return () => clearTimeout(timer);
    } else {
      setPlayerStats([]);
    }
  }, [selectedPlayers, allPlayers.length]); // Add allPlayers.length as dependency

  async function fetchComparison() {
    if (selectedPlayers.length < 1) {
      console.warn("[PlayerCompare] fetchComparison called but selectedPlayers is empty");
      return;
    }

    // Wait for allPlayers to be loaded if not ready
    if (allPlayers.length === 0) {
      console.warn("[PlayerCompare] allPlayers not loaded yet, waiting...");
      setTimeout(() => fetchComparison(), 500);
      return;
    }

    setLoading(true);
    try {
      // Remove duplicates and ensure we have valid IDs
      const uniqueIds = Array.from(new Set(selectedPlayers)).filter(id => id > 0);
      console.log("[PlayerCompare] Fetching comparison for players:", uniqueIds, "count:", uniqueIds.length);
      console.log("[PlayerCompare] allPlayers available:", allPlayers.length, "players");
      console.log("[PlayerCompare] Checking if all selected players exist in allPlayers:");
      uniqueIds.forEach(id => {
        const exists = allPlayers.some(p => p.id === id);
        const player = allPlayers.find(p => p.id === id);
        console.log(`[PlayerCompare]   ID ${id}: ${exists ? `YES (${player?.name})` : 'NO'}`);
      });

      if (uniqueIds.length === 0) {
        console.warn("[PlayerCompare] No valid player IDs");
        setLoading(false);
        return;
      }

      const res = await fetch("/api/players/compare", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ playerIds: uniqueIds }),
        credentials: "include",
      });

      let data: any = {};
      try {
        data = await res.json();
      } catch (jsonError) {
        console.error("[PlayerCompare] Failed to parse JSON:", jsonError);
        toast.error("Invalid response from server");
        setPlayerStats([]);
        return;
      }

      console.log("[PlayerCompare] API response:", { 
        status: res.status, 
        ok: res.ok, 
        dataOk: data.ok, 
        hasPlayers: !!data.players,
        playersCount: data.players?.length 
      });

      const successPayload =
        res.ok &&
        data &&
        typeof data === "object" &&
        Array.isArray(data.players) &&
        data.ok !== false;

      if (successPayload) {
        console.log("[PlayerCompare] ✅ Successfully received", data.players.length, "players from API");
        console.log("[PlayerCompare] Player stats data:", data.players.map((p: any) => ({ id: p.id, name: p.name })));
        console.log("[PlayerCompare] Expected", uniqueIds.length, "players, got", data.players.length);

        const receivedPlayersMap = new Map(
          data.players.map((p: any) => [Number(p.id), p]),
        );

        const missingFromApi = uniqueIds.filter((id) => !receivedPlayersMap.has(Number(id)));

        if (missingFromApi.length > 0) {
          toast(t("comparePlayersSkippedUnavailable"), { icon: "ℹ️" });
        }

        const keptIds = uniqueIds.filter((id) => receivedPlayersMap.has(Number(id)));

        if (keptIds.length === 0) {
          toast.error(t("compareNoPlayersLoaded"));
          try {
            localStorage.removeItem("playerComparisonIds");
          } catch {
            /* ignore */
          }
          router.replace("/players");
          setPlayerStats([]);
          return;
        }

        const idsChanged =
          keptIds.length !== uniqueIds.length ||
          !keptIds.every((id, i) => id === uniqueIds[i]);

        if (idsChanged) {
          setSelectedPlayers(keptIds);
          router.replace(`/players/compare?ids=${keptIds.join(",")}`);
          try {
            localStorage.setItem("playerComparisonIds", JSON.stringify(keptIds));
          } catch {
            /* ignore */
          }
        }

        const finalStats: any[] = [];
        for (const id of keptIds) {
          const row = receivedPlayersMap.get(Number(id));
          if (row) finalStats.push(row);
        }

        setPlayerStats(finalStats);
      } else {
        const hint = [
          `http ${res.status}`,
          typeof data?.ok !== "undefined" ? `body.ok=${data.ok}` : null,
          data?.message ? `message=${data.message}` : null,
        ]
          .filter(Boolean)
          .join(", ");
        console.warn("[PlayerCompare] Compare unavailable:", hint || "unknown");
        toast.error(
          data?.message ||
            (res.status === 401
              ? t("compareLoginRequired") || "Please log in to compare players."
              : `Failed to load comparison (${res.status})`),
        );
        setPlayerStats([]);
      }
    } catch (error) {
      console.error("[PlayerCompare] Network error:", error);
      toast.error("Network error. Please try again.");
      setPlayerStats([]);
    } finally {
      setLoading(false);
    }
  }

  function handlePlayerSelect(playerId: number) {
    if (selectedPlayers.includes(playerId)) {
      const newSelected = selectedPlayers.filter((id) => id !== playerId);
      setSelectedPlayers(newSelected);
      // Update URL and localStorage
      if (newSelected.length >= 1) {
        const idsParam = newSelected.join(",");
        router.push(`/players/compare?ids=${idsParam}`);
        try {
          localStorage.setItem("playerComparisonIds", JSON.stringify(newSelected));
          console.log("[PlayerCompare] Updated localStorage:", newSelected);
        } catch (e) {
          console.warn("[PlayerCompare] Failed to update localStorage:", e);
        }
      } else {
        router.push("/players");
        try {
          localStorage.removeItem("playerComparisonIds");
          console.log("[PlayerCompare] Cleared localStorage");
        } catch (e) {
          console.warn("[PlayerCompare] Failed to clear localStorage:", e);
        }
      }
    } else {
      if (selectedPlayers.length < 4) {
        const newSelected = [...selectedPlayers, playerId];
        setSelectedPlayers(newSelected);
        // Update URL and localStorage
        const idsParam = newSelected.join(",");
        router.push(`/players/compare?ids=${idsParam}`);
        try {
          localStorage.setItem("playerComparisonIds", JSON.stringify(newSelected));
          console.log("[PlayerCompare] Updated localStorage:", newSelected);
        } catch (e) {
          console.warn("[PlayerCompare] Failed to update localStorage:", e);
        }
      } else {
        toast.error("Maximum 4 players can be compared");
      }
    }
  }

  function getSelectedPlayerNames() {
    return selectedPlayers
      .map((id) => allPlayers.find((p) => p.id === id)?.name)
      .filter(Boolean);
  }

  // Icon component for stats
  function StatIcon({ statKey }: { statKey: string }) {
    const iconClass = "h-4 w-4 text-slate-400";
    switch (statKey) {
      case "matches":
        return (
          <svg className={iconClass} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
          </svg>
        );
      case "minutes":
        return (
          <svg className={iconClass} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
        );
      case "goals":
        return (
          <svg className={iconClass} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
          </svg>
        );
      case "assists":
        return (
          <svg className={iconClass} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
          </svg>
        );
      case "shots":
        return (
          <svg className={iconClass} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 15l-2 5L9 9l11 4-5 2zm0 0l5 5M7.188 2.239l.777 2.897M5.136 7.965l-2.898-.777M13.95 4.05l-2.122 2.122m-5.657 5.656l-2.12 2.122" />
          </svg>
        );
      case "shotsOnTarget":
        return (
          <svg className={iconClass} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
          </svg>
        );
      case "totalXG":
      case "averageXG":
        return (
          <svg className={iconClass} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
          </svg>
        );
      case "xA":
        return (
          <svg className={iconClass} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
        );
      case "passes":
      case "successfulPasses":
        return (
          <svg className={iconClass} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4" />
          </svg>
        );
      case "passAccuracy":
        return (
          <svg className={iconClass} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
        );
      case "touches":
        return (
          <svg className={iconClass} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21a4 4 0 01-4-4V5a2 2 0 012-2h4a2 2 0 012 2v12a4 4 0 01-4 4zm0 0h12a2 2 0 002-2v-4a2 2 0 00-2-2h-2.343M11 7.343l1.657-1.657a2 2 0 012.828 0l2.829 2.829a2 2 0 010 2.828l-8.486 8.485M7 17h.01" />
          </svg>
        );
      default:
        return (
          <svg className={iconClass} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
          </svg>
        );
    }
  }

  const allStats = [
    { label: "Matches", key: "matches", per90: false, category: "all" as const },
    { label: "Minutes", key: "minutes", per90: false, category: "all" as const },
    { label: "Goals", key: "goals", per90Key: "goalsPer90", category: "attacking" as const },
    { label: "Assists", key: "assists", per90Key: "assistsPer90", category: "attacking" as const },
    { label: "Shots", key: "shots", per90Key: "shotsPer90", category: "attacking" as const },
    { label: "Shots on Target", key: "shotsOnTarget", per90: false, category: "attacking" as const },
    { label: "Total xG", key: "totalXG", per90Key: "xGPer90", category: "attacking" as const },
    { label: "Average xG", key: "averageXG", per90: false, category: "attacking" as const },
    { label: "xA", key: "xA", per90Key: "xAPer90", category: "attacking" as const },
    { label: "Passes", key: "passes", per90Key: "passesPer90", category: "passing" as const },
    { label: "Successful Passes", key: "successfulPasses", per90: false, category: "passing" as const },
    { label: "Pass Accuracy", key: "passAccuracy", per90: false, format: (v: number) => `${v.toFixed(1)}%`, category: "passing" as const },
    { label: "Touches", key: "touches", per90Key: "touchesPer90", category: "all" as const },
  ];

  const comparisonStats = statCategory === "all"
    ? allStats
    : allStats.filter((s) => s.category === statCategory);

  return (
    <>
      <Toaster position="top-right" />
      <div className="space-y-5 text-xs text-slate-200">
        {/* Header */}
        <header className="flex items-center justify-between rounded-xl border border-slate-800 bg-gradient-to-r from-slate-900 via-slate-950 to-slate-900 px-4 py-3">
          <div className="space-y-0.5">
            <div className="flex items-center gap-2">
              <Link href="/players" className="text-slate-400 hover:text-slate-200 transition" suppressHydrationWarning>
                ← Back to Players
              </Link>
            </div>
            <h1 className="text-lg font-semibold tracking-tight text-slate-900 dark:text-slate-50">{t("playerComparison")}</h1>
            <p className="text-[11px] text-slate-600 dark:text-slate-500">
              {mounted && selectedPlayers.length > 0 ? (
                <>{t("playerComparisonDescription")}</>
              ) : (
                <>{t("playerComparisonDescription")}</>
              )}
            </p>
          </div>
          <div className="flex items-center gap-2">
            <Link
              href="/players"
              className="h-8 rounded-md bg-slate-800 px-4 text-[11px] font-medium text-slate-200 hover:bg-slate-700 transition"
            >
              Change Selection
            </Link>
          </div>
        </header>

        {/* Quick Add More Players - Only show if less than 4 selected */}
        {selectedPlayers.length < 4 && selectedPlayers.length >= 2 && (
          <div className="rounded-xl border border-slate-800 bg-slate-950/80 p-4">
            <div className="mb-4 flex items-center justify-between">
              <p className="text-sm font-medium text-slate-200">Add More Players ({selectedPlayers.length}/4)</p>
              <Link
                href="/players"
                className="text-[11px] text-emerald-400 hover:text-emerald-300 transition"
              >
                Select from Players →
              </Link>
            </div>
            <div className="grid gap-2 md:grid-cols-2 lg:grid-cols-3 max-h-48 overflow-y-auto">
              {allPlayers
                .filter(p => !selectedPlayers.includes(p.id))
                .slice(0, 6)
                .map((player) => (
                  <button
                    key={player.id}
                    onClick={() => handlePlayerSelect(player.id)}
                    className="flex items-center gap-2 rounded-lg border border-slate-800 bg-slate-900 px-3 py-2 text-left text-[11px] text-slate-300 transition hover:bg-slate-800"
                  >
                    <div className="flex h-6 w-6 items-center justify-center rounded-full bg-emerald-500/20 text-[10px] font-semibold text-emerald-300">
                      {player.number || player.name.charAt(0)}
                    </div>
                    <div className="flex-1">
                      <p className="font-medium">{player.name}</p>
                      <p className="text-[10px] text-slate-500">{player.position}</p>
                    </div>
                    <span className="text-slate-400">+</span>
                  </button>
                ))}
            </div>
          </div>
        )}

        {/* Selected Players Display (like Instat/Wyscout) */}
        {selectedPlayers.length >= 1 && (
          <div className="rounded-xl border border-slate-800 bg-slate-950/80 p-4">
            <p className="mb-3 text-sm font-medium text-slate-200">Select Players ({selectedPlayers.length}/4)</p>
            <div className="flex flex-wrap gap-3">
              {selectedPlayers.map((playerId) => {
                const player = allPlayers.find((p) => p.id === playerId);
                if (!player) {
                  console.warn("[PlayerCompare] Player not found in allPlayers:", playerId);
                  return null;
                }
                return (
                  <div
                    key={playerId}
                    className="flex items-center gap-2 rounded-lg border border-slate-800 bg-slate-900 px-3 py-2"
                  >
                    <div className="flex h-8 w-8 items-center justify-center rounded-full bg-emerald-500/20 text-[10px] font-semibold text-emerald-300">
                      {player.number || player.name.charAt(0)}
                    </div>
                    <div>
                      <p className="text-[11px] font-medium text-slate-100">{player.name}</p>
                      <p className="text-[10px] text-slate-500">
                        {player.position} {player.team ? `• ${player.team.name}` : ""}
                      </p>
                    </div>
                    <button
                      onClick={() => handlePlayerSelect(playerId)}
                      className="ml-2 text-slate-400 hover:text-red-400 transition"
                    >
                      ×
                    </button>
                  </div>
                );
              })}
            </div>
            {selectedPlayers.length < 2 && (
              <p className="mt-3 text-center text-[11px] text-slate-500">
                Select 1-4 players to view their statistics
              </p>
            )}
          </div>
        )}

        {/* Comparison Results */}
        {loading && (
          <div className="rounded-xl border border-slate-800 bg-slate-950/80 p-8 text-center">
            <p className="text-slate-400">Loading comparison data...</p>
          </div>
        )}

        {!loading && selectedPlayers.length < 2 && (
          <div className="rounded-xl border border-slate-800 bg-slate-950/80 p-8 text-center">
            <p className="text-slate-400 mb-2">Please select at least 2 players to compare</p>
            <Link
              href="/players"
              className="inline-block rounded-md bg-emerald-500 px-4 py-2 text-[11px] font-medium text-white hover:bg-emerald-400 transition"
            >
              Go to Players →
            </Link>
          </div>
        )}

        {/* Show comparison if we have at least 1 player with stats OR if we have selected players but no stats yet */}
        {!loading && (playerStats.length >= 1 || (selectedPlayers.length >= 1 && playerStats.length === 0)) && (
          <>
            {/* Player Header Cards - Instat/StepOut Style */}
            {playerStats.length >= 1 && (
              <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4">
                {playerStats.map((player, idx) => {
                  const colorClasses = [
                    { bg: "from-emerald-500/20 to-emerald-600/10", text: "text-emerald-300", border: "border-emerald-500/40", accent: "text-emerald-400", bar: "bg-emerald-500", cardBg: "bg-emerald-500/5" },
                    { bg: "from-blue-500/20 to-blue-600/10", text: "text-blue-300", border: "border-blue-500/40", accent: "text-blue-400", bar: "bg-blue-500", cardBg: "bg-blue-500/5" },
                    { bg: "from-purple-500/20 to-purple-600/10", text: "text-purple-300", border: "border-purple-500/40", accent: "text-purple-400", bar: "bg-purple-500", cardBg: "bg-purple-500/5" },
                    { bg: "from-orange-500/20 to-orange-600/10", text: "text-orange-300", border: "border-orange-500/40", accent: "text-orange-400", bar: "bg-orange-500", cardBg: "bg-orange-500/5" },
                  ];
                  const color = colorClasses[idx % colorClasses.length];

                  return (
                    <div key={player.id} className={`rounded-xl border-2 ${color.border} bg-gradient-to-br ${color.bg} p-4 backdrop-blur-sm`}>
                      <div className="flex items-center gap-3 mb-4">
                        <div className={`flex h-14 w-14 items-center justify-center rounded-full ${color.cardBg} text-lg font-bold ${color.text} border-2 ${color.border} shadow-lg`}>
                          {player.number || player.name.charAt(0)}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="font-bold text-base text-white truncate">{player.name}</p>
                          <p className="text-[11px] text-slate-400">{player.position}</p>
                          {player.team && (
                            <p className="text-[10px] text-slate-500 truncate">{player.team.name}</p>
                          )}
                        </div>
                      </div>

                      {statCategory === "all" && (
                        <>
                          <div className="grid grid-cols-2 gap-3 mb-3">
                            <div className={`rounded-lg ${color.cardBg} p-2.5 border ${color.border}/30`}>
                              <p className="text-[10px] text-slate-400 mb-1">Matches</p>
                              <p className={`text-xl font-bold ${color.accent}`}>{player.matches}</p>
                            </div>
                            <div className={`rounded-lg ${color.cardBg} p-2.5 border ${color.border}/30`}>
                              <p className="text-[10px] text-slate-400 mb-1">Minutes</p>
                              <p className={`text-xl font-bold ${color.accent}`}>{player.minutes}</p>
                            </div>
                          </div>

                          <div className="grid grid-cols-3 gap-2 pt-2 border-t border-slate-800/50">
                            <div className="text-center">
                              <p className="text-[9px] text-slate-400 mb-0.5">Goals</p>
                              <p className={`text-sm font-bold ${color.accent}`}>{player.goals}</p>
                            </div>
                            <div className="text-center">
                              <p className="text-[9px] text-slate-400 mb-0.5">Assists</p>
                              <p className={`text-sm font-bold ${color.accent}`}>{player.assists}</p>
                            </div>
                            <div className="text-center">
                              <p className="text-[9px] text-slate-400 mb-0.5">xG</p>
                              <p className={`text-sm font-bold ${color.text}`}>{player.totalXG.toFixed(1)}</p>
                            </div>
                          </div>
                        </>
                      )}

                      {statCategory === "attacking" && (
                        <div className="grid grid-cols-3 gap-2 pt-2 border-t border-slate-800/50">
                          <div className="text-center">
                            <p className="text-[9px] text-slate-400 mb-0.5">Goals</p>
                            <p className={`text-sm font-bold ${color.accent}`}>{player.goals}</p>
                          </div>
                          <div className="text-center">
                            <p className="text-[9px] text-slate-400 mb-0.5">Shots</p>
                            <p className={`text-sm font-bold ${color.accent}`}>{player.shots}</p>
                          </div>
                          <div className="text-center">
                            <p className="text-[9px] text-slate-400 mb-0.5">xG</p>
                            <p className={`text-sm font-bold ${color.text}`}>{player.totalXG.toFixed(1)}</p>
                          </div>
                        </div>
                      )}

                      {statCategory === "passing" && (
                        <div className="grid grid-cols-3 gap-2 pt-2 border-t border-slate-800/50">
                          <div className="text-center">
                            <p className="text-[9px] text-slate-400 mb-0.5">Passes</p>
                            <p className={`text-sm font-bold ${color.accent}`}>{player.passes}</p>
                          </div>
                          <div className="text-center">
                            <p className="text-[9px] text-slate-400 mb-0.5">Successful</p>
                            <p className={`text-sm font-bold ${color.accent}`}>{player.successfulPasses}</p>
                          </div>
                          <div className="text-center">
                            <p className="text-[9px] text-slate-400 mb-0.5">Accuracy</p>
                            <p className={`text-sm font-bold ${color.text}`}>{player.passAccuracy.toFixed(1)}%</p>
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}

            {/* Controls Bar - Toggle and Category Tabs */}
            {playerStats.length >= 1 && (
              <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 rounded-xl border border-slate-800 bg-slate-950/80 p-4">
                <div className="flex items-center gap-2">
                  <span className="text-[11px] text-slate-400 font-medium">Categories:</span>
                  <div className="flex gap-1 bg-slate-900/50 p-1 rounded-lg border border-slate-800">
                    {(["all", "attacking", "passing"] as const).map((cat) => (
                      <button
                        key={cat}
                        onClick={() => setStatCategory(cat)}
                        className={`px-3 py-1.5 text-[11px] font-medium rounded-md transition ${
                          statCategory === cat
                            ? "bg-emerald-500 text-white shadow-lg"
                            : "text-slate-400 hover:text-slate-200 hover:bg-slate-800/50"
                        }`}
                      >
                        {cat.charAt(0).toUpperCase() + cat.slice(1)}
                      </button>
                    ))}
                  </div>
                </div>
                <label className="flex items-center gap-2 text-[11px] text-slate-400 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={showPer90}
                    onChange={(e) => setShowPer90(e.target.checked)}
                    className="h-4 w-4 rounded border-slate-700 bg-slate-900 text-emerald-500 focus:ring-2 focus:ring-emerald-500/50 transition"
                  />
                  Show per 90 minutes
                </label>
              </div>
            )}

            {/* Info message if no events */}
            {playerStats.length > 0 && playerStats.every((p) => p.matches === 0) && (
              <div className="mb-4 rounded-lg border border-yellow-500/30 bg-yellow-500/10 p-4 text-center">
                <p className="text-sm text-yellow-400">
                  ⚠️ Selected players have no match events yet.
                </p>
                <p className="mt-1 text-[11px] text-yellow-300/80">
                  Add events to matches to see detailed statistics. Go to a match and add shots, passes, and touches.
                </p>
              </div>
            )}

            {/* Radar by selected category */}
            {playerStats.length >= 2 && playerStats.some(p => p.matches > 0) && (
              <PlayerRadarChart players={playerStats} mode={statCategory} />
            )}

            {/* Stats Comparison Table - Enhanced Instat/StepOut Style */}
            <div className="overflow-hidden rounded-xl border-2 border-slate-800 bg-gradient-to-br from-slate-950 via-slate-950 to-slate-900 shadow-2xl">
              <div className="border-b-2 border-slate-800 bg-gradient-to-r from-slate-900/80 to-slate-950/80 px-6 py-5 backdrop-blur-sm">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-lg font-bold text-white">Statistics Comparison</p>
                    <p className="text-[11px] text-slate-400 mt-1">Side-by-side performance metrics</p>
                  </div>
                </div>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full border-collapse">
                  <thead>
                    <tr className="border-b-2 border-slate-800 bg-slate-900/60">
                      <th className="px-6 py-5 text-left font-bold text-slate-200 uppercase tracking-wider text-[12px] sticky left-0 z-10 bg-slate-900/95 backdrop-blur-sm">
                        <div className="flex items-center gap-2">
                          <span>Statistic</span>
                        </div>
                      </th>
                      {playerStats.map((player, idx) => {
                        const colorClasses = [
                          "border-emerald-500/40",
                          "border-blue-500/40",
                          "border-purple-500/40",
                          "border-orange-500/40",
                        ];
                        return (
                          <th key={player.id} className={`px-6 py-5 text-center border-l-2 ${colorClasses[idx % colorClasses.length]} bg-slate-900/40`}>
                            <div>
                              <p className="font-bold text-base text-white">{player.name}</p>
                              <p className="text-[10px] text-slate-400 mt-1">{player.position}</p>
                              {player.team && (
                                <p className="text-[9px] text-slate-500 mt-0.5">{player.team.name}</p>
                              )}
                            </div>
                          </th>
                        );
                      })}
                    </tr>
                  </thead>
                  <tbody>
                    {comparisonStats.map((stat, statIdx) => {
                      const valueKey = showPer90 && stat.per90Key ? stat.per90Key : stat.key;
                      const format = stat.format || ((v: number) => v.toFixed(stat.per90 ? 2 : 1));

                      // Get all values for this stat to find min/max
                      const values = playerStats.map((p) => (p as any)[valueKey] || 0);
                      const maxValue = Math.max(...values);
                      const minValue = Math.min(...values);
                      const hasVariation = maxValue !== minValue && maxValue > 0;

                      return (
                        <tr 
                          key={stat.key} 
                          className={`border-b border-slate-800/50 hover:bg-slate-900/40 transition-all group ${
                            statIdx % 2 === 0 ? 'bg-slate-950/30' : 'bg-slate-950/10'
                          }`}
                        >
                          <td className="px-6 py-4 sticky left-0 z-10 bg-inherit backdrop-blur-sm">
                            <div className="flex items-center gap-3">
                              <div className="flex-shrink-0">
                                <StatIcon statKey={stat.key} />
                              </div>
                              <span className="font-semibold text-slate-200 text-sm">{stat.label}</span>
                              {showPer90 && stat.per90Key && (
                                <span className="text-[10px] text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded-full border border-emerald-500/30">
                                  per 90
                                </span>
                              )}
                            </div>
                          </td>
                          {playerStats.map((player, idx) => {
                            const value = (player as any)[valueKey] || 0;
                            const isBest = hasVariation && value === maxValue && value > 0;
                            const isWorst = hasVariation && value === minValue && maxValue > 0 && playerStats.length > 1;
                            const percentage = hasVariation && maxValue > 0 ? (value / maxValue) * 100 : 0;

                            const colorClasses = [
                              { best: "text-emerald-400", worst: "text-red-400", bar: "bg-emerald-500", border: "border-emerald-500/40" },
                              { best: "text-blue-400", worst: "text-red-400", bar: "bg-blue-500", border: "border-blue-500/40" },
                              { best: "text-purple-400", worst: "text-red-400", bar: "bg-purple-500", border: "border-purple-500/40" },
                              { best: "text-orange-400", worst: "text-red-400", bar: "bg-orange-500", border: "border-orange-500/40" },
                            ];
                            const color = colorClasses[idx % colorClasses.length];

                            return (
                              <td key={player.id} className={`px-6 py-4 text-center border-l-2 ${color.border} bg-slate-950/20`}>
                                <div className="flex flex-col items-center gap-2">
                                  <span className={`text-center font-bold text-lg transition-all ${
                                    isBest 
                                      ? color.best
                                      : isWorst 
                                      ? color.worst 
                                      : "text-slate-200"
                                  }`}>
                                    {typeof value === "number" ? format(value) : value}
                                  </span>
                                  {hasVariation && (
                                    <div className="w-full max-w-[100px] h-2 overflow-hidden rounded-full bg-slate-900 border border-slate-800">
                                      <div
                                        className={`h-full transition-all duration-500 ${color.bar} shadow-lg ${
                                          isBest ? 'shadow-emerald-500/30' : ''
                                        }`}
                                        style={{ width: `${Math.max(8, percentage)}%` }}
                                      />
                                    </div>
                                  )}
                                </div>
                              </td>
                            );
                          })}
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          </>
        )}

        {/* Show message only if we have selected players but NO stats at all */}
        {!loading && selectedPlayers.length >= 1 && playerStats.length === 0 && (
          <div className="rounded-xl border border-yellow-500/30 bg-yellow-500/10 p-8 text-center">
            <p className="text-yellow-400 mb-2">⏳ Loading comparison data...</p>
            <p className="text-[11px] text-yellow-300/80">
              Fetching statistics for {selectedPlayers.length} player{selectedPlayers.length > 1 ? "s" : ""}...
            </p>
          </div>
        )}
      </div>
    </>
  );
}

"use client";

import Link from "next/link";
import { useState, FormEvent, useEffect, useMemo, useRef } from "react";
import { useRouter } from "next/navigation";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { playerSchema, type PlayerFormData } from "@/lib/validations";
import toast, { Toaster } from "react-hot-toast";
import { ExportModal } from "@/app/components/ExportModal";
import { useTranslation } from "@/lib/i18n";

type Player = {
  id: number;
  slug: string;
  name: string;
  position: string;
  age: number | null;
  club: string | null;
  number: number | null;
  xg: number | null;
  shotsPer90: number | null;
  team: { id: number; name: string } | null;
  matchesCount?: number;
  totalGameTime?: number;
};

type Team = {
  id: number;
  name: string;
};

export default function PlayersPage() {
  const { t } = useTranslation();
  const router = useRouter();
  const [showAddPlayer, setShowAddPlayer] = useState(false);
  const [editingPlayer, setEditingPlayer] = useState<Player | null>(null);
  const [players, setPlayers] = useState<Player[]>([]);
  const [teams, setTeams] = useState<Team[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [openActionsMenu, setOpenActionsMenu] = useState<number | null>(null);
  const [menuPosition, setMenuPosition] = useState<{ top: number; right: number } | null>(null);
  const buttonRefs = useRef<{ [key: number]: HTMLButtonElement | null }>({});
  const [selectedPlayers, setSelectedPlayers] = useState<number[]>([]);
  /** Έγινε restore από localStorage· τρέχει ένα validate προς το compare API. */
  const compareHydrationPendingRef = useRef(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [filterTeamId, setFilterTeamId] = useState<string>("");
  const [filterPosition, setFilterPosition] = useState<string>("");
  const [showExportModal, setShowExportModal] = useState(false);
  const [watchlistIds, setWatchlistIds] = useState<number[]>([]);

  // Pagination state (like Instat/Wyscout)
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [totalPlayers, setTotalPlayers] = useState(0);

  // Debounce server search so we don't hit the API on every keystroke and
  // avoid the full table flash that looks like a page refresh.
  useEffect(() => {
    const handle = window.setTimeout(() => {
      setDebouncedSearch(searchQuery);
    }, 300);
    return () => window.clearTimeout(handle);
  }, [searchQuery]);

  // Combined client-side filtering: search + team + position.
  const filteredPlayers = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();
    const teamIdNum = filterTeamId ? Number(filterTeamId) : null;

    return players.filter((player) => {
      if (teamIdNum && player.team?.id !== teamIdNum) return false;
      if (filterPosition && player.position !== filterPosition) return false;

      if (query) {
        const nameMatch = player.name?.toLowerCase().includes(query);
        const idMatch = player.id?.toString().includes(query);
        const positionMatch = player.position?.toLowerCase().includes(query);
        const teamMatch = player.team?.name?.toLowerCase().includes(query);
        const clubMatch = player.club?.toLowerCase().includes(query);
        if (!(nameMatch || idMatch || positionMatch || teamMatch || clubMatch)) {
          return false;
        }
      }

      return true;
    });
  }, [searchQuery, players, filterTeamId, filterPosition]);

  const hasActiveFilters = useMemo(
    () => Boolean(filterTeamId || filterPosition),
    [filterTeamId, filterPosition]
  );

  // Distinct positions present in the currently loaded players list.
  const availablePositions = useMemo(() => {
    const set = new Set<string>();
    for (const p of players) {
      if (p.position) set.add(p.position);
    }
    return Array.from(set).sort();
  }, [players]);

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
    reset,
    setValue,
  } = useForm<PlayerFormData>({
    resolver: zodResolver(playerSchema),
    defaultValues: {
      name: "",
      position: "",
      age: "",
      club: "",
      nationality: "",
      foot: "Right",
      teamId: "",
      number: "",
    },
  });

  // Fetch players with pagination (like Instat/Wyscout)
  const fetchPlayers = async (pageNum: number = 1, append: boolean = false) => {
    try {
      if (!append) {
        // Only show full-screen skeleton on first load, not on every search refetch.
        if (players.length === 0) {
          setLoading(true);
        }
      } else {
        setLoadingMore(true);
      }

      const effectiveSearch = debouncedSearch.trim();
      const searchParam = effectiveSearch ? `&search=${encodeURIComponent(effectiveSearch)}` : "";
      const playersUrl = `/api/players?page=${pageNum}&limit=50&t=${Date.now()}${searchParam}`;

      const playersRes = await fetch(playersUrl);

      if (playersRes.ok) {
        const playersData = await playersRes.json();

        if (playersData.ok && Array.isArray(playersData.players)) {
          const playersWithIds = playersData.players.map((p: any, index: number) => ({
            ...p,
            id: p.id || index + 1,
            matchesCount: p.matchesCount ?? 0,
            totalGameTime: p.totalGameTime ?? 0,
            // Keep original slug from DB, don't create fallback (we'll use id in links if slug is missing)
            slug: p.slug || null,
            name: p.name || "Unknown",
            position: p.position || "N/A",
          }));

          if (append) {
            setPlayers((prev) => {
              const existingMap = new Map(prev.map((p) => [p.id, p]));
              playersWithIds.forEach((p: any) => {
                existingMap.set(p.id, p);
              });
              return Array.from(existingMap.values()).sort((a, b) => b.id - a.id);
            });
          } else if (effectiveSearch) {
            // Fresh search results: replace the list so stale entries from a
            // previous query don't linger. Client-side useMemo still applies
            // the additional team/position filters.
            setPlayers(playersWithIds.sort((a: Player, b: Player) => b.id - a.id));
          } else {
            // Initial / unfiltered refetch: merge so we never drop locally
            // optimistic players (added via inline create).
            setPlayers((prev) => {
              const existingMap = new Map(prev.map((p) => [p.id, p]));
              playersWithIds.forEach((p: any) => {
                existingMap.set(p.id, p);
              });
              const merged = Array.from(existingMap.values()).sort((a, b) => b.id - a.id);

              if (prev.length > 0 && merged.length < prev.length) {
                prev.forEach((prevPlayer) => {
                  if (!merged.some((m) => m.id === prevPlayer.id)) {
                    merged.push(prevPlayer);
                  }
                });
                merged.sort((a, b) => b.id - a.id);
              }

              return merged;
            });
          }

          // Update pagination state
          if (playersData.pagination) {
            setHasMore(playersData.pagination.hasMore);
            setTotalPlayers(playersData.pagination.total);
            setPage(pageNum);
          }
        } else {
          console.error("[fetchPlayers] Invalid response format:", playersData);
          toast.error("Failed to load players: Invalid response format");
        }
      } else {
        const errorText = await playersRes.text();
        console.error("[fetchPlayers] Failed:", playersRes.status, errorText);
        toast.error(`Failed to load players: ${playersRes.status}`);
      }
    } catch (err) {
      console.error("[fetchPlayers] Error:", err);
        toast.error(t("loadingPlayers"));
    } finally {
      setLoading(false);
      setLoadingMore(false);
    }
  };

  // Track if this is the initial mount
  const [isInitialMount, setIsInitialMount] = useState(true);

  // Check authentication first
  useEffect(() => {
    async function checkAuth() {
      try {
        const userRes = await fetch("/api/account/me");
        if (!userRes.ok) {
          router.push("/auth/login");
          return;
        }
        const userData = await userRes.json();
        if (!userData.ok) {
          router.push("/auth/login");
          return;
        }
      } catch {
        router.push("/auth/login");
      }
    }
    checkAuth();
  }, [router]);

  // Initial load and when (debounced) search changes.
  // We deliberately keep the existing list while re-fetching so the table
  // does not flash empty (which looked like a full page refresh).
  useEffect(() => {
    if (isInitialMount) {
      setIsInitialMount(false);
    }
    setPage(1);
    fetchPlayers(1, false);
  }, [debouncedSearch]); // Re-fetch only after debounce

  // Load teams once
  useEffect(() => {
    fetch("/api/teams")
      .then((res) => res.json())
      .then((data) => {
        if (data.ok && data.teams) {
          setTeams(data.teams);
        }
      })
      .catch(() => {
        console.error("Failed to load teams");
      });
  }, []);

  // Load watchlist once
  useEffect(() => {
    fetch("/api/watchlist")
      .then((res) => res.json())
      .then((data) => {
        if (data.ok && Array.isArray(data.players)) {
          setWatchlistIds(data.players.map((p: any) => p.id));
        }
      })
      .catch(() => {
        console.error("Failed to load watchlist");
      });
  }, []);

  // Load selected players from localStorage on mount (for persistence across reloads)
  useEffect(() => {
    try {
      const stored = localStorage.getItem("playerComparisonIds");
      if (stored) {
        const parsedIds = JSON.parse(stored);
        if (Array.isArray(parsedIds) && parsedIds.length >= 1 && parsedIds.length <= 4) {
          const validIds = parsedIds.map(id => parseInt(String(id))).filter(id => !isNaN(id) && id > 0);
          if (validIds.length > 0) {
            compareHydrationPendingRef.current = true;
            setSelectedPlayers(validIds);
          }
        }
      }
    } catch (e) {
      console.warn("[PlayersPage] Failed to load selected players from localStorage:", e);
    }
  }, []);

  // Μετά το localStorage: κράτα μόνο παίκτες που επιστρέφει το compare API (δικές σου ομάδες).
  useEffect(() => {
    if (!compareHydrationPendingRef.current) return;
    if (selectedPlayers.length < 1) return;

    compareHydrationPendingRef.current = false;
    let cancelled = false;
    const snapshot = [...selectedPlayers];

    (async () => {
      try {
        const res = await fetch("/api/players/compare", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ playerIds: snapshot }),
          credentials: "include",
        });
        const data = await res.json().catch(() => ({}));
        if (cancelled || !res.ok || !Array.isArray(data.players)) return;

        const allowed = new Set(data.players.map((p: { id: number }) => Number(p.id)));
        const next = snapshot.filter((id) => allowed.has(Number(id)));
        if (next.length === snapshot.length) return;

        if (next.length >= 1) {
          localStorage.setItem("playerComparisonIds", JSON.stringify(next));
          setSelectedPlayers(next);
        } else {
          localStorage.removeItem("playerComparisonIds");
          setSelectedPlayers([]);
        }
      } catch {
        compareHydrationPendingRef.current = false;
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [selectedPlayers]);

  // Infinite scroll handler (like Instat/Wyscout)
  useEffect(() => {
    const handleScroll = () => {
      if (loadingMore || !hasMore || loading) return;

      const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
      const windowHeight = window.innerHeight;
      const documentHeight = document.documentElement.scrollHeight;

      // Load more when user is 200px from bottom
      if (scrollTop + windowHeight >= documentHeight - 200) {
        fetchPlayers(page + 1, true);
      }
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, [page, hasMore, loadingMore, loading, searchQuery]);

  // Filter is now handled by useMemo above

  async function handleAddPlayer(data: PlayerFormData) {
    try {
      const isEditing = editingPlayer !== null;
      const url = isEditing ? `/api/players/${editingPlayer.slug}` : "/api/players";
      const method = isEditing ? "PATCH" : "POST";

      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: data.name,
          position: data.position,
          age: data.age ? parseInt(data.age) : undefined,
          club: data.club || undefined,
          nationality: data.nationality || undefined,
          foot: data.foot || "Right",
          teamId: data.teamId ? parseInt(data.teamId) : undefined,
          number: data.number ? parseInt(data.number) : undefined,
        }),
      });

      const result = await res.json();
      if (!res.ok || !result.ok) {
        toast.error(result.message || (isEditing ? t("failedToUpdatePlayer") : t("failedToAddPlayer")));
        return;
      }

      toast.success(isEditing ? t("playerUpdatedSuccessfully") : t("playerAddedSuccessfully"));
      setShowAddPlayer(false);
      setEditingPlayer(null);
      reset();

      if (isEditing) {
        // Update existing player in list
        setPlayers((prev) =>
          prev.map((p) =>
            p.id === result.player?.id
              ? {
                  ...result.player,
                  id: result.player.id,
                  matchesCount: result.player.matchesCount ?? 0,
                  totalGameTime: result.player.totalGameTime ?? 0,
                  slug: result.player.slug || `player-${result.player.id}`,
                  name: result.player.name || "Unknown",
                  position: result.player.position || "N/A",
                }
              : p
          )
        );
      } else {
        // Add new player at the beginning (newest first, like Instat/Wyscout)
        if (result.player) {
          const newPlayer: Player = {
            ...result.player,
            id: result.player.id,
            matchesCount: result.player.matchesCount ?? 0,
            totalGameTime: result.player.totalGameTime ?? 0,
            slug: result.player.slug || `player-${result.player.id}`,
            name: result.player.name || "Unknown",
            position: result.player.position || "N/A",
          };

          // Add player to list IMMEDIATELY and ensure it stays
          setPlayers((prev) => {
            const existingMap = new Map(prev.map((p) => [p.id, p]));
            existingMap.set(newPlayer.id, newPlayer);
            return Array.from(existingMap.values()).sort((a, b) => b.id - a.id);
          });

          // Update total count
          setTotalPlayers((prev) => prev + 1);

          // DON'T refresh immediately - it might cause race conditions
          // The player is already added locally and will be included in next natural refresh
          // Only refresh if user explicitly searches or navigates

          // Scroll to top to show new player
          window.scrollTo({ top: 0, behavior: "smooth" });

          // Highlight the new player
          setTimeout(() => {
            const row = document.querySelector(`[data-player-id="${newPlayer.id}"]`);
            if (row) {
              row.scrollIntoView({ behavior: "smooth", block: "center" });
              row.classList.add("bg-emerald-500/20", "border-emerald-500/50");
              setTimeout(() => {
                row.classList.remove("bg-emerald-500/20", "border-emerald-500/50");
              }, 3000);
            }
          }, 800);
        }
      }
    } catch (err) {
      toast.error("Network error. Please try again.");
    }
  }

  function handlePlayerSelect(playerId: number) {
    let newSelected: number[];
    if (selectedPlayers.includes(playerId)) {
      newSelected = selectedPlayers.filter((id) => id !== playerId);
    } else {
      if (selectedPlayers.length < 4) {
        newSelected = [...selectedPlayers, playerId];
      } else {
        toast.error("Maximum 4 players can be compared");
        return;
      }
    }

    setSelectedPlayers(newSelected);

    // Save to localStorage for persistence
    try {
      if (newSelected.length > 0) {
        localStorage.setItem("playerComparisonIds", JSON.stringify(newSelected));
      } else {
        localStorage.removeItem("playerComparisonIds");
      }
    } catch (e) {
      console.warn("[PlayersPage] Failed to save to localStorage:", e);
    }
  }

  function handleSelectAll() {
    let newSelected: number[];
    if (selectedPlayers.length === filteredPlayers.length && filteredPlayers.length > 0) {
      newSelected = [];
    } else {
      newSelected = filteredPlayers.slice(0, 4).map((p) => p.id);
    }

    setSelectedPlayers(newSelected);

    try {
      if (newSelected.length > 0) {
        localStorage.setItem("playerComparisonIds", JSON.stringify(newSelected));
      } else {
        localStorage.removeItem("playerComparisonIds");
      }
    } catch (e) {
      console.warn("[PlayersPage] Failed to save to localStorage:", e);
    }
  }

  async   function handleCompare() {
    if (selectedPlayers.length < 2) {
      toast.error(t("selectAtLeast2Players"));
      return;
    }

    // Save to localStorage before navigating (for persistence across reloads)
    try {
      localStorage.setItem("playerComparisonIds", JSON.stringify(selectedPlayers));
    } catch (e) {
      console.warn("[PlayersPage] Failed to save to localStorage:", e);
    }

    const idsParam = selectedPlayers.join(",");
    router.push(`/players/compare?ids=${idsParam}`);
  }

  async function handleToggleWatchlist(playerId: number) {
    try {
      const isInWatchlist = watchlistIds.includes(playerId);

      if (isInWatchlist) {
        // Remove from watchlist
        const res = await fetch(`/api/watchlist?playerId=${playerId}`, {
          method: "DELETE",
        });
        if (res.ok) {
          setWatchlistIds(watchlistIds.filter((id) => id !== playerId));
          toast.success(t("removedFromWatchlist"));
        } else {
          toast.error(t("failedToRemoveFromWatchlist"));
        }
      } else {
        // Add to watchlist
        const res = await fetch("/api/watchlist", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ playerId }),
        });
        if (res.ok) {
          setWatchlistIds([...watchlistIds, playerId]);
          toast.success(t("addedToWatchlist"));
        } else {
          const data = await res.json();
          toast.error(data.message || t("failedToAddToWatchlist"));
        }
      }
    } catch (err) {
      toast.error(t("networkError"));
    }
  }

  if (loading) {
    return (
      <div className="space-y-5 text-xs text-slate-700 dark:text-slate-200">
        <p className="text-slate-600 dark:text-slate-400">{t("loadingPlayers")}</p>
      </div>
    );
  }

  return (
    <>
      <Toaster position="top-right" />
      <div className="min-h-screen bg-white dark:bg-slate-950">
        {/* Professional Header */}
        <header className="border-b border-slate-200 dark:border-slate-900/50 bg-white/80 dark:bg-slate-950/80 backdrop-blur-sm">
          <div className="mx-auto max-w-7xl px-6 py-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="flex h-12 w-12 items-center justify-center rounded-full bg-purple-500/20 border border-purple-500/30">
                  <svg className="h-6 w-6 text-purple-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" />
                  </svg>
                </div>
                <div>
                  <h1 className="text-3xl font-bold tracking-tight text-slate-900 dark:text-white mb-1">{t("players")}</h1>
                  <p className="text-sm text-slate-600 dark:text-slate-400">{t("playersDescription")}</p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <button
                  onClick={() => setShowExportModal(true)}
                  className="flex items-center gap-2 rounded-lg border border-slate-300 dark:border-slate-700 bg-slate-100 dark:bg-slate-800/50 px-5 py-3 text-sm font-semibold text-slate-700 dark:text-slate-200 transition-all hover:bg-slate-200 dark:hover:bg-slate-800 hover:border-slate-400 dark:hover:border-slate-600"
                >
                  <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                  </svg>
                  {t("export")}
                </button>
                {selectedPlayers.length >= 2 && (
                  <button
                    onClick={handleCompare}
                    className="flex items-center gap-2 rounded-lg bg-emerald-600 px-5 py-3 text-sm font-semibold text-white shadow-lg shadow-emerald-500/20 transition-all hover:bg-emerald-500 hover:scale-105"
                  >
                    <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                    </svg>
                    {t("playerComparison")} ({selectedPlayers.length})
                  </button>
                )}
                <button
                  onClick={() => setShowAddPlayer(true)}
                  className="flex items-center gap-2 rounded-lg bg-amber-500 px-6 py-3 text-sm font-semibold text-slate-950 shadow-lg shadow-amber-500/20 transition-all hover:bg-amber-400 hover:scale-105"
                >
                  <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                  </svg>
                  {t("addNewPlayer")}
                </button>
              </div>
            </div>
          </div>
        </header>

        {/* Main Content */}
        <main className="mx-auto max-w-7xl px-4 md:px-6 py-6 md:py-8">
          {/* Filters Panel */}
          <div className="mb-4 md:mb-6 rounded-xl border border-slate-200/80 dark:border-slate-800/50 bg-gradient-to-br from-white dark:from-slate-900/50 via-slate-50/50 dark:via-slate-950/50 to-white dark:to-slate-950/50 p-4 md:p-6 shadow-lg">
            <div className="mb-4">
              <h2 className="text-sm font-semibold text-white mb-1">{t("filters")}</h2>
              <p className="text-xs text-slate-400">{t("filterPlayersBy")}</p>
            </div>
            <div className="flex flex-wrap items-end gap-3 md:gap-4">
              <div className="space-y-2">
                <label className="block text-xs font-semibold uppercase tracking-wide text-slate-400">{t("seasons")}</label>
                <div className="relative">
                  <select className="h-12 min-h-[44px] w-full sm:w-32 appearance-none rounded-lg border border-slate-200/80 dark:border-slate-800 bg-white dark:bg-slate-900/50 px-4 pr-10 text-sm font-medium text-slate-900 dark:text-white outline-none transition-all focus:border-emerald-500 dark:focus:border-emerald-500 focus:bg-white dark:focus:bg-slate-900 focus:ring-2 focus:ring-emerald-500/20 hover:border-slate-300 dark:hover:border-slate-700">
                    <option className="bg-slate-900 text-white">{t("all")}</option>
                  </select>
                  <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center pr-4">
                    <svg className="h-5 w-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                    </svg>
                  </div>
                </div>
              </div>
              <div className="space-y-2">
                <label className="block text-xs font-semibold uppercase tracking-wide text-slate-400">{t("myTeams")}</label>
                <div className="relative">
                  <select
                    value={filterTeamId}
                    onChange={(e) => setFilterTeamId(e.target.value)}
                    className="h-12 w-48 appearance-none rounded-lg border border-slate-800 bg-slate-900/50 px-4 pr-10 text-sm font-medium text-white outline-none transition-all focus:border-emerald-500 focus:bg-slate-900 focus:ring-2 focus:ring-emerald-500/20 hover:border-slate-700"
                  >
                    <option value="" className="bg-slate-900 text-white">{t("all")}</option>
                    {teams.map((team) => (
