                </div>
              </div>
              <button
                type="submit"
                disabled={isSubmitting}
                className="mt-2 h-8 w-full rounded-md bg-emerald-500 text-[11px] font-semibold text-slate-950 shadow-sm transition hover:bg-emerald-400 disabled:cursor-not-allowed disabled:opacity-60"
              >
                {isSubmitting ? (editingPlayer ? "Updating..." : "Adding...") : (editingPlayer ? "Update player" : "Add player")}
              </button>
            </form>
          </div>
        </div>
      )}

        <ExportModal
          isOpen={showExportModal}
          onClose={() => setShowExportModal(false)}
          onExportSuccess={() => {
            toast.success("Export completed!");
          }}
        />
      </div>
    </>
  );
}

"use client";

import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { useEffect, useMemo, useState } from "react";
import { useTranslation } from "@/lib/i18n";
import toast, { Toaster } from "react-hot-toast";

type PlaylistClip = {
  id: number;
  title: string;
  startSec: number;
  endSec: number;
  position: number;
  match: {
    slug: string;
    date: string;
    homeTeam: { name: string } | null;
    awayTeam: { name: string } | null;
    homeTeamName: string | null;
    awayTeamName: string | null;
  };
  matchEvent: {
    id: number;
    type: string;
    minute: number | null;
    x: number | null;
    y: number | null;
  } | null;
};

type PlaylistPayload = {
  id: number;
  name: string;
  description: string | null;
  updatedAt: string;
  match: {
    slug: string;
    date: string;
    homeTeam: { name: string } | null;
    awayTeam: { name: string } | null;
    homeTeamName: string | null;
    awayTeamName: string | null;
  } | null;
  clips: PlaylistClip[];
  _count: { clips: number };
};

function formatSeconds(total: number): string {
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
}

export default function PlaylistDetailPage() {
  const { t } = useTranslation();
  const router = useRouter();
  const params = useParams<{ id: string }>();
  const playlistId = params?.id;

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [removingClipId, setRemovingClipId] = useState<number | null>(null);
  const [downloadingClipId, setDownloadingClipId] = useState<number | null>(null);
  const [bulkDownloading, setBulkDownloading] = useState(false);
  const [bulkProgress, setBulkProgress] = useState<{ done: number; total: number } | null>(null);
  const [selectedClipIds, setSelectedClipIds] = useState<Set<number>>(new Set());
  const [playlist, setPlaylist] = useState<PlaylistPayload | null>(null);
  const [editName, setEditName] = useState("");
  const [editDescription, setEditDescription] = useState("");

  const matchLabel = useMemo(() => {
    if (!playlist?.match) return null;
    const home = playlist.match.homeTeam?.name || playlist.match.homeTeamName || "Home";
    const away = playlist.match.awayTeam?.name || playlist.match.awayTeamName || "Away";
    return `${home} vs ${away}`;
  }, [playlist]);

  async function loadPlaylist() {
    if (!playlistId) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/playlists/${playlistId}`);
      const data = await res.json().catch(() => null);
      if (!res.ok || !data?.ok || !data.playlist) {
        toast.error(data?.message || "Playlist not found.");
        router.replace("/playlist");
        return;
      }
      setPlaylist(data.playlist);
      setEditName(data.playlist.name ?? "");
      setEditDescription(data.playlist.description ?? "");
    } catch {
      toast.error("Failed to load playlist.");
      router.replace("/playlist");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    void loadPlaylist();
  }, [playlistId]);

  useEffect(() => {
    if (!playlist) {
      setSelectedClipIds(new Set());
      return;
    }
    const allowedIds = new Set(playlist.clips.map((clip) => clip.id));
    setSelectedClipIds((prev) => {
      const next = new Set([...prev].filter((id) => allowedIds.has(id)));
      return next.size === prev.size ? prev : next;
    });
  }, [playlist]);

  async function saveMeta() {
    if (!playlistId) return;
    setSaving(true);
    try {
      const res = await fetch(`/api/playlists/${playlistId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: editName.trim(),
          description: editDescription.trim() || null,
        }),
      });
      const data = await res.json().catch(() => null);
      if (!res.ok || !data?.ok) {
        toast.error(data?.message || "Could not update playlist.");
        return;
      }
      toast.success(t("saved") || "Saved");
      await loadPlaylist();
    } catch {
      toast.error(t("anErrorOccurred") || "An error occurred");
    } finally {
      setSaving(false);
    }
  }

  async function deletePlaylist() {
    if (!playlistId) return;
    if (!confirm(t("deletePlaylistConfirm") || "Delete this playlist?")) return;
    setDeleting(true);
    try {
      const res = await fetch(`/api/playlists/${playlistId}`, { method: "DELETE" });
      const data = await res.json().catch(() => null);
      if (!res.ok || !data?.ok) {
        toast.error(data?.message || "Could not delete playlist.");
        return;
      }
      toast.success(t("playlistDeleted") || "Playlist deleted");
      router.replace("/playlist");
    } catch {
      toast.error(t("anErrorOccurred") || "An error occurred");
    } finally {
      setDeleting(false);
    }
  }

  async function removeClip(clipId: number) {
    if (!playlistId) return;
    if (!confirm(t("removeClipConfirm") || "Remove this clip?")) return;
    setRemovingClipId(clipId);
    try {
      const res = await fetch(`/api/playlists/${playlistId}/clips?clipId=${clipId}`, { method: "DELETE" });
      const data = await res.json().catch(() => null);
      if (!res.ok || !data?.ok) {
        toast.error(data?.message || "Could not remove clip.");
        return;
      }
      await loadPlaylist();
    } catch {
      toast.error(t("anErrorOccurred") || "An error occurred");
    } finally {
      setRemovingClipId(null);
    }
  }

  async function downloadClip(clipId: number) {
    if (!playlistId) return;
    setDownloadingClipId(clipId);
    try {
      const payload = await getClipDownloadPayload(clipId, true);
      if (!payload) return;
      triggerBrowserDownload(payload.blob, payload.filename);
    } catch {
      toast.error(t("anErrorOccurred") || "An error occurred");
    } finally {
      setDownloadingClipId(null);
    }
  }

  function toggleClipSelection(clipId: number) {
    setSelectedClipIds((prev) => {
      const next = new Set(prev);
      if (next.has(clipId)) {
        next.delete(clipId);
      } else {
        next.add(clipId);
      }
      return next;
    });
  }

  function toggleSelectAllClips() {
    if (!playlist) return;
    setSelectedClipIds((prev) => {
      if (prev.size === playlist.clips.length) {
        return new Set();
      }
      return new Set(playlist.clips.map((clip) => clip.id));
    });
  }

  async function getClipDownloadPayload(clipId: number, showErrorToast: boolean) {
    if (!playlistId) return null;
    const res = await fetch(`/api/playlists/${playlistId}/clips/${clipId}/download`, {
      method: "GET",
    });

    if (!res.ok) {
      if (showErrorToast) {
        const errorData = await res.json().catch(() => null);
        toast.error(errorData?.message || "Could not download clip.");
      }
      return null;
    }

    const blob = await res.blob();
    const contentDisposition = res.headers.get("Content-Disposition") || "";
    const filenameMatch = contentDisposition.match(/filename="?([^"]+)"?/i);
    const filename = filenameMatch?.[1] || `playlist-clip-${clipId}.mp4`;
    return { blob, filename };
  }

  function triggerBrowserDownload(blob: Blob, filename: string) {
    const blobUrl = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = blobUrl;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(blobUrl);
  }

  async function downloadMany(clipIds: number[], mode: "selected" | "all") {
    if (!playlist) return;
    if (clipIds.length === 0) {
      toast.error(t("selectAtLeastOneClip") || "Select at least one clip.");
      return;
    }

    setBulkDownloading(true);
    setBulkProgress({ done: 0, total: clipIds.length });
    let okCount = 0;
    let failCount = 0;

    try {
      for (let index = 0; index < clipIds.length; index += 1) {
        const clipId = clipIds[index];
        const payload = await getClipDownloadPayload(clipId, false);
        if (payload) {
          triggerBrowserDownload(payload.blob, payload.filename);
          okCount += 1;
        } else {
          failCount += 1;
        }
        setBulkProgress({ done: index + 1, total: clipIds.length });
      }

      if (failCount === 0) {
        toast.success(
          mode === "all"
            ? t("downloadedAllClips") || "Downloaded all clips."
            : t("downloadedSelectedClips") || "Downloaded selected clips."
        );
      } else {
        toast.error(
          `${t("downloadCompletedWithFailures") || "Download completed with failures."} (${okCount}/${clipIds.length})`
        );
      }
    } catch {
      toast.error(t("anErrorOccurred") || "An error occurred");
    } finally {
      setBulkDownloading(false);
      setBulkProgress(null);
    }
  }

  if (loading) {
    return (
      <div className="space-y-4 p-6 text-xs text-slate-200">
        <p className="text-slate-400">{t("loading")}</p>
      </div>
    );
  }

  if (!playlist) return null;

  const selectedCount = selectedClipIds.size;
  const allSelected = playlist.clips.length > 0 && selectedCount === playlist.clips.length;
  const isDownloading = bulkDownloading || downloadingClipId !== null;

  return (
    <>
      <Toaster position="top-right" />
      <div className="mx-auto max-w-5xl space-y-6 p-6 text-xs text-slate-200">
        <div className="flex items-center justify-between gap-4">
          <div className="space-y-2">
            <Link href="/playlist" className="text-slate-400 hover:text-slate-200">
              ← {t("back") || "Back"}
            </Link>
            <h1 className="text-2xl font-semibold text-white">{playlist.name}</h1>
            {matchLabel && (
              <p className="text-[11px] text-slate-400">
                {matchLabel}
                {playlist.match?.date ? ` · ${new Date(playlist.match.date).toLocaleDateString("en-GB")}` : ""}
              </p>
            )}
          </div>
          <button
            onClick={deletePlaylist}
            disabled={deleting}
            className="rounded-lg border border-red-500/40 bg-red-500/10 px-3 py-2 text-[11px] font-semibold text-red-200 hover:bg-red-500/20 disabled:cursor-not-allowed disabled:opacity-60"
          >
            {deleting ? t("deleting") || "Deleting..." : t("deletePlaylist") || "Delete playlist"}
          </button>
        </div>

        <section className="space-y-3 rounded-xl border border-slate-800 bg-slate-950/70 p-4">
          <h2 className="text-sm font-semibold text-slate-100">{t("playlistDetails") || "Playlist details"}</h2>
          <div className="grid gap-3 md:grid-cols-2">
            <div className="space-y-1.5">
              <label className="text-[11px] text-slate-400">{t("name") || "Name"}</label>
              <input
                value={editName}
                onChange={(e) => setEditName(e.target.value)}
                className="h-9 w-full rounded-md border border-slate-800 bg-slate-900 px-3 text-[12px] text-slate-100 outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500/60"
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-[11px] text-slate-400">{t("description") || "Description"}</label>
              <input
                value={editDescription}
                onChange={(e) => setEditDescription(e.target.value)}
                className="h-9 w-full rounded-md border border-slate-800 bg-slate-900 px-3 text-[12px] text-slate-100 outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500/60"
              />
            </div>
          </div>
          <button
            onClick={saveMeta}
            disabled={saving}
            className="rounded-md bg-emerald-500 px-3 py-2 text-[11px] font-semibold text-slate-950 hover:bg-emerald-400 disabled:cursor-not-allowed disabled:opacity-60"
          >
            {saving ? t("saving") || "Saving..." : t("saveChanges") || "Save changes"}
          </button>
        </section>

        <section className="space-y-3 rounded-xl border border-slate-800 bg-slate-950/70 p-4">
          <h2 className="text-sm font-semibold text-slate-100">
            {(t("clips") || "Clips")} ({playlist._count.clips})
          </h2>
          {playlist.clips.length === 0 ? (
            <p className="rounded-md border border-dashed border-slate-700 px-3 py-4 text-[11px] text-slate-400">
              {t("noClipsInPlaylistYet") || "No clips in this playlist yet. Add clips from the match page in a next step."}
            </p>
          ) : (
            <div className="space-y-2">
              <div className="flex flex-wrap items-center justify-between gap-2 rounded-md border border-slate-800 bg-slate-900/50 px-3 py-2">
                <label className="flex items-center gap-2 text-[11px] text-slate-300">
                  <input
                    type="checkbox"
                    checked={allSelected}
                    onChange={toggleSelectAllClips}
                    disabled={isDownloading}
                    className="h-3.5 w-3.5 min-h-0 min-w-0 shrink-0 rounded border-slate-600 bg-slate-900 accent-emerald-500"
                  />
                  {t("selectAllClips") || "Select all clips"}
                </label>
                <div className="flex items-center gap-2">
                  <span className="text-[11px] text-slate-400">
                    {selectedCount} {t("selected") || "selected"}
                  </span>
                  <button
                    onClick={() => downloadMany([...selectedClipIds], "selected")}
                    disabled={isDownloading || selectedCount === 0}
                    className="rounded-md border border-blue-500/40 bg-blue-500/10 px-3 py-1.5 text-[11px] font-semibold text-blue-200 hover:bg-blue-500/20 disabled:cursor-not-allowed disabled:opacity-60"
                  >
                    {bulkDownloading && bulkProgress
                      ? `${t("downloading") || "Downloading..."} ${bulkProgress.done}/${bulkProgress.total}`
                      : t("downloadSelectedClips") || "Download selected"}
                  </button>
                  <button
                    onClick={() => downloadMany(playlist.clips.map((clip) => clip.id), "all")}
                    disabled={isDownloading || playlist.clips.length === 0}
                    className="rounded-md border border-indigo-500/40 bg-indigo-500/10 px-3 py-1.5 text-[11px] font-semibold text-indigo-200 hover:bg-indigo-500/20 disabled:cursor-not-allowed disabled:opacity-60"
                  >
                    {t("downloadAllClips") || "Download all"}
                  </button>
                </div>
              </div>
              {playlist.clips.map((clip) => (
                <div
                  key={clip.id}
                  className="flex flex-col gap-3 rounded-lg border border-slate-800 bg-slate-900/50 p-3 md:flex-row md:items-center md:justify-between"
                >
                  <div className="flex items-start gap-3">
                    <input
                      type="checkbox"
                      checked={selectedClipIds.has(clip.id)}
                      onChange={() => toggleClipSelection(clip.id)}
                      disabled={isDownloading}
                      className="mt-1 h-3.5 w-3.5 min-h-0 min-w-0 shrink-0 rounded border-slate-600 bg-slate-900 accent-emerald-500"
                    />
                    <div className="space-y-1">
                    <p className="text-sm font-medium text-slate-100">{clip.title}</p>
                    <p className="text-[11px] text-slate-400">
                      {formatSeconds(clip.startSec)} - {formatSeconds(clip.endSec)}
                      {clip.matchEvent
                        ? ` · ${clip.matchEvent.type}${clip.matchEvent.minute != null ? ` (${clip.matchEvent.minute}')` : ""}`
                        : ""}
                    </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <Link
                      href={`/matches/${clip.match.slug}?t=${clip.startSec}`}
                      className="rounded-md border border-emerald-500/40 bg-emerald-500/10 px-3 py-1.5 text-[11px] font-semibold text-emerald-300 hover:bg-emerald-500/20"
                    >
                      {t("watchInMatch") || "Watch in match"}
                    </Link>
                    <button
                      onClick={() => downloadClip(clip.id)}
                      disabled={isDownloading}
                      className="rounded-md border border-blue-500/40 bg-blue-500/10 px-3 py-1.5 text-[11px] font-semibold text-blue-200 hover:bg-blue-500/20"
                    >
                      {downloadingClipId === clip.id
                        ? t("downloading") || "Downloading..."
                        : t("downloadClip") || "Download clip"}
                    </button>
                    <button
                      onClick={() => removeClip(clip.id)}
                      disabled={removingClipId === clip.id}
                      className="rounded-md border border-red-500/40 bg-red-500/10 px-3 py-1.5 text-[11px] font-semibold text-red-200 hover:bg-red-500/20 disabled:cursor-not-allowed disabled:opacity-60"
                    >
                      {removingClipId === clip.id ? t("removing") || "Removing..." : t("remove") || "Remove"}
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { useTranslation } from "@/lib/i18n";

type Match = {
  id: number;
  slug: string;
  competition: string;
  date: string;
  homeTeam: { name: string } | null;
  awayTeam: { name: string } | null;
  homeTeamName?: string | null;
  awayTeamName?: string | null;
};

type Analytics = {
  xg: { home: number; away: number };
  possession: { home: number; away: number };
  shots: {
    home: { total: number; onTarget: number; goals: number };
    away: { total: number; onTarget: number; goals: number };
  };
  ppda: { home: number; away: number };
  highRegains: { home: number; away: number };
  progressivePasses: { home: number; away: number };
  xa: { home: number; away: number };
  passAccuracy: { home: number; away: number };
  events: {
    total: number;
    touchesHome: number;
    touchesAway: number;
    passesHomeSuccess: number;
    passesAwaySuccess: number;
  };
};

type SelectedView = "summary" | "shotQuality" | "pressing";
type TeamFilter = "both" | "home" | "away";

export default function MatchComparisonPage() {
  const { t } = useTranslation();
  const [matches, setMatches] = useState<Match[]>([]);
  const [selectedMatchId, setSelectedMatchId] = useState<string>("");
  const [selectedView, setSelectedView] = useState<SelectedView>("summary");
  const [teamFilter, setTeamFilter] = useState<TeamFilter>("both");
  const [analytics, setAnalytics] = useState<Analytics | null>(null);
  const [loadingAnalytics, setLoadingAnalytics] = useState(false);
  const [analyticsError, setAnalyticsError] = useState<string | null>(null);
  const [, setLoading] = useState(true);

  function getTeamName(team: { name: string } | null | undefined, teamName: string | null | undefined): string {
    if (team?.name) return team.name;
    if (teamName) return teamName;
    return t("unknown");
  }

  useEffect(() => {
    async function fetchMatches() {
      try {
        const res = await fetch("/api/matches");
        if (res.ok) {
          const data = await res.json();
          if (data.ok && Array.isArray(data.matches)) {
            const safeMatches = data.matches.map((match: any) => ({
              ...match,
              homeTeam: match.homeTeam || null,
              awayTeam: match.awayTeam || null,
              homeTeamName: match.homeTeamName || null,
              awayTeamName: match.awayTeamName || null,
            }));
            setMatches(safeMatches);
          }
        }
      } catch {
        // ignore
      } finally {
        setLoading(false);
      }
    }
    fetchMatches();
  }, []);

  const selectedMatch = useMemo(
    () => matches.find((m) => m.slug === selectedMatchId) ?? null,
    [matches, selectedMatchId]
  );

  useEffect(() => {
    if (!selectedMatch) {
      setAnalytics(null);
      setAnalyticsError(null);
      return;
    }
    let cancelled = false;
    setLoadingAnalytics(true);
    setAnalyticsError(null);
    (async () => {
      try {
        const res = await fetch(`/api/matches/${selectedMatch.id}/analytics`);
        const data = await res.json().catch(() => null);
        if (cancelled) return;
        if (!res.ok || !data?.ok) {
          setAnalytics(null);
          setAnalyticsError(data?.message || t("failedToLoadAnalytics") || "Failed to load analytics");
          return;
        }
        setAnalytics(data.analytics as Analytics);
      } catch {
        if (!cancelled) {
          setAnalytics(null);
          setAnalyticsError(t("failedToLoadAnalytics") || "Failed to load analytics");
        }
      } finally {
        if (!cancelled) setLoadingAnalytics(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [selectedMatch, t]);

  function pickSide<T>(home: T, away: T, both: (h: T, a: T) => string): string {
    if (teamFilter === "home") return formatNumber(home);
    if (teamFilter === "away") return formatNumber(away);
    return both(home, away);
  }

  function formatNumber(n: unknown): string {
    if (n === null || n === undefined) return "—";
    if (typeof n === "number") {
      if (Number.isInteger(n)) return n.toString();
      return (Math.round(n * 100) / 100).toString();
    }
    return String(n);
  }

  function bothLabel<T>(home: T, away: T): string {
    return `${formatNumber(home)} - ${formatNumber(away)}`;
  }

  return (
    <div className="min-h-screen bg-white dark:bg-slate-950">
      <header className="border-b border-slate-200 dark:border-slate-900/50 bg-white/80 dark:bg-slate-950/80 backdrop-blur-sm">
        <div className="mx-auto max-w-7xl px-6 py-6">
          <h1 className="text-3xl font-bold tracking-tight text-slate-900 dark:text-white mb-2">
            {t("matchComparison")}
          </h1>
          <p className="text-sm text-slate-600 dark:text-slate-400">{t("matchComparisonDescription")}</p>
        </div>
      </header>

      <main className="mx-auto max-w-7xl px-4 md:px-6 py-6 md:py-8">
        <div className="mb-8 rounded-xl border border-slate-200/80 dark:border-slate-800/50 bg-gradient-to-br from-white dark:from-slate-900/30 via-slate-50/30 dark:via-slate-950/30 to-white dark:to-slate-950/30 p-6 shadow-sm">
          <div className="flex flex-wrap items-end justify-between gap-4">
            <div className="flex flex-wrap gap-4">
              <div className="space-y-2">
                <label className="block text-xs font-semibold uppercase tracking-wide text-slate-400">Match</label>
                <div className="relative">
                  <select
                    value={selectedMatchId}
                    onChange={(e) => setSelectedMatchId(e.target.value)}
                    className="h-12 w-64 appearance-none rounded-lg border border-slate-200/80 dark:border-slate-800 bg-white dark:bg-slate-900/50 px-4 pr-10 text-sm font-medium text-slate-900 dark:text-white outline-none transition-all focus:border-emerald-500 dark:focus:border-emerald-500 focus:bg-white dark:focus:bg-slate-900 focus:ring-2 focus:ring-emerald-500/20 hover:border-slate-300 dark:hover:border-slate-700"
                  >
                    <option value="" className="bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400">
                      Select match
                    </option>
                    {matches.map((match) => {
                      const homeName = getTeamName(match.homeTeam, match.homeTeamName);
                      const awayName = getTeamName(match.awayTeam, match.awayTeamName);
                      return (
                        <option
                          key={match.id}
                          value={match.slug}
                          className="bg-white dark:bg-slate-900 text-slate-900 dark:text-white"
                        >
                          {homeName} {t("vs")} {awayName} - {match.competition || t("match")}
                        </option>
                      );
                    })}
                  </select>
                </div>
              </div>
              <div className="space-y-2">
                <label className="block text-xs font-semibold uppercase tracking-wide text-slate-400">{t("view")}</label>
                <div className="relative">
                  <select
                    value={selectedView}
                    onChange={(e) => setSelectedView(e.target.value as SelectedView)}
                    className="h-12 w-48 appearance-none rounded-lg border border-slate-200/80 dark:border-slate-800 bg-white dark:bg-slate-900/50 px-4 pr-10 text-sm font-medium text-slate-900 dark:text-white outline-none transition-all focus:border-emerald-500 dark:focus:border-emerald-500 focus:bg-white dark:focus:bg-slate-900 focus:ring-2 focus:ring-emerald-500/20 hover:border-slate-300 dark:hover:border-slate-700"
                  >
                    <option value="summary" className="bg-white dark:bg-slate-900 text-slate-900 dark:text-white">
                      {t("summary")}
                    </option>
                    <option value="shotQuality" className="bg-white dark:bg-slate-900 text-slate-900 dark:text-white">
                      {t("shotQuality")}
                    </option>
                    <option value="pressing" className="bg-slate-900 text-white">
                      {t("pressing")}
                    </option>
                  </select>
                </div>
              </div>
            </div>
            <div className="flex gap-3">
              <button
                type="button"
                onClick={() => setTeamFilter(teamFilter === "home" ? "both" : "home")}
                className={`flex items-center gap-2 rounded-lg border px-4 py-2 text-sm font-medium transition-all ${
                  teamFilter === "home"
                    ? "border-emerald-500/70 bg-emerald-500/30 text-emerald-200"
                    : "border-emerald-500/30 bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500/20"
                }`}
              >
                <span className="h-2.5 w-2.5 rounded-full bg-emerald-400" />
                {t("home")}
              </button>
              <button
                type="button"
                onClick={() => setTeamFilter(teamFilter === "away" ? "both" : "away")}
                className={`flex items-center gap-2 rounded-lg border px-4 py-2 text-sm font-medium transition-all ${
                  teamFilter === "away"
                    ? "border-emerald-500/70 bg-emerald-500/30 text-emerald-200"
                    : "border-emerald-500/30 bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500/20"
                }`}
              >
                <span className="h-2.5 w-2.5 rounded-full bg-emerald-400" />
                {t("away")}
              </button>
            </div>
          </div>
        </div>

        {/* Top row: xG / Shot quality */}
        <div className="grid gap-4 md:gap-6 md:grid-cols-2 lg:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)] mb-6">
          <div className="rounded-xl border border-slate-800/50 bg-gradient-to-br from-slate-900/50 to-slate-950/50 p-6">
            <div className="mb-4 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="rounded-lg bg-emerald-500/20 p-2">
                  <svg className="h-5 w-5 text-emerald-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                  </svg>
                </div>
                <div>
                  <h3 className="text-base font-bold text-white">{t("xgTimeline")}</h3>
                  <p className="text-xs text-slate-500 mt-0.5">
                    {selectedMatch ? `${selectedView}` : t("selectMatchToViewPhases")}
                  </p>
                </div>
              </div>
            </div>
            <div className="min-h-[200px] flex items-center justify-center">
              {!selectedMatch ? (
                <p className="text-sm text-slate-500 text-center">{t("selectMatchFromDropdown")}</p>
              ) : loadingAnalytics ? (
                <p className="text-sm text-slate-500 text-center">{t("loading")}</p>
              ) : analyticsError ? (
                <p className="text-sm text-red-400 text-center">{analyticsError}</p>
              ) : analytics ? (
                <div className="text-center">
                  <p className="text-[11px] uppercase tracking-wide text-slate-400 mb-2">{t("xg")}</p>
                  <p className="text-3xl font-bold text-white">
                    {pickSide(analytics.xg.home, analytics.xg.away, bothLabel)}
                  </p>
                  <Link
                    href={`/matches/${selectedMatch.slug}`}
                    className="mt-4 inline-flex items-center gap-2 rounded-lg bg-emerald-600 px-4 py-2 text-xs font-semibold text-white transition-all hover:bg-emerald-500"
                  >
                    {t("viewMatchAnalytics")}
                  </Link>
                </div>
              ) : (
                <p className="text-sm text-slate-500 text-center">—</p>
              )}
            </div>
          </div>

          <div className="rounded-xl border border-slate-800/50 bg-gradient-to-br from-slate-900/50 to-slate-950/50 p-6">
            <div className="mb-4 flex items-center gap-3">
              <div className="rounded-lg bg-amber-500/20 p-2">
                <svg className="h-5 w-5 text-amber-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 15l-2 5L9 9l11 4-5 2zm0 0l5 5M7.188 2.239l.777 2.897M5.136 7.965l-2.898-.777M13.95 4.05l-2.122 2.122m-5.657 5.656l-2.12 2.122" />
                </svg>
              </div>
              <h3 className="text-base font-bold text-white">{t("shotQualitySummary")}</h3>
            </div>
            <div className="min-h-[200px] flex flex-col items-center justify-center gap-3 text-sm text-slate-300">
              {!selectedMatch ? (
                <p className="text-sm text-slate-500 text-center">{t("selectMatchToViewShotQuality")}</p>
              ) : loadingAnalytics ? (
                <p className="text-sm text-slate-500">{t("loading")}</p>
              ) : analyticsError ? (
                <p className="text-sm text-red-400">{analyticsError}</p>
              ) : analytics ? (
                <div className="grid grid-cols-2 gap-4 text-center w-full">
                  <div>
                    <p className="text-[11px] uppercase tracking-wide text-slate-400">{t("shotsTotal") || "Shots"}</p>
                    <p className="text-2xl font-bold text-white mt-1">
                      {pickSide(analytics.shots.home.total, analytics.shots.away.total, bothLabel)}
                    </p>
                  </div>
                  <div>
                    <p className="text-[11px] uppercase tracking-wide text-slate-400">
                      {t("shotsOnTarget") || "On target"}
                    </p>
                    <p className="text-2xl font-bold text-white mt-1">
                      {pickSide(analytics.shots.home.onTarget, analytics.shots.away.onTarget, bothLabel)}
                    </p>
                  </div>
                  <div>
                    <p className="text-[11px] uppercase tracking-wide text-slate-400">{t("goals")}</p>
                    <p className="text-2xl font-bold text-white mt-1">
                      {pickSide(analytics.shots.home.goals, analytics.shots.away.goals, bothLabel)}
                    </p>
                  </div>
                  <div>
                    <p className="text-[11px] uppercase tracking-wide text-slate-400">{t("xa") || "xA"}</p>
                    <p className="text-2xl font-bold text-white mt-1">
                      {pickSide(analytics.xa.home, analytics.xa.away, bothLabel)}
                    </p>
                  </div>
                </div>
              ) : (
                <p className="text-sm text-slate-500">—</p>
              )}
            </div>
          </div>
        </div>

        {/* Bottom row: Pressing / High regains / Transitions */}
        <div className="grid gap-6 md:grid-cols-3">
          <MetricCard
            title={t("pressingIntensityPPDA")}
            iconColor="text-red-400"
            bgColor="bg-red-500/20"
            iconPath="M13 10V3L4 14h7v7l9-11h-7z"
            empty={!selectedMatch}
            loading={loadingAnalytics}
            error={analyticsError}
            placeholderText={t("selectMatchToViewPressingMetrics")}
            value={
              analytics
                ? pickSide(analytics.ppda.home, analytics.ppda.away, bothLabel)
                : null
            }
            label={t("ppda") || "PPDA"}
          />
          <MetricCard
            title={t("highRegainsLabel")}
            iconColor="text-purple-400"
            bgColor="bg-purple-500/20"
            iconPath="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"
            empty={!selectedMatch}
            loading={loadingAnalytics}
            error={analyticsError}
            placeholderText={t("selectMatchToViewRegainMetrics")}
            value={
              analytics
                ? pickSide(analytics.highRegains.home, analytics.highRegains.away, bothLabel)
                : null
            }
            label={t("highRegainsLabel")}
          />
          <MetricCard
            title={t("transitions")}
            iconColor="text-cyan-400"
            bgColor="bg-cyan-500/20"
            iconPath="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4"
            empty={!selectedMatch}
            loading={loadingAnalytics}
            error={analyticsError}
            placeholderText={t("selectMatchToViewTransitionMetrics")}
            value={
              analytics
                ? pickSide(
                    analytics.progressivePasses.home,
                    analytics.progressivePasses.away,
                    bothLabel
                  )
                : null
            }
            label={t("progressivePasses") || "Progressive passes"}
          />
        </div>
      </main>
    </div>
  );
}

function MetricCard({
  title,
  iconColor,
  bgColor,
  iconPath,
  empty,
  loading,
  error,
  placeholderText,
  value,
  label,
}: {
  title: string;
  iconColor: string;
  bgColor: string;
  iconPath: string;
  empty: boolean;
  loading: boolean;
  error: string | null;
  placeholderText: string;
  value: string | null;
  label: string;
}) {
  return (
    <div className="rounded-xl border border-slate-800/50 bg-gradient-to-br from-slate-900/50 to-slate-950/50 p-6">
      <div className="mb-4 flex items-center gap-3">
        <div className={`rounded-lg ${bgColor} p-2`}>
          <svg className={`h-5 w-5 ${iconColor}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={iconPath} />
          </svg>
        </div>
        <h3 className="text-base font-bold text-white">{title}</h3>
      </div>
      <div className="min-h-[150px] flex flex-col items-center justify-center text-center gap-2">
        {empty ? (
          <p className="text-sm text-slate-500">{placeholderText}</p>
        ) : loading ? (
          <p className="text-sm text-slate-500">Loading...</p>
        ) : error ? (
          <p className="text-sm text-red-400">{error}</p>
        ) : value ? (
          <>
            <p className="text-[11px] uppercase tracking-wide text-slate-400">{label}</p>
            <p className="text-3xl font-bold text-white">{value}</p>
          </>
        ) : (
          <p className="text-sm text-slate-500">—</p>
        )}
      </div>
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { useEffect, useState, useTransition } from "react";
import { useTheme } from "@/lib/theme";
import { useTranslation } from "@/lib/i18n";

function ThemeSelector() {
  const { theme, setTheme } = useTheme();
  const { t } = useTranslation();

  return (
    <select 
      value={theme}
      onChange={(e) => setTheme(e.target.value as "light" | "dark")}
      className="fa-input focus:border-purple-500/50 focus:ring-purple-500/20"
    >
      <option value="dark">{t("dark")}</option>
      <option value="light">{t("light")}</option>
    </select>
  );
}

type AccountState = {
  name: string;
  email: string;
  role: string;
  joinedAt?: string | null;
  emailVerified?: boolean;
  phone?: string | null;
  phoneVerified?: boolean;
  profilePicture?: string | null;
  notificationPreference?: "all" | "important" | "muted";
};

type SubscriptionState = {
  plan: string | null;
  status: string;
  renewsAt: string | null;
} | null;

export default function SettingsPage() {
  const { t, language, setLanguage } = useTranslation();
  const router = useRouter();
  const [account, setAccount] = useState<AccountState | null>(null);
  const [loadingAccount, setLoadingAccount] = useState(true);
  const [saveMessage, setSaveMessage] = useState<string | null>(null);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [isSaving, startSaving] = useTransition();
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [pwdMessage, setPwdMessage] = useState<string | null>(null);
  const [pwdError, setPwdError] = useState<string | null>(null);
  const [isPwdSaving, startPwdSaving] = useTransition();
  const [phone, setPhone] = useState("");
  const [phoneCode, setPhoneCode] = useState("");
  const [phoneMessage, setPhoneMessage] = useState<string | null>(null);
  const [phoneError, setPhoneError] = useState<string | null>(null);
  const [isPhoneSubmitting, startPhoneSubmitting] = useTransition();
  const [uploadingPicture, setUploadingPicture] = useState(false);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [uploadSuccess, setUploadSuccess] = useState<string | null>(null);
  const [subscription, setSubscription] = useState<SubscriptionState>(null);
  const [notificationPref, setNotificationPref] = useState<"all" | "important" | "muted">("all");
  const [savingNotification, setSavingNotification] = useState(false);

  function getPasswordStrengthLabel(pwd: string): { label: string; level: "weak" | "medium" | "strong" } {
    let score = 0;
    if (pwd.length >= 8) score++;
    if (/[0-9]/.test(pwd)) score++;
    if (/[A-Z]/.test(pwd) || /[^a-zA-Z0-9]/.test(pwd)) score++;
    if (score <= 1) return { label: "Weak", level: "weak" };
    if (score === 2) return { label: "Medium", level: "medium" };
    return { label: "Strong", level: "strong" };
  }

  function handleSendPhoneCode(e: React.FormEvent) {
    e.preventDefault();
    if (!account) return;
    setPhoneMessage(null);
    setPhoneError(null);

    const value = phone || account.phone || "";
    if (!value) {
      setPhoneError(t("pleaseEnterPhoneNumber"));
      return;
    }

    startPhoneSubmitting(async () => {
      try {
        const res = await fetch("/api/auth/phone/send-code", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "x-user-email": account.email,
          },
          body: JSON.stringify({ phone: value }),
        });
        const data = (await res.json().catch(() => ({}))) as { ok?: boolean; error?: string };
        if (!res.ok || !data.ok) {
          setPhoneError(data.error || "Failed to send SMS code.");
          return;
        }
        setPhoneMessage(t("ifSmsConfigured"));
      } catch {
        setPhoneError("Network error while sending code.");
      }
    });
  }

  function handleVerifyPhoneCode(e: React.FormEvent) {
    e.preventDefault();
    if (!account) return;
    setPhoneMessage(null);
    setPhoneError(null);

    if (!phoneCode) {
      setPhoneError(t("pleaseEnterVerificationCode"));
      return;
    }

    startPhoneSubmitting(async () => {
      try {
        const res = await fetch("/api/auth/phone/verify-code", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "x-user-email": account.email,
          },
          body: JSON.stringify({ code: phoneCode }),
        });
        const data = (await res.json().catch(() => ({}))) as { ok?: boolean; error?: string };
        if (!res.ok || !data.ok) {
          setPhoneError(data.error || "Failed to verify code.");
          return;
        }
        setPhoneMessage(t("phoneNumberVerified"));
        setAccount((prev) => (prev ? { ...prev, phoneVerified: true } : prev));
      } catch {
        setPhoneError("Network error while verifying code.");
      }
    });
  }

  const pwdStrength = newPassword ? getPasswordStrengthLabel(newPassword) : null;

  useEffect(() => {
    async function loadAccount() {
      try {
        const res = await fetch("/api/account/me");
        if (!res.ok) {
          router.replace("/auth/login");
          return;
        }
        const data = (await res.json()) as {
          ok?: boolean;
          user?: {
            email?: string;
            name?: string | null;
            role?: string | null;
            createdAt?: string;
            emailVerified?: boolean;
            phone?: string | null;
            phoneVerified?: boolean;
            profilePicture?: string | null;
          };
        };
        if (res.ok && data.ok && data.user?.email) {
          const u = data.user as {
            email: string;
            name?: string | null;
            role?: string | null;
            createdAt?: string;
            emailVerified?: boolean;
            phone?: string | null;
            phoneVerified?: boolean;
            profilePicture?: string | null;
            notificationPreference?: string;
          };
          const pref =
            (u.notificationPreference === "important" ||
            u.notificationPreference === "muted" ||
            u.notificationPreference === "all"
              ? u.notificationPreference
              : "all") as "all" | "important" | "muted";
          setAccount({
            email: u.email,
            name: u.name || "",
            role: u.role || t("headCoach"),
            joinedAt: u.createdAt ?? null,
            emailVerified: u.emailVerified,
            phone: u.phone || "",
            phoneVerified: u.phoneVerified,
            profilePicture: u.profilePicture || null,
            notificationPreference: pref,
          });
          setNotificationPref(pref);
        } else {
          router.replace("/auth/login");
        }
      } catch {
        router.replace("/auth/login");
      } finally {
        setLoadingAccount(false);
      }
    }
    loadAccount();
  }, [router]);

  useEffect(() => {
    let cancelled = false;
    async function loadSubscription() {
      try {
        const res = await fetch("/api/billing/subscription");
        if (!res.ok) return;
        const data = (await res.json().catch(() => null)) as
          | { ok?: boolean; plan?: string | null; status?: string; renewsAt?: string | null }
          | null;
        if (cancelled || !data?.ok) return;
        setSubscription({
          plan: data.plan ?? null,
          status: data.status ?? "none",
          renewsAt: data.renewsAt ?? null,
        });
      } catch {
        // ignore - subscription is optional
      }
    }
    loadSubscription();
    return () => {
      cancelled = true;
    };
  }, []);

  async function handleNotificationChange(value: "all" | "important" | "muted") {
    setNotificationPref(value);
    setSavingNotification(true);
    try {
      const res = await fetch("/api/account/me", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ notificationPreference: value }),
      });
      if (!res.ok) {
        // Roll back optimistic update on failure
        setNotificationPref(account?.notificationPreference || "all");
      } else if (account) {
        setAccount({ ...account, notificationPreference: value });
      }
    } catch {
      setNotificationPref(account?.notificationPreference || "all");
    } finally {
      setSavingNotification(false);
    }
  }

  function planDisplayLabel(plan: string | null): string {
    if (!plan) return t("free") || "Free";
    const map: Record<string, string> = {
      free: t("free") || "Free",
      starter: t("starter") || "Starter",
      pro_monthly: t("pro") || "Pro",
      pro: t("pro") || "Pro",
      elite: t("elite") || "Elite",
    };
    return map[plan] || plan;
  }

  async function handleLogout() {
    try {
      const res = await fetch("/api/auth/logout", { method: "POST" });
      const data = (await res.json().catch(() => null)) as { redirectTo?: string | null } | null;
      if (data?.redirectTo) {
        window.location.href = data.redirectTo;
        return;
      }
    } catch {
      // ignore
    }
    router.push("/auth/login");
    router.refresh();
  }

  async function handlePictureUpload(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploadError(null);
    setUploadSuccess(null);
    setUploadingPicture(true);

    try {
      const formData = new FormData();
      formData.append("file", file);

      const res = await fetch("/api/upload/profile-picture", {
        method: "POST",
        body: formData,
      });

      const data = await res.json();

      if (res.ok && data.ok) {
        setUploadSuccess(t("profilePictureUploadedSuccessfully"));
        // Update account state with new picture
        if (account) {
          setAccount({ ...account, profilePicture: data.url });
        }
        // Refresh page after 1 second
        setTimeout(() => {
          window.location.reload();
        }, 1000);
      } else {
        setUploadError(data.message || "Failed to upload picture");
      }
    } catch (error) {
      setUploadError("Network error. Please try again.");
    } finally {
      setUploadingPicture(false);
      // Reset input
      e.target.value = "";
    }
  }

  function handleAccountSave(e: React.FormEvent) {
    e.preventDefault();
    if (!account) return;
    setSaveMessage(null);
    setSaveError(null);

    startSaving(async () => {
      try {
        const res = await fetch("/api/account/me", {
          method: "PATCH",
          headers: {
            "Content-Type": "application/json",
            "x-user-email": account.email,
          },
          body: JSON.stringify({ name: account.name, role: account.role }),
        });
        const data = (await res.json()) as { ok?: boolean; message?: string };
        if (!res.ok || !data.ok) {
          setSaveError(data.message || "Failed to update account");
          return;
        }
        setSaveMessage(t("accountDetailsUpdated"));
      } catch {
        setSaveError("Network error while saving");
      }
    });
  }

  function handlePasswordChange(e: React.FormEvent) {
    e.preventDefault();
    if (!account) return;
    setPwdMessage(null);
    setPwdError(null);

    if (!currentPassword || !newPassword) {
      setPwdError("Please fill in all password fields");
      return;
    }
    if (newPassword !== confirmPassword) {
      setPwdError("New passwords do not match");
      return;
    }

    startPwdSaving(async () => {
      try {
        const res = await fetch("/api/auth/change-password", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "x-user-email": account.email,
          },
          body: JSON.stringify({ currentPassword, newPassword }),
        });
        const data = (await res.json()) as { ok?: boolean; message?: string };
        if (!res.ok || !data.ok) {
          setPwdError(data.message || "Failed to update password");
          return;
        }
        setPwdMessage(t("passwordUpdatedSuccessfully"));
        setCurrentPassword("");
        setNewPassword("");
        setConfirmPassword("");
      } catch {
        setPwdError("Network error while updating password");
      }
    });
  }

  return (
    <div className="grid gap-6 md:gap-8 md:grid-cols-[minmax(0,2fr)_minmax(0,1.3fr)] text-xs text-text">
      <div className="space-y-6">
        {/* Header - Premium */}
        <div className="fa-panel-header">
          <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/5 via-transparent to-purple-500/5"></div>
          <div className="relative space-y-4">
            <div className="flex items-center gap-3">
