"use client";

import { useEffect, useState } from "react";
import { useRouter, useParams } from "next/navigation";
import { useTranslation } from "@/lib/i18n";
import Link from "next/link";

type Team = {
  id: number;
  name: string;
  league: string | null;
  style: string | null;
  _count: {
    players: number;
    homeGames: number;
    awayGames: number;
  };
};

export default function TeamDetailsPage() {
  const { t } = useTranslation();
  const router = useRouter();
  const params = useParams();
  const teamId = params?.id ? parseInt(params.id as string) : null;
  const [team, setTeam] = useState<Team | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!teamId || isNaN(teamId)) {
      setError("Invalid team ID");
      setLoading(false);
      return;
    }

    async function fetchTeam() {
      try {
        const res = await fetch(`/api/teams/${teamId}`);
        if (res.ok) {
          const data = await res.json();
          if (data.ok && data.team) {
            setTeam(data.team);
          } else {
            setError("Team not found");
          }
        } else if (res.status === 403) {
          setError("You don't have access to this team");
        } else {
          setError("Failed to load team");
        }
      } catch (err) {
        setError("Network error");
      } finally {
        setLoading(false);
      }
    }

    fetchTeam();
  }, [teamId]);

  if (loading) {
    return (
      <div className="space-y-6 text-xs text-slate-200">
        <div className="h-96 animate-pulse rounded-xl bg-slate-900" />
      </div>
    );
  }

  if (error || !team) {
    return (
      <div className="space-y-6 text-xs text-slate-200">
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 p-6">
          <h2 className="text-lg font-semibold text-red-400 mb-2">{t("error")}</h2>
          <p className="text-sm text-red-300">{error || t("teamNotFound")}</p>
          <Link
            href="/teams"
            className="mt-4 inline-block rounded-lg bg-slate-800 px-4 py-2 text-sm text-slate-200 hover:bg-slate-700"
          >
            {t("backToTeams")}
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 text-xs text-slate-200">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <Link
            href="/teams"
            className="text-sm text-slate-400 hover:text-slate-200 mb-2 inline-block"
          >
            ← {t("backToTeams")}
          </Link>
          <h1 className="text-2xl font-bold text-slate-50">{team.name}</h1>
          {team.league && (
            <p className="text-sm text-slate-400 mt-1">{team.league}</p>
          )}
        </div>
        <Link
          href="/admin/staff"
          className="rounded-lg border border-emerald-500/30 bg-gradient-to-r from-emerald-500/20 to-emerald-600/20 px-4 py-2 text-sm font-semibold text-emerald-200 transition-all hover:from-emerald-500/30 hover:to-emerald-600/30 hover:border-emerald-500/50"
        >
{t("inviteStaff")}
        </Link>
      </div>

      {/* Team Stats */}
      <div className="grid grid-cols-3 gap-4">
        <div className="rounded-xl border border-slate-800/50 bg-slate-900/50 p-4">
          <p className="text-[10px] text-slate-400 uppercase tracking-wide">{t("players")}</p>
          <p className="text-2xl font-bold text-emerald-400 mt-1">{team._count.players}</p>
        </div>
        <div className="rounded-xl border border-slate-800/50 bg-slate-900/50 p-4">
          <p className="text-[10px] text-slate-400 uppercase tracking-wide">{t("matches")}</p>
          <p className="text-2xl font-bold text-sky-400 mt-1">{team._count.homeGames + team._count.awayGames}</p>
        </div>
        <div className="rounded-xl border border-slate-800/50 bg-slate-900/50 p-4">
          <p className="text-[10px] text-slate-400 uppercase tracking-wide">{t("style")}</p>
          <p className="text-sm font-semibold text-slate-200 mt-1">{team.style || t("notSet")}</p>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="rounded-xl border border-slate-800/50 bg-slate-900/50 p-6">
        <h2 className="text-sm font-semibold text-white mb-4">{t("quickActions")}</h2>
        <div className="grid grid-cols-2 gap-3">
          <Link
            href={`/teams?teamId=${team.id}`}
            className="rounded-lg border border-slate-700/50 bg-slate-800/50 px-4 py-3 text-sm font-medium text-slate-200 hover:bg-slate-800 transition-colors text-center"
          >
{t("managePlayers")}
          </Link>
          <Link
            href="/admin/staff"
            className="rounded-lg border border-emerald-500/30 bg-gradient-to-r from-emerald-500/20 to-emerald-600/20 px-4 py-3 text-sm font-semibold text-emerald-200 transition-all hover:from-emerald-500/30 hover:to-emerald-600/30 text-center"
          >
  {t("inviteStaff")}
          </Link>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import { format } from "date-fns";
import toast, { Toaster } from "react-hot-toast";
import { useTranslation } from "@/lib/i18n";

type Team = {
  id: number;
  name: string;
  league: string | null;
};

type OpponentTeam = {
  name: string;
  isOpponent: true;
};

type TeamStats = {
  matches: number;
  wins: number;
  draws: number;
  losses: number;
  goals: number;
  xG: number;
  shots: number;
  shotsOnTarget: number;
  passes: number;
  successfulPasses: number;
  passAccuracy: number;
  touches: number;
  tackles: number;
  interceptions: number;
  possession: number;
  goalsPerMatch: number;
  xGPerMatch: number;
};

type HeadToHeadMatch = {
  id: number;
  slug: string;
  date: string;
  competition: string;
  venue: string | null;
  homeTeamId: number | null;
  awayTeamId: number | null;
  homeTeamName: string | null;
  awayTeamName: string | null;
  scoreHome: number | null;
  scoreAway: number | null;
  xgHome: number | null;
  xgAway: number | null;
};

type ComparisonData = {
  teams: {
    team1: Team;
    team2: Team;
  };
  stats: {
    team1: TeamStats;
    team2: TeamStats;
  };
  headToHead: {
    matches: number;
    team1Wins: number;
    team2Wins: number;
    draws: number;
    team1Goals: number;
    team2Goals: number;
    matchList: HeadToHeadMatch[];
  };
  formations: {
    team1: {
      mostUsed: string;
      all: Array<{ formation: string; count: number }>;
    };
    team2: {
      mostUsed: string;
      all: Array<{ formation: string; count: number }>;
    };
  };
};

function getTeamName(team: { name: string } | null, teamName: string | null | undefined): string {
  if (team?.name) return team.name;
  if (teamName) return teamName;
  return "Unknown";
}

export default function TeamComparePage() {
  const { t } = useTranslation();
  const router = useRouter();
  const searchParams = useSearchParams();
  const [teams, setTeams] = useState<Team[]>([]);
  const [opponentTeams, setOpponentTeams] = useState<OpponentTeam[]>([]);
  const [team1Id, setTeam1Id] = useState<number | null>(null);
  const [team1Name, setTeam1Name] = useState<string | null>(null);
  const [team2Id, setTeam2Id] = useState<number | null>(null);
  const [team2Name, setTeam2Name] = useState<string | null>(null);
  const [comparisonData, setComparisonData] = useState<ComparisonData | null>(null);
  const [loading, setLoading] = useState(false);

  // Load teams and opponent teams
  useEffect(() => {
    // Load registered teams
    fetch("/api/teams")
      .then((res) => res.json())
      .then((data) => {
        if (data.ok && data.teams) {
          setTeams(data.teams);
        }
      })
      .catch(() => {
        console.error("Failed to load teams");
      });

    // Load opponent teams from matches
    fetch("/api/matches")
      .then((res) => res.json())
      .then((data) => {
        if (data.ok && data.matches) {
          const opponents = new Set<string>();
          data.matches.forEach((match: any) => {
            if (match.homeTeamName && !match.homeTeamId) {
              opponents.add(match.homeTeamName);
            }
            if (match.awayTeamName && !match.awayTeamId) {
              opponents.add(match.awayTeamName);
            }
          });
          setOpponentTeams(
            Array.from(opponents).map((name) => ({ name, isOpponent: true as const }))
          );
        }
      })
      .catch(() => {
        console.error("Failed to load opponent teams");
      });
  }, []);

  // Load team IDs/names from URL
  useEffect(() => {
    const id1 = searchParams.get("team1");
    const id2 = searchParams.get("team2");
    const name1 = searchParams.get("team1Name");
    const name2 = searchParams.get("team2Name");

    if (id1) {
      const team1 = parseInt(id1);
      if (!isNaN(team1)) {
        setTeam1Id(team1);
        setTeam1Name(null);
      }
    } else if (name1) {
      setTeam1Id(null);
      setTeam1Name(name1);
    }

    if (id2) {
      const team2 = parseInt(id2);
      if (!isNaN(team2)) {
        setTeam2Id(team2);
        setTeam2Name(null);
      }
    } else if (name2) {
      setTeam2Id(null);
      setTeam2Name(name2);
    }
  }, [searchParams]);

  // Fetch comparison when teams are selected
  useEffect(() => {
    const hasTeam1 = team1Id || team1Name;
    const hasTeam2 = team2Id || team2Name;
    if (hasTeam1 && hasTeam2) {
      // Check if not comparing same team
      if (
        (team1Id && team2Id && team1Id === team2Id) ||
        (team1Name && team2Name && team1Name === team2Name)
      ) {
        return;
      }
      fetchComparison();
    }
  }, [team1Id, team1Name, team2Id, team2Name]);

  async function fetchComparison() {
    const hasTeam1 = team1Id || team1Name;
    const hasTeam2 = team2Id || team2Name;
    if (!hasTeam1 || !hasTeam2) return;

    setLoading(true);
    try {
      const res = await fetch("/api/teams/compare", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          team1Id: team1Id || undefined,
          team1Name: team1Name || undefined,
          team2Id: team2Id || undefined,
          team2Name: team2Name || undefined,
        }),
      });

      if (res.ok) {
        const data = await res.json();
        if (data.ok) {
          setComparisonData(data);
          // Update URL
          const params = new URLSearchParams();
          if (team1Id) params.set("team1", team1Id.toString());
          else if (team1Name) params.set("team1Name", team1Name);
          if (team2Id) params.set("team2", team2Id.toString());
          else if (team2Name) params.set("team2Name", team2Name);
          router.push(`/teams/compare?${params.toString()}`, { scroll: false });
        } else {
          toast.error(data.message || "Failed to fetch comparison");
        }
      } else {
        const errorData = await res.json().catch(() => ({ message: "Unknown error" }));
        toast.error(errorData.message || "Failed to fetch comparison");
      }
    } catch (error) {
      console.error("[TeamCompare] Error:", error);
      toast.error("Network error");
    } finally {
      setLoading(false);
    }
  }

  function handleCompare() {
    const hasTeam1 = team1Id || team1Name;
    const hasTeam2 = team2Id || team2Name;
    if (!hasTeam1 || !hasTeam2) {
      toast.error("Please select both teams");
      return;
    }
    if (
      (team1Id && team2Id && team1Id === team2Id) ||
      (team1Name && team2Name && team1Name === team2Name)
    ) {
      toast.error("Please select two different teams");
      return;
    }
    fetchComparison();
  }

  if (!comparisonData) {
    return (
      <>
        <Toaster position="top-right" />
        <div className="min-h-screen bg-slate-950">
          {/* Minimal Header */}
          <header className="border-b border-slate-900/50 bg-slate-950/80 backdrop-blur-sm">
            <div className="mx-auto max-w-7xl px-6 py-4">
              <div className="flex items-center gap-4">
                <Link 
                  href="/teams" 
                  className="text-sm font-medium text-slate-500 hover:text-white transition-colors"
                >
                  ← Teams
                </Link>
                <div className="h-4 w-px bg-slate-800" />
                <h1 className="text-lg font-semibold text-slate-900 dark:text-white">{t("teamComparison")}</h1>
              </div>
            </div>
          </header>

          {/* Main Content - Instat/Wyscout Style */}
          <main className="mx-auto max-w-4xl px-6 py-12">
            <div className="mb-8">
              <h2 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">{t("selectTeams")}</h2>
