                                    if (teamDetails) {
                                      setEditingTeam(teamDetails);
                                      setValue("name", teamDetails.name);
                                      setValue("league", teamDetails.league || "");
                                      setValue("style", teamDetails.style || "");
                                      setShowAddTeam(true);
                                    }
                                    setOpenActionsMenu(null);
                                  }}
