                    </div>

                    {/* Statistics Grid */}
                    <div className="grid grid-cols-3 gap-3">
                      <div className="rounded-lg border border-emerald-500/20 bg-emerald-500/5 p-3 text-center">
                        <div className="mb-1 flex items-center justify-center">
