                <button
                  onClick={() => {
                    setShowAddPlayersModal(null);
                    setSelectedPlayerIds([]);
                  }}
                  className="h-6 w-6 rounded-full bg-slate-100 dark:bg-slate-900 text-[11px] text-slate-600 dark:text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-800"
